    "home.about.body": "Shyam Jagat is a spiritual and social organization inspired by Baba Shyam, dedicated to serving humanity through faith and action. We uplift communities across areas: quality education for children, skill training for employment, free meals for food security, safe shelter for the homeless, free healthcare camps, and women empowerment programs. Together, we aim to build a compassionate and self-reliant society where everyone can thrive with dignity.",
