    "home.baba.body": "\"Born as Barbarik, the legendary grandson of Bhima, he possessed unparalleled warrior strength. Yet, his greatest act was the supreme sacrifice of his own head for the victory of Dharma (truth). Pleased by his selfless devotion, Lord Krishna blessed him with his own name—Shyam—decreeing that he would be revered in Kalyug as the ultimate savior of the defeated.\"",
