    "home.success.title": "Success Stories",
    "home.success.subtitle": "Real lives, real impact — stories of hope and transformation.",
    "home.success.t1": "The scholarship from Shyam Jagat changed my life. Today I am a software engineer and I owe it all to their support and faith in me.",
    "home.success.t2": "Through the Employment Portal, I found a job that matches my skills. Shyam Jagat didn't just give me work — they gave me purpose and confidence.",
    "home.success.t3": "I was alone and struggling. The Old Age Home gave me a family again. The warmth, care, and respect I receive here is beyond words.",
    "home.why.title": "Why Choose Shyam Jagat",
    "home.why.subtitle": "Built on faith, driven by purpose, and committed to lasting change.",
    "home.why.f1.title": "Faith Driven",
