    "baba.hero.title": "The Divine Legacy of Baba Shyam",
    "baba.hero.subtitle": "“Sachche dil se jo yaad kare, Baba Shyam uski sunte hain.”",
    "baba.hero.cta1": "Explore His Journey",
    "baba.hero.cta2": "Visit Khatu Temple",
    "baba.story.title": "The Divine Story of Khatu Shyam Ji",
    "baba.story.p1": "Khatu Shyam Ji, revered as Baba Shyam, is worshipped as an incarnation of Lord Krishna's blessing to Barbarika, the grandson of the mighty Bhima. Known as the “King of Kalyug,” he is the deity of the poor, the wronged, and the hopeless.",
    "baba.story.p2": "His temple in Khatu, Rajasthan, draws millions of devotees each year who come seeking his blessings, believing that he answers every sincere prayer, especially those made from a place of true devotion and surrender.",
    "baba.story.p3": "Baba Shyam's story is one of ultimate sacrifice, unwavering faith, and boundless compassion — a story that continues to inspire generations of devotees across the world.",
    "baba.story.stat1.label": "Annual Devotees",
    "baba.story.stat2.label": "Years of Faith",
    "baba.story.stat3.label": "Sacred Temple",
    "baba.history.title": "The Sacred History",
    "baba.history.p1": "Barbarika was the son of Ghatotkacha and grandson of Bhima, one of the five Pandavas. From a young age, he was blessed with extraordinary courage and was trained in the art of warfare by none other than Lord Shiva himself.",
    "baba.history.p2": "He was granted three invincible arrows by Lord Agni, which could destroy any enemy and always returned to his quiver. With this power, Barbarika vowed to fight for the weaker side in any battle to ensure fairness.",
    "baba.history.p3": "When the Mahabharata war approached, Lord Krishna tested Barbarika's resolve. Understanding that Barbarika's power alone could end the war in a single day, Krishna asked for his head as alms, disguised as a Brahmin.",
    "baba.history.p4": "Barbarika, recognizing Krishna's true form, offered his head willingly, fulfilling his promise of ultimate sacrifice. Pleased with his devotion, Krishna blessed him to be worshipped in Kalyug under the name Shyam.",
    "baba.history.quote": "“Whoever worships Barbarika's head with a true heart shall receive blessings equal to worshipping me myself.”",
    "baba.journey.title": "The Divine Journey of Barbarika",
    "baba.journey.subtitle": "From a mighty warrior to the beloved deity of Kalyug",
    "baba.journey.footer1": "Faith. Devotion. Sacrifice. Blessings.",
    "baba.journey.footer2": "Jai Shree Shyam!",
    "baba.journey.step1.title": "Birth",
    "baba.journey.step1.desc": "Born to Ghatotkacha and Ahilyavati, grandson of the mighty Bhima, destined for greatness.",
    "baba.journey.step2.title": "Training from Lord Shiva",
    "baba.journey.step2.desc": "Blessed with unmatched skills in warfare and archery directly from Lord Shiva.",
    "baba.journey.step3.title": "Three Divine Arrows",
    "baba.journey.step3.desc": "Received three invincible arrows from Lord Agni, capable of ending any war instantly.",
    "baba.journey.step4.title": "Meeting Lord Krishna",
    "baba.journey.step4.desc": "Encountered Lord Krishna, who tested his devotion and true understanding of dharma.",
    "baba.journey.step5.title": "The Supreme Sacrifice",
    "baba.journey.step5.desc": "Offered his own head as the ultimate act of devotion to ensure fairness in the great war.",
    "baba.journey.step6.title": "Witness of Mahabharata",
    "baba.journey.step6.desc": "His head watched the entire Mahabharata war from atop a hill, seeing all that unfolded.",
    "baba.journey.step7.title": "Blessed as Baba Shyam",
    "baba.journey.step7.desc": "Krishna blessed him to be worshipped in Kalyug as Shyam, granter of every true prayer.",
    "baba.teachings.title": "Teachings of Baba Shyam",
    "baba.teachings.subtitle": "Timeless wisdom for a devoted life",
    "baba.teachings.t1.title": "Faith",
    "baba.teachings.t1.desc": "Unwavering belief in the divine, even in the darkest of times.",
    "baba.teachings.t2.title": "Humility",
    "baba.teachings.t2.desc": "True greatness lies in surrender and humbleness before the divine.",
    "baba.teachings.t3.title": "Sacrifice",
    "baba.teachings.t3.desc": "The highest form of devotion is selfless sacrifice for a greater good.",
    "baba.teachings.t4.title": "Compassion",
    "baba.teachings.t4.desc": "Baba Shyam teaches us to show kindness to all beings, regardless of status.",
    "baba.teachings.t5.title": "Truth",
    "baba.teachings.t5.desc": "Standing for what is right, even when it is the harder path to take.",
    "baba.teachings.t6.title": "Equality",
    "baba.teachings.t6.desc": "He blesses the poor and rich alike, seeing no difference among true devotees.",
    "baba.teachings.t7.title": "Seva",
    "baba.teachings.t7.desc": "Selfless service to others is the truest form of worship.",
    "baba.abode.badge": "Sacred Pilgrimage",
    "baba.abode.title": "The Divine Abode of Khatu Shyam Ji",
    "baba.abode.p1": "The Khatu Shyam Ji temple, located in the small town of Khatu in Sikar district, Rajasthan, stands as one of the most revered pilgrimage sites in India, drawing devotees from every corner of the country and beyond.",
    "baba.abode.p2": "The temple complex, with its intricate architecture and serene atmosphere, offers a spiritual sanctuary where devotees come to seek blessings, fulfill vows, and experience the divine presence of Baba Shyam.",
    "baba.abode.p3": "Every year, especially during the Falgun Mela, the temple witnesses an extraordinary gathering of devotees, each carrying their own story of faith, hope, and gratitude toward Baba Shyam.",
    "baba.abode.chip1": "📍 Sikar, Rajasthan",
    "baba.abode.chip2": "🕐 Open 4 AM – 10 PM",
    "baba.abode.chip3": "🎪 Falgun Mela (Annual)",
    "baba.miracles.title": "Miracles & Divine Blessings",
    "baba.miracles.subtitle": "Stories of faith from devotees whose prayers were answered",
    "baba.miracles.q1": "“When all hope seemed lost, I turned to Baba Shyam. My prayers were answered in ways I never imagined possible. His blessings changed my life forever.”",
    "baba.miracles.q2": "“I have witnessed countless miracles through my devotion to Baba Shyam. He truly is the saviour of the hopeless and the answerer of every true prayer.”",
    "baba.miracles.q3": "“Baba Shyam's grace helped my family through our darkest hour. Our faith in him has only grown stronger with each passing year.”",
    "baba.miracles.stat1.label": "Devotees Annually",
    "baba.miracles.stat2.label": "Years of Worship",
    "baba.miracles.stat3.label": "Daily Prayers",
    "baba.miracles.stat4.label": "Miracles of Faith",
    "baba.festivals.title": "Festivals & Celebrations",
    "baba.festival1.title": "Falgun Mela",
    "baba.festival1.when": "March (Annual)",
    "baba.festival1.desc": "The grandest celebration, drawing millions of devotees over several days of devotion and festivity.",
    "baba.festival2.title": "Janmashtami",
    "baba.festival2.when": "August",
    "baba.festival2.desc": "Celebrating Lord Krishna's birth with grand festivities and midnight prayers at the temple.",
