    "baba.festival3.desc": "Special prayers and fasting observed by devotees, seeking Baba Shyam's blessings.",
    "baba.festival4.title": "Bhajan Sandhya",
    "baba.festival4.when": "Every Evening",
    "baba.festival4.desc": "Devotional music sessions filling the temple with soulful hymns and prayers.",
    "baba.festival5.title": "Shyam Katha",
    "baba.festival5.when": "Weekly",
    "baba.festival5.desc": "Storytelling sessions narrating the divine tales and teachings of Baba Shyam.",
    "baba.rituals.title": "Daily Temple Rituals",
    "baba.rituals.subtitle": "The sacred rhythm of devotion at Khatu Shyam Ji temple",
    "baba.ritual1.title": "Mangla Aarti",
    "baba.ritual1.desc": "The first prayer of the day, welcoming Baba Shyam with devotion at dawn.",
    "baba.ritual2.title": "Shringar Darshan",
    "baba.ritual2.desc": "Devotees witness Baba Shyam adorned in beautiful attire and ornaments.",
    "baba.ritual3.title": "Rajbhog",
    "baba.ritual3.desc": "A grand offering of food is presented to Baba Shyam at midday.",
    "baba.ritual4.title": "Afternoon Darshan",
