    "about.hero.mantra": "|| जय श्री श्याम ||",
    "about.hero.title": "About Shyam Jagat",
    "about.hero.subtitle": "Serving Humanity with Faith, Compassion, and Purpose",
    "about.whoWeAre.title": "Who We Are",
    "about.whoWeAre.p1": "Shyam Jagat is a spiritual and social organization inspired by the divine teachings and blessings of Baba Shyam. Our mission is to transform lives by combining devotion with meaningful social service, creating a community where compassion, dignity, and opportunity are accessible to everyone.",
    "about.whoWeAre.p2": "We believe that true devotion is expressed through selfless service. Every initiative we undertake is driven by the values of kindness, equality, and humanity, helping individuals and families build a brighter future.",
    "about.vision.title": "Our Vision",
    "about.vision.text": "To build a compassionate, empowered, and self-reliant society where every individual has access to education, healthcare, food, shelter, employment opportunities, and a life of dignity under the blessings of Baba Shyam.",
    "about.mission.title": "Our Mission",
    "about.mission.text": "Our mission is to serve society through sustainable initiatives that uplift lives, strengthen communities, and inspire people to contribute towards a better tomorrow. We strive to create lasting social impact by empowering individuals with the resources, support, and opportunities they need to thrive.",
    "about.belief.title": "Our Belief",
    "about.belief.text": "At Shyam Jagat, we believe that even the smallest act of kindness can create a lasting impact. Guided by the blessings of Baba Shyam, we encourage every individual to become a part of this journey of service, compassion, and positive change. Together, we are not just serving people—we are building hope, creating opportunities, and shaping a stronger, kinder society for generations to come.",
    "about.belief.cta": "Join the Shyam Family",
    "about.roles.devotees": "Devotees",
    "about.roles.temples": "Temples",
    "about.roles.artists": "Artists",
    "about.roles.organizers": "Organizers",
    "about.roles.administrators": "Administrators",
    "about.ecosystem.badge": "Platform Ecosystem Overview",
    "about.ecosystem.title": "One Platform. Every Role. Infinite Devotion.",
    "about.ecosystem.subtitle": "A multi-role spiritual ecosystem seamlessly connecting Devotees, Temples, Artists, Event Organizers, and Administrators - all under the blessings of Baba Shyam.",
    "about.feature1.title": "Temple Registration & Management",
    "about.feature1.desc": "Register temples, manage profiles, update schedules, and showcase offerings to thousands of devotees online.",
    "about.feature2.title": "Artist Registration & Slot Booking",
    "about.feature2.desc": "Bhajan singers, katha speakers, and performers can register, set availability, and get booked for events seamlessly.",
    "about.feature3.title": "Live Darshan & Aarti Feed",
    "about.feature3.desc": "Stream live aarti and darshan in real time, allowing devotees worldwide to participate in sacred rituals from anywhere.",
    "about.feature4.title": "Puja / Seva / Darshan Booking",
    "about.feature4.desc": "Devotees can book personalized pujas, sevas, and darshan slots at their preferred temple with ease.",
    "about.feature5.title": "Center Dashboard",
    "about.feature5.desc": "A unified control center for managing all platform activity - content, users, bookings, and operations - in one place.",
    "about.feature6.title": "Events & Activities",
    "about.feature6.desc": "Discover, create, and manage spiritual events, satsangs, bhajan programs, and community gatherings.",
    "about.feature7.title": "Donations & Fundraising",
    "about.feature7.desc": "Enable transparent, secure donations to temples, causes, and relief initiatives with campaign tracking.",
    "about.feature8.title": "Spiritual Content",
    "about.feature8.desc": "Access a rich library of bhajans, kathas, articles, and devotional videos curated for every seeker.",
    "about.feature9.title": "Analytics & Reports",
    "about.feature9.desc": "Real-time dashboards and detailed reports for administrators and organizers to track impact and engagement.",
    "about.footer.text": "Join thousands of devotees, temples, and artists already on the platform.",
    "about.footer.cta": "Get Started",

    "initiativesPage.hero.mantra": "|| जय श्री श्याम ||",
    "initiativesPage.hero.title": "Our Initiatives",
    "initiativesPage.hero.subtitle": "Serving Society Through Compassion & Seva",
    "initiativesPage.hero.desc": "At Shyam Jagat, every initiative is driven by the spirit of selfless service (Seva) and inspired by the teachings of Baba Shyam. Our programs are designed to uplift individuals, strengthen families, and create opportunities for a more compassionate and self-reliant society.",
    "initiativesPage.featured.title": "Featured Initiatives",
    "initiativesPage.featured.subtitle": "Flagship programs creating lasting impact across communities",
