    "registerPage.testimonials.eyebrow": "Feedback",
    "registerPage.testimonials.title": "Voices from Our Sacred Family",
    "registerPage.testimonial1.quote": "Singing bhajan at Khatu Shyam Ji events under Shyam Jagat's platform has been the absolute pinnacle of my career. The energy and management are purely spiritual.",
    "registerPage.testimonial1.role": "Bhajan Singer",
    "registerPage.testimonial2.quote": "Registering our historical temple brought us completely online. We now handle darshan bookings smoothly and can stream aarti to elders across the country.",
    "registerPage.testimonial2.role": "Temple Administrator",
    "registerPage.testimonial3.quote": "As a classical Kathak dancer, finding the right spiritual platforms was hard. Shyam Jagat linked us directly to major divine events across India.",
    "registerPage.testimonial3.role": "Classical Dancer",
    "registerPage.faq.eyebrow": "Questions",
    "registerPage.faq.title": "Frequently Asked Questions",
    "registerPage.faq1.q": "Is there any registration fee?",
    "registerPage.faq1.a": "No, registration on the Shyam Jagat platform is absolutely free of charge for all individual artists, temples, and organizations.",
    "registerPage.faq2.q": "What is the verification process?",
    "registerPage.faq2.a": "Our dedicated seva committee reviews every profile within 24 to 48 hours. We verify ID proofs and credentials to maintain the sacred environment of our directory.",
    "registerPage.faq3.q": "Can I manage multiple profiles?",
    "registerPage.faq3.a": "Yes, you can register as an individual and also manage a temple or mandal listing using a unified admin dashboard.",
    "registerPage.faq4.q": "How do travelers contact dharamshalas?",
    "registerPage.faq4.a": "Once listed, your contact info, location map, and booking guidelines will be directly visible to millions of pilgrims who can call or book instantly.",
    "registerPage.cta.title": "Ready to Join Our Family?",
    "registerPage.cta.desc": "Take a leap of faith. Registering takes less than 5 minutes and is 100% free. Connect directly with millions of Baba Shyam devotees.",
    "registerPage.cta.button": "Start Registration",

