    "home.join.title": "श्याम परिवार से जुड़ें",
    "home.join.desc": "हमारे मिशन का हिस्सा बनें और एक बेहतर समाज बनाने में हमारी मदद करें।",
    "home.faq.title": "अक्सर पूछे जाने वाले प्रश्न",
    "home.faq.subtitle": "प्रश्न हैं? हमारे पास उत्तर हैं।",
    "home.faq.left.q1": "मैं श्याम जगत को दान कैसे कर सकता हूं?",
    "home.faq.left.a1": "आप हमारी वेबसाइट के माध्यम से ऑनलाइन, UPI, बैंक ट्रांसफर या हमारे कार्यालयों में व्यक्तिगत रूप से दान कर सकते हैं। सभी दान की रसीद दी जाती है और वे 80G कर छूट के अंतर्गत आते हैं।",
    "home.faq.left.q2": "मैं श्याम जगत का सदस्य कैसे बनूं?",
