    "initiativesPage.gallery.item12.title": "सामुदायिक सभा",
    "initiativesPage.contribute.title": "आप कैसे योगदान दे सकते हैं",
    "initiativesPage.contribute.subtitle": "देने का हर कार्य - बड़ा हो या छोटा - बदलाव की लहर पैदा करता है।",
    "initiativesPage.contribute1.title": "स्वयंसेवक बनें",
    "initiativesPage.contribute1.desc": "अपना समय और कौशल हमारे सेवा कार्यक्रमों को समर्पित करें और लोगों के जीवन में सीधा बदलाव लाएं।",
    "initiativesPage.contribute1.cta": "स्वयंसेवक बनें",
    "initiativesPage.contribute2.title": "दान करें",
    "initiativesPage.contribute2.desc": "आपका दान उन लोगों के लिए भोजन, दवाइयां, शिक्षा और आश्रय का वित्तपोषण करता है जिन्हें इसकी सबसे अधिक आवश्यकता है।",
    "initiativesPage.contribute2.cta": "अभी दान करें",
    "initiativesPage.contribute3.title": "सदस्य बनें",
    "initiativesPage.contribute3.desc": "आधिकारिक श्याम जगत सदस्य बनें और बदलाव लाने वालों के हमारे बढ़ते परिवार का हिस्सा बनें।",
