    "registerPage.step2.title": "अपना विवरण भरें",
    "registerPage.step2.desc": "अपनी प्रामाणिक साख और पोर्टफोलियो के साथ सुरक्षित पंजीकरण फ़ॉर्म पूरा करें।",
    "registerPage.step3.title": "सत्यापित हों और लाइव जाएं",
    "registerPage.step3.desc": "हमारी टीम आपके आवेदन की समीक्षा करेगी। सत्यापित होने के बाद, आप तुरंत लाइव हो जाते हैं!",
    "registerPage.benefits.eyebrow": "लाभ",
    "registerPage.benefits.title": "श्याम जगत के साथ पंजीकरण क्यों करें?",
    "registerPage.benefit1.title": "राष्ट्रव्यापी दृश्यता",
    "registerPage.benefit1.desc": "आध्यात्मिक सेवाओं और वस्तुओं की तलाश कर रहे लाखों भक्तों तक पहुंचें।",
    "registerPage.benefit2.title": "सत्यापित ट्रस्ट बैज",
    "registerPage.benefit2.desc": "प्रामाणिकता प्रदर्शित करने और भक्तों का विश्वास बनाने के लिए एक सुनहरा ट्रस्ट बैज अर्जित करें।",
    "registerPage.benefit3.title": "सामुदायिक सहायता",
    "registerPage.benefit3.desc": "हमारे डिजिटल सेवा सहायता विशेषज्ञों से समर्पित चौबीसों घंटे सहायता प्राप्त करें।",
    "registerPage.benefit4.title": "मुफ़्त सूचीकरण",
    "registerPage.benefit4.desc": "अपनी प्रोफ़ाइल बनाने और सूचीबद्ध करना शुरू करने के लिए बिल्कुल कोई छिपा हुआ शुल्क या फीस नहीं।",
    "registerPage.testimonials.eyebrow": "प्रतिक्रिया",
    "registerPage.testimonials.title": "हमारे पवित्र परिवार की आवाज़ें",
    "registerPage.testimonial1.quote": "श्याम जगत के मंच के तहत खाटू श्याम जी के कार्यक्रमों में भजन गाना मेरे करियर का सर्वोच्च शिखर रहा है। ऊर्जा और प्रबंधन पूरी तरह आध्यात्मिक है।",
    "registerPage.testimonial1.role": "भजन गायक",
    "registerPage.testimonial2.quote": "हमारे ऐतिहासिक मंदिर को पंजीकृत करने से हम पूरी तरह ऑनलाइन आ गए। अब हम दर्शन बुकिंग को सहजता से संभालते हैं और देश भर के बुजुर्गों तक आरती स्ट्रीम कर सकते हैं।",
    "registerPage.testimonial2.role": "मंदिर प्रशासक",
    "registerPage.testimonial3.quote": "एक शास्त्रीय कथक नर्तकी के रूप में, सही आध्यात्मिक मंच ढूंढना कठिन था। श्याम जगत ने हमें भारत भर के प्रमुख दिव्य आयोजनों से सीधे जोड़ा।",
    "registerPage.testimonial3.role": "शास्त्रीय नर्तकी",
    "registerPage.faq.eyebrow": "प्रश्न",
    "registerPage.faq.title": "अक्सर पूछे जाने वाले सवाल",
    "registerPage.faq1.q": "क्या कोई पंजीकरण शुल्क है?",
    "registerPage.faq1.a": "नहीं, श्याम जगत मंच पर पंजीकरण सभी व्यक्तिगत कलाकारों, मंदिरों और संगठनों के लिए बिल्कुल मुफ़्त है।",
    "registerPage.faq2.q": "सत्यापन प्रक्रिया क्या है?",
    "registerPage.faq2.a": "हमारी समर्पित सेवा समिति हर प्रोफ़ाइल की 24 से 48 घंटों के भीतर समीक्षा करती है। हम अपनी डायरेक्टरी के पवित्र वातावरण को बनाए रखने के लिए पहचान प्रमाण और साख सत्यापित करते हैं।",
    "registerPage.faq3.q": "क्या मैं कई प्रोफ़ाइल प्रबंधित कर सकता हूं?",
    "registerPage.faq3.a": "हां, आप एक व्यक्ति के रूप में पंजीकरण कर सकते हैं और एक एकीकृत एडमिन डैशबोर्ड का उपयोग करके मंदिर या मंडल सूची भी प्रबंधित कर सकते हैं।",
    "registerPage.faq4.q": "यात्री धर्मशालाओं से कैसे संपर्क करते हैं?",
    "registerPage.faq4.a": "सूचीबद्ध होने के बाद, आपकी संपर्क जानकारी, स्थान मानचित्र, और बुकिंग दिशानिर्देश सीधे लाखों तीर्थयात्रियों को दिखाई देंगे, जो तुरंत कॉल या बुक कर सकते हैं।",
    "registerPage.cta.title": "हमारे परिवार में शामिल होने के लिए तैयार हैं?",
    "registerPage.cta.desc": "आस्था की एक छलांग लगाएं। पंजीकरण में 5 मिनट से भी कम समय लगता है और यह 100% मुफ़्त है। लाखों बाबा श्याम भक्तों से सीधे जुड़ें।",
    "registerPage.cta.button": "पंजीकरण शुरू करें",

