    "artistReg.heroTitle": "एक कलाकार के रूप में पंजीकरण करें",
    "artistReg.heroDesc": "श्याम जगत के भक्ति कलाकारों के बढ़ते समुदाय में शामिल हों। पूरे भारत में आध्यात्मिक कार्यक्रमों, सांस्कृतिक कार्यक्रमों और पवित्र सभाओं में अपनी प्रतिभा दिखाएं।",
    "artistReg.expertiseTitle": "आपकी कला और विशेषज्ञता",
    "artistReg.primaryLabel": "प्राथमिक कला रूप",
    "artistReg.secondaryLabel": "द्वितीयक कला रूप (वैकल्पिक)",
    "artistReg.secondaryPlaceholder": "द्वितीयक कला रूप चुनें",
    "artistReg.guruLabel": "गुरु / शिक्षक का नाम (वैकल्पिक)",
    "artistReg.bioLabel": "संक्षिप्त परिचय / आपकी कला के बारे में",
    "artistReg.bioPlaceholder": "हमें एक कलाकार के रूप में अपनी यात्रा, अपने प्रशिक्षण और अपनी भक्ति कला को प्रेरित करने वाली चीज़ों के बारे में बताएं...",
    "artistReg.dragDrop": "अपनी तस्वीरें, वीडियो या ऑडियो फ़ाइलें यहां खींचें और छोड़ें",
    "artistReg.artistType1": "भजन गायक",
    "artistReg.artistType2": "संगीतकार",
    "artistReg.artistType3": "नर्तक",
    "artistReg.artistType4": "वक्ता",
    "artistReg.artistType5": "चित्रकार",
    "artistReg.artistType6": "संगीत रचयिता",
    "artistReg.artistType7": "अन्य",
    "artistReg.whyTitle": "एक कलाकार के रूप में श्याम जगत में क्यों शामिल हों?",
    "artistReg.whySubtitle": "भक्ति और प्रदर्शन का संगम। एक ऐसे मंच पर कदम रखें जो आपकी पवित्र कला का सम्मान करने और आपको वैश्विक भक्तों से जोड़ने के लिए बनाया गया है।",
    "artistReg.whyFeature1Title": "हजारों तक पहुंचें",
    "artistReg.whyFeature1Desc": "पूरे भारत में मंदिर बोर्डों और प्रमुख कार्यक्रम आयोजकों द्वारा खोजे जाएं।",
    "artistReg.whyFeature2Title": "पवित्र मंच",
    "artistReg.whyFeature2Desc": "प्रतिष्ठित मंदिर उत्सवों, निरंतर सत्संगों और प्रमुख सांस्कृतिक सभाओं में प्रदर्शन करें।",
    "artistReg.whyFeature3Title": "अपनी कला को बढ़ाएं",
    "artistReg.whyFeature3Desc": "अनुभवी भक्ति गुरुओं से जुड़ें, तकनीकों का आदान-प्रदान करें, और अपना आध्यात्मिक नेटवर्क बढ़ाएं।",
    "artistReg.whyFeature4Title": "उचित मुआवज़ा",
    "artistReg.whyFeature4Desc": "पारदर्शी बुकिंग शर्तों और सीधे अपने खाते में तेज़, सत्यापित डिजिटल भुगतान का अनुभव करें।",

    "dancerReg.heroTitle": "एक नर्तक के रूप में पंजीकरण करें",
    "dancerReg.heroDesc": "श्याम जगत के भक्ति नर्तकों के बढ़ते समुदाय में शामिल हों। पूरे भारत में आध्यात्मिक कार्यक्रमों, सांस्कृतिक कार्यक्रमों और पवित्र सभाओं में अपनी शास्त्रीय और भक्ति नृत्य प्रस्तुतियां साझा करें।",
