    "musicianReg.heroTitle": "एक संगीतकार के रूप में पंजीकरण करें",
    "musicianReg.heroDesc": "श्याम जगत के भक्ति संगीतकारों के बढ़ते समुदाय में शामिल हों। पूरे भारत में आध्यात्मिक कार्यक्रमों और पवित्र सभाओं में दिव्य धुनें लाएं — कीर्तन, भजन और शास्त्रीय संगीत।",
    "musicianReg.expertiseTitle": "आपका संगीत और विशेषज्ञता",
    "musicianReg.primaryLabel": "प्राथमिक वाद्य / शैली",
    "musicianReg.secondaryLabel": "द्वितीयक वाद्य / शैली (वैकल्पिक)",
    "musicianReg.secondaryPlaceholder": "द्वितीयक वाद्य / शैली चुनें",
    "musicianReg.guruLabel": "गुरु / संगीत अकादमी का नाम (वैकल्पिक)",
    "musicianReg.bioLabel": "संक्षिप्त परिचय / आपके संगीत के बारे में",
    "musicianReg.bioPlaceholder": "हमें एक संगीतकार के रूप में अपनी यात्रा, अपने प्रशिक्षण और अपने भक्ति संगीत को प्रेरित करने वाली चीज़ों के बारे में बताएं...",
    "musicianReg.dragDrop": "अपनी तस्वीरें, वीडियो या ऑडियो फ़ाइलें यहां खींचें और छोड़ें",
    "musicianReg.instrumentGenre1": "गायन / भजन गायन",
    "musicianReg.instrumentGenre2": "तबला",
    "musicianReg.instrumentGenre3": "हारमोनियम",
    "musicianReg.instrumentGenre4": "सितार",
    "musicianReg.instrumentGenre5": "बांसुरी",
    "musicianReg.instrumentGenre6": "ढोलक",
    "musicianReg.instrumentGenre7": "वायलिन",
    "musicianReg.instrumentGenre8": "अन्य",
    "musicianReg.whyTitle": "एक संगीतकार के रूप में श्याम जगत में क्यों शामिल हों?",
    "musicianReg.whySubtitle": "भक्ति और प्रदर्शन का संगम। एक ऐसे मंच पर कदम रखें जो आपकी पवित्र कला का सम्मान करने और आपको वैश्विक भक्तों से जोड़ने के लिए बनाया गया है।",
    "musicianReg.whyFeature1Title": "हजारों तक पहुंचें",
    "musicianReg.whyFeature1Desc": "पूरे भारत में मंदिर बोर्डों और प्रमुख कार्यक्रम आयोजकों द्वारा खोजे जाएं।",
    "musicianReg.whyFeature2Title": "पवित्र मंच",
    "musicianReg.whyFeature2Desc": "प्रतिष्ठित मंदिर उत्सवों, निरंतर सत्संगों और प्रमुख सांस्कृतिक सभाओं में प्रदर्शन करें।",
    "musicianReg.whyFeature3Title": "अपनी कला को बढ़ाएं",
    "musicianReg.whyFeature3Desc": "अनुभवी भक्ति गुरुओं से जुड़ें, तकनीकों का आदान-प्रदान करें, और अपना आध्यात्मिक नेटवर्क बढ़ाएं।",
    "musicianReg.whyFeature4Title": "उचित मुआवज़ा",
    "musicianReg.whyFeature4Desc": "पारदर्शी बुकिंग शर्तों और सीधे अपने खाते में तेज़, सत्यापित डिजिटल भुगतान का अनुभव करें।",

    "templeReg.heroTitle": "अपने मंदिर को पंजीकृत करें",
    "templeReg.heroDesc": "श्याम जगत पर अपने मंदिर को सूचीबद्ध करें और लाखों भक्तों से जुड़ें। तीर्थयात्रियों को आपके पवित्र स्थान, सेवाओं, दैनिक दर्शन समय और आगामी त्योहारों की जानकारी पाने में मदद करें।",
