    "templeReg.terms.certify": "मैं प्रमाणित करता हूं कि प्रदान की गई जानकारी सटीक है और मैं मंदिर ट्रस्ट की ओर से इस मंदिर को पंजीकृत करने के लिए अधिकृत हूं।",
    "templeReg.terms.agree": "मैं श्याम जगत आध्यात्मिक मंच की सेवा की शर्तों और गोपनीयता नीति से सहमत हूं।",
    "templeReg.terms.consent": "मैं मंच अपडेट और भक्त पूछताछ के बारे में संचार प्राप्त करने की सहमति देता हूं।",
    "templeReg.submit": "मंदिर पंजीकरण सबमिट करें",
    "templeReg.why.title": "श्याम जगत पर अपना मंदिर क्यों सूचीबद्ध करें?",
    "templeReg.why.subtitle": "दुनिया भर के लाखों साधकों के साथ भक्ति के पवित्र स्थानों को जोड़ना। संचार को सरल बनाएं, कार्यक्रम आयोजित करें, और सामुदायिक सहायता को सहजता से प्रबंधित करें।",
    "templeReg.whyFeature1Title": "भक्तों तक पहुंचें",
    "templeReg.whyFeature1Desc": "अपने आसपास मंदिरों की खोज कर रहे लाखों भक्तों से जुड़ें, उन्हें अपने पवित्र स्थल तक मार्गदर्शन करें।",
    "templeReg.whyFeature2Title": "कार्यक्रम प्रबंधित करें",
    "templeReg.whyFeature2Desc": "नियमित त्योहारों, विशेष पूजाओं और भंडारों की घोषणा एक व्यापक, अत्यधिक जुड़े हुए दर्शकों तक करें।",
    "templeReg.whyFeature3Title": "दान प्राप्त करें",
    "templeReg.whyFeature3Desc": "सुरक्षित और पारदर्शी तरीके से ऑनलाइन दान स्वीकार करें, मंदिर के रखरखाव के लिए सीधा वित्तीय सहयोग प्राप्त करें।",
    "templeReg.whyFeature4Title": "समुदाय का निर्माण करें",
    "templeReg.whyFeature4Desc": "अपने मंदिर के दर्शकों को डिजिटल-प्रथम तरीके से बढ़ाएं, आशीर्वाद भेजें और आध्यात्मिक शिक्षाओं को सहजता से साझा करें।",

