    "chairmanPage.breadcrumbCurrent": "अध्यक्ष",
    "chairmanPage.roleTitle": "अध्यक्ष — श्री श्याम जगत",
    "chairmanPage.bio": "एक आजीवन आध्यात्मिक साधक और सामाजिक परिवर्तन के शिल्पकार, श्री रमेश कुमार जी ने तीन दशकों से अधिक समय वैश्विक आध्यात्मिक समुदायों के संगठन, राहत कार्यक्रमों के संचालन और संस्थानों के निर्माण में समर्पित किया है।",
    "chairmanPage.ctaSchedule": "भेंट का समय लें",
    "chairmanPage.quoteTitle": "“श्रद्धा तभी शक्ति देती है जब वह अथक मानव सेवा में परिवर्तित हो।”",
    "chairmanPage.quoteBody": "“हम आध्यात्मिक संपर्क के एक नए युग में प्रवेश कर चुके हैं। हमारा मिशन आधुनिक डिजिटल प्रणालियों की शक्ति का उपयोग करना है ताकि कोई भी भक्त बाबा श्याम की दिव्य आभा का अनुभव करने से वंचित न रहे, और हमारी पहुंच में कोई भी बुज़ुर्ग या भूखा बच्चा सहायता से वंचित न रहे।”",
    "chairmanPage.quoteSignatureLabel": "अध्यक्ष के हस्ताक्षर और मुहर स्वीकृत",
    "chairmanPage.milestonesTitle": "नेतृत्व यात्रा और उपलब्धियां",
    "chairmanPage.milestone1Year": "1998 – वर्तमान",
    "chairmanPage.milestone1Title": "संस्थापक निदेशक, श्याम सेवा पहल",
    "chairmanPage.milestone1Desc": "खाटू, राजस्थान आने वाले तीर्थयात्रियों के लिए बुनियादी चिकित्सा शिविरों और मुफ्त रसोई सेवाओं का नेतृत्व किया।",
    "chairmanPage.milestone2Year": "2012",
    "chairmanPage.milestone2Title": "आध्यात्मिक सुधार पुरस्कार प्राप्तकर्ता",
    "chairmanPage.milestone2Desc": "तीर्थयात्री भीड़-प्रबंधन डेटाबेस और सुरक्षा के आधुनिकीकरण के लिए राष्ट्रीय स्तर पर सम्मानित।",
    "chairmanPage.milestone3Year": "2020",
    "chairmanPage.milestone3Title": "श्री श्याम जगत के वैश्विक अध्यक्ष नियुक्त",
    "chairmanPage.milestone3Desc": "डिजिटलीकरण, वैवाहिक मंच और राज्यव्यापी शाखा एकीकरण का नेतृत्व।",
    "chairmanPage.credEducation": "शिक्षा",
    "chairmanPage.credKeyResponsibility": "मुख्य जिम्मेदारी",

    "mukhyaTrusteePage.breadcrumbCurrent": "मुख्य ट्रस्टी",
    "mukhyaTrusteePage.roleTitle": "मुख्य ट्रस्टी — श्री श्याम जगत",
    "mukhyaTrusteePage.bio": "प्रशासनिक नैतिकता और सामुदायिक कल्याण की एक स्तंभ, श्रीमती सुनीता देवी जी खाटू मंदिर संचालन, महिला सशक्तिकरण और वरिष्ठ देखभाल गृहों को समर्पित पारंपरिक पारिवारिक ट्रस्टों का संचालन करती हैं।",
    "mukhyaTrusteePage.ctaConnect": "कार्यालय से संपर्क करें",
    "mukhyaTrusteePage.quoteTitle": "“सच्चा सशक्तिकरण हमारी बेटियों को सक्षम बनाने और हमारे बुजुर्गों की रक्षा करने में है।”",
    "mukhyaTrusteePage.quoteBody": "“श्याम जगत की शक्ति सबसे कमजोर वर्ग के लिए हम जो आत्मनिर्भरता उत्पन्न कर सकते हैं, उसमें निहित है। सक्रिय कौशल शिक्षा और पारदर्शी दानदाता सहयोग के माध्यम से, हम सभी जिलों में अपने महिला सहकारी समूहों और वरिष्ठ देखभाल नेटवर्क का विस्तार करना चाहते हैं।”",
    "mukhyaTrusteePage.visionTitle": "दृष्टिकोण और कार्य क्षेत्र",
    "mukhyaTrusteePage.focus1Title": "ग्रामीण महिलाओं का सशक्तिकरण",
    "mukhyaTrusteePage.focus1Desc": "स्थायी आय सक्षम करने वाले व्यावसायिक सिलाई, शिल्प डिज़ाइन और कंप्यूटर साक्षरता केंद्रों का नेतृत्व।",
    "mukhyaTrusteePage.focus2Title": "वरिष्ठ नागरिक कल्याण",
    "mukhyaTrusteePage.focus2Desc": "जयपुर और सीकर के वृद्धाश्रमों में सम्मानजनक आवास और उच्च-देखभाल नर्सिंग इकाइयों की स्थापना।",
    "mukhyaTrusteePage.focus3Title": "अनूप सेवा वैवाहिक सेवाएं",
    "mukhyaTrusteePage.focus3Desc": "सामुदायिक-समर्थित ऑनलाइन विवाह सहायता के माध्यम से पारिवारिक मूल्यों और पारंपरिक संरचनाओं का संरक्षण।",
    "mukhyaTrusteePage.credAreaOfWork": "कार्य क्षेत्र",

