    "home.hero.stat.states2": "কভার করা হয়েছে",
    "home.hero.missionTitle": "আমাদের লক্ষ্য",
    "home.hero.missionText": "বিশ্বাস, সেবা ও করুণায় ঐক্যবদ্ধ ভক্তদের একটি বৈশ্বিক সম্প্রদায় গড়ে তোলা।",
    "home.about.eyebrow": "সম্পর্কে",
    "home.about.body": "শ্যাম জগত বাবা শ্যামের দ্বারা অনুপ্রাণিত একটি আধ্যাত্মিক ও সামাজিক সংগঠন, যা বিশ্বাস ও কর্মের মাধ্যমে মানবতার সেবায় নিবেদিত। আমরা শিশুদের জন্য মানসম্পন্ন শিক্ষা, কর্মসংস্থানের জন্য দক্ষতা প্রশিক্ষণ, খাদ্য নিরাপত্তার জন্য বিনামূল্যে খাবার, গৃহহীনদের জন্য নিরাপদ আশ্রয়, বিনামূল্যে স্বাস্থ্য শিবির এবং নারী ক্ষমতায়ন কর্মসূচির মাধ্যমে সম্প্রদায়কে এগিয়ে নিয়ে যাই। একসাথে, আমরা একটি সহানুভূতিশীল ও স্বনির্ভর সমাজ গড়তে চাই যেখানে সবাই মর্যাদার সাথে উন্নতি করতে পারে।",
    "home.about.knowMore": "আরও জানুন",
    "home.baba.body": "\"ভীমের কিংবদন্তি নাতি বর্বরীক হিসেবে জন্ম নিয়ে, তাঁর ছিল অতুলনীয় যোদ্ধা শক্তি। তবুও, ধর্মের (সত্যের) বিজয়ের জন্য নিজের মাথা উৎসর্গ করাই ছিল তাঁর সর্বশ্রেষ্ঠ কাজ। তাঁর নিঃস্বার্থ ভক্তিতে সন্তুষ্ট হয়ে, ভগবান কৃষ্ণ তাঁকে নিজের নাম—শ্যাম—প্রদান করেন এবং বর দেন যে কলিযুগে তিনি পরাজিতদের চূড়ান্ত রক্ষাকর্তা হিসেবে পূজিত হবেন।\"",
    "home.aarti.eyebrow": "দর্শন",
    "home.aarti.title": "লাইভ আরতি ও দর্শন",
    "home.aarti.streamingTitle": "সরাসরি সম্প্রচার চলছে",
    "home.aarti.streamingDesc": "মন্দিরের গর্ভগৃহের আমাদের অবিরত লাইভ সম্প্রচারে হাজারো ভক্তের সাথে যোগ দিন।",
    "home.aarti.watchLive": "লাইভ দেখুন",
    "home.initiatives.eyebrow": "আমরা যা করি",
    "home.initiatives.titlePrefix": "আমাদের",
    "home.initiatives.titleHighlight": "উদ্যোগ",
    "home.initiatives.subtitle": "বিশ্বাসের দ্বারা চালিত, সহানুভূতির দ্বারা লালিত - সমাজের প্রতিটি স্তরে জীবনের সেবা।",
    "home.initiatives.learnMore": "আরও জানুন",
    "home.success.title": "সাফল্যের গল্প",
    "home.success.subtitle": "প্রকৃত জীবন, প্রকৃত প্রভাব — আশা ও পরিবর্তনের গল্প।",
    "home.success.t1": "শ্যাম জগতের বৃত্তি আমার জীবন বদলে দিয়েছে। আজ আমি একজন সফটওয়্যার ইঞ্জিনিয়ার এবং এর সম্পূর্ণ কৃতিত্ব তাদের সমর্থন ও আমার প্রতি বিশ্বাসের।",
    "home.success.t2": "কর্মসংস্থান পোর্টালের মাধ্যমে, আমি আমার দক্ষতার সাথে মানানসই একটি চাকরি পেয়েছি। শ্যাম জগত শুধু কাজই দেয়নি — তারা আমাকে লক্ষ্য ও আত্মবিশ্বাস দিয়েছে।",
    "home.success.t3": "আমি একা এবং সংগ্রামরত ছিলাম। বৃদ্ধাশ্রম আমাকে আবার একটি পরিবার দিয়েছে। এখানে আমি যে উষ্ণতা, যত্ন ও সম্মান পাই তা ভাষায় প্রকাশ করা যায় না।",
    "home.why.title": "কেন শ্যাম জগত বেছে নেবেন",
    "home.why.subtitle": "বিশ্বাসের উপর নির্মিত, উদ্দেশ্য দ্বারা চালিত এবং স্থায়ী পরিবর্তনে প্রতিশ্রুতিবদ্ধ।",
    "home.why.f1.title": "বিশ্বাস চালিত",
    "home.why.f1.desc": "প্রতিটি উদ্যোগ বাবা শ্যামের ঐশ্বরিক শিক্ষায় নিহিত - সেবাই ভক্তি।",
    "home.why.f2.title": "স্বচ্ছ",
    "home.why.f2.desc": "আমরা আমাদের সকল কর্মসূচি ও দানে সম্পূর্ণ আর্থিক স্বচ্ছতা ও জবাবদিহিতা বজায় রাখি।",
    "home.why.f3.title": "সম্প্রদায় কেন্দ্রিক",
    "home.why.f3.desc": "আমাদের কাজ সম্প্রদায়ের দ্বারা, সম্প্রদায়ের জন্য পরিচালিত - বিশ্বাস ও সম্মিলিত অংশগ্রহণের উপর নির্মিত।",
    "home.why.f4.title": "যাচাইকৃত স্বেচ্ছাসেবক",
    "home.why.f4.desc": "আমাদের সকল স্বেচ্ছাসেবক যাচাইকৃত, প্রশিক্ষিত এবং সর্বোচ্চ মানের সেবায় প্রতিশ্রুতিবদ্ধ।",
    "home.why.f5.title": "নিবেদিত সহায়তা",
    "home.why.f5.desc": "আমাদের সদস্য, উপকারভোগী ও অংশীদারদের জন্য 24/7 সহায়তা - আপনার প্রয়োজনে আমরা সর্বদা পাশে আছি।",
    "home.why.f6.title": "দীর্ঘমেয়াদী প্রভাব",
    "home.why.f6.desc": "আমরা টেকসই পরিবর্তনে মনোনিবেশ করি - শুধু স্বল্পমেয়াদী ত্রাণ নয়, বরং স্থায়ী সুযোগ তৈরি করি।",
    "home.temple.eyebrow": "মন্দিরের জন্য",
    "home.temple.title": "আপনার মন্দির নিবন্ধন করুন",
    "home.temple.desc": "আপনার মন্দিরকে শ্যাম জগতে তালিকাভুক্ত করুন এবং লক্ষ লক্ষ ভক্তের সাথে সংযুক্ত হোন। তীর্থযাত্রীদের আপনার পবিত্র স্থান, দর্শনের সময় ও আসন্ন অনুষ্ঠান আবিষ্কার করতে সাহায্য করুন।",
    "home.temple.b1": "অনলাইনে লক্ষ লক্ষ ভক্তের কাছে পৌঁছান",
