    "home.faq.left.q1": "আমি কীভাবে শ্যাম জগতে দান করতে পারি?",
    "home.faq.left.a1": "আপনি আমাদের ওয়েবসাইটের মাধ্যমে অনলাইনে, UPI, ব্যাংক ট্রান্সফার বা আমাদের অফিসে সরাসরি দান করতে পারেন। সকল দানের রসিদ দেওয়া হয় এবং তা 80G কর মুক্ত।",
