    "home.contact.desc": "আমরা সবসময় আপনাকে সাহায্য করতে এখানে আছি। আপনার প্রশ্ন থাকুক, স্বেচ্ছাসেবক হতে চান, দান করতে চান, বা সহায়তা প্রয়োজন হোক - আমাদের হেল্পডেস্ক আপনার জন্য এখানে আছে।",
