    "initiatives.card3.desc": "সম্প্রদায়-চালিত উদ্যোগের মাধ্যমে পরিচ্ছন্নতা, স্বাস্থ্যবিধি এবং পরিবেশ যত্নের প্রচার।",
    "initiatives.card4.tag": "গোশালা",
    "initiatives.card4.title": "গোশালা",
    "initiatives.card4.desc": "পরিত্যক্ত ও আহত গরুদের আশ্রয়, পুষ্টি এবং চিকিৎসা সেবা প্রদান।",
    "initiatives.card5.tag": "বিবাহ ব্যুরো",
    "initiatives.card5.title": "বিবাহ ব্যুরো",
    "initiatives.card5.desc": "সম্প্রদায়ের জন্য নির্মিত একটি বিশ্বস্ত, মূল্যবোধ-চালিত বৈবাহিক প্ল্যাটফর্মের মাধ্যমে হৃদয়কে সংযুক্ত করা।",
    "initiatives.card6.tag": "যত্ন ও আশ্রয়",
    "initiatives.card6.title": "বৃদ্ধাশ্রম",
