    "baba.festival1.desc": "সবচেয়ে বৃহৎ উদযাপন, যা কয়েক দিনের ভক্তি ও উৎসবে লক্ষ লক্ষ ভক্তকে আকৃষ্ট করে।",
    "baba.festival2.title": "জন্মাষ্টমী",
