    "baba.festival3.title": "একাদশী",
    "baba.festival3.when": "মাসে দুইবার",
    "baba.festival3.desc": "বাবা শ্যামের আশীর্বাদ পেতে ভক্তদের বিশেষ প্রার্থনা ও উপবাস।",
    "baba.festival4.title": "ভজন সন্ধ্যা",
    "baba.festival4.when": "প্রতি সন্ধ্যা",
    "baba.festival4.desc": "ভাবপূর্ণ স্তোত্র ও প্রার্থনায় মন্দির পূর্ণ করা ভক্তিমূলক সংগীত অধিবেশন।",
    "baba.festival5.title": "শ্যাম কথা",
    "baba.festival5.when": "সাপ্তাহিক",
    "baba.festival5.desc": "বাবা শ্যামের দিব্য কাহিনী ও শিক্ষা বর্ণনাকারী কথকতা অধিবেশন।",
    "baba.rituals.title": "দৈনিক মন্দির আচার",
    "baba.rituals.subtitle": "খাটু শ্যাম জি মন্দিরে ভক্তির পবিত্র ছন্দ",
    "baba.ritual1.title": "মঙ্গলা আরতি",
    "baba.ritual1.desc": "দিনের প্রথম প্রার্থনা, ভোরে ভক্তি সহকারে বাবা শ্যামকে স্বাগত জানানো।",
    "baba.ritual2.title": "শৃঙ্গার দর্শন",
    "baba.ritual2.desc": "ভক্তরা বাবা শ্যামকে সুন্দর পোশাক ও অলংকারে সজ্জিত দেখেন।",
    "baba.ritual3.title": "রাজভোগ",
    "baba.ritual3.desc": "দুপুরে বাবা শ্যামকে খাবারের বৃহৎ ভোগ নিবেদন করা হয়।",
    "baba.ritual4.title": "বিকেলের দর্শন",
    "baba.ritual4.desc": "ভক্তরা বিকেলের ঘণ্টাগুলিতে আশীর্বাদ পেতে থাকেন।",
    "baba.ritual5.title": "সন্ধ্যা আরতি",
    "baba.ritual5.desc": "সন্ধ্যার প্রার্থনা, ভক্তি সহকারে দিন থেকে রাতে রূপান্তর চিহ্নিত করে।",
    "baba.ritual6.title": "শয়ন দর্শন",
    "baba.ritual6.desc": "দিনের শেষ প্রার্থনা, যখন বাবা শ্যামকে বিশ্রামের জন্য প্রস্তুত করা হয়।",
    "baba.bhajans.title": "ভজন ও আধ্যাত্মিক জ্ঞান",
