    "about.hero.mantra": "|| জয় শ্রী শ্যাম ||",
    "about.hero.title": "শ্যাম জগত সম্পর্কে",
    "about.hero.subtitle": "বিশ্বাস, করুণা এবং উদ্দেশ্য নিয়ে মানবতার সেবা",
    "about.whoWeAre.title": "আমরা কারা",
    "about.whoWeAre.p1": "শ্যাম জগত বাবা শ্যামের দিব্য শিক্ষা ও আশীর্বাদ দ্বারা অনুপ্রাণিত একটি আধ্যাত্মিক ও সামাজিক সংস্থা। আমাদের লক্ষ্য ভক্তিকে অর্থবহ সামাজিক সেবার সাথে যুক্ত করে জীবন পরিবর্তন করা, এমন একটি সম্প্রদায় তৈরি করা যেখানে করুণা, মর্যাদা এবং সুযোগ সবার জন্য উপলব্ধ।",
    "about.whoWeAre.p2": "আমরা বিশ্বাস করি যে সত্যিকারের ভক্তি নিঃস্বার্থ সেবার মাধ্যমে প্রকাশ পায়। আমাদের প্রতিটি উদ্যোগ দয়া, সমতা এবং মানবতার মূল্যবোধ দ্বারা চালিত, যা ব্যক্তি ও পরিবারকে একটি উজ্জ্বল ভবিষ্যৎ গড়তে সাহায্য করে।",
    "about.vision.title": "আমাদের দৃষ্টিভঙ্গি",
    "about.vision.text": "একটি সহানুভূতিশীল, ক্ষমতায়িত এবং স্বনির্ভর সমাজ গড়ে তোলা যেখানে প্রতিটি ব্যক্তি বাবা শ্যামের আশীর্বাদে শিক্ষা, স্বাস্থ্যসেবা, খাদ্য, আশ্রয়, কর্মসংস্থানের সুযোগ এবং মর্যাদাপূর্ণ জীবনের অধিকারী হয়।",
    "about.mission.title": "আমাদের লক্ষ্য",
    "about.mission.text": "আমাদের লক্ষ্য টেকসই উদ্যোগের মাধ্যমে সমাজের সেবা করা যা জীবনকে উন্নত করে, সম্প্রদায়কে শক্তিশালী করে এবং মানুষকে একটি উন্নত আগামীর জন্য অবদান রাখতে অনুপ্রাণিত করে। আমরা ব্যক্তিদের প্রয়োজনীয় সম্পদ, সহায়তা এবং সুযোগ দিয়ে ক্ষমতায়িত করে স্থায়ী সামাজিক প্রভাব তৈরি করার চেষ্টা করি।",
    "about.belief.title": "আমাদের বিশ্বাস",
    "about.belief.text": "শ্যাম জগতে, আমরা বিশ্বাস করি যে দয়ার ক্ষুদ্রতম কাজও একটি স্থায়ী প্রভাব তৈরি করতে পারে। বাবা শ্যামের আশীর্বাদে পরিচালিত, আমরা প্রতিটি ব্যক্তিকে সেবা, করুণা এবং ইতিবাচক পরিবর্তনের এই যাত্রার অংশ হতে উৎসাহিত করি। একসাথে, আমরা শুধু মানুষের সেবা করছি না — আমরা আশা তৈরি করছি, সুযোগ সৃষ্টি করছি এবং ভবিষ্যৎ প্রজন্মের জন্য একটি শক্তিশালী, দয়ালু সমাজ গড়ে তুলছি।",
    "about.belief.cta": "শ্যাম পরিবারে যোগ দিন",
    "about.roles.devotees": "ভক্ত",
    "about.roles.temples": "মন্দির",
