    "initiativesPage.contribute.title": "আপনি কীভাবে অবদান রাখতে পারেন",
    "initiativesPage.contribute.subtitle": "দানের প্রতিটি কাজ - বড় বা ছোট - পরিবর্তনের ঢেউ তৈরি করে।",
    "initiativesPage.contribute1.title": "স্বেচ্ছাসেবক হোন",
    "initiativesPage.contribute1.desc": "আপনার সময় ও দক্ষতা আমাদের সেবা কার্যক্রমে উৎসর্গ করুন এবং মানুষের জীবনে সরাসরি পরিবর্তন আনুন।",
    "initiativesPage.contribute1.cta": "স্বেচ্ছাসেবক হোন",
    "initiativesPage.contribute2.title": "দান করুন",
    "initiativesPage.contribute2.desc": "আপনার দান তাদের জন্য খাদ্য, ওষুধ, শিক্ষা এবং আশ্রয়ের অর্থায়ন করে যাদের এটি সবচেয়ে বেশি প্রয়োজন।",
    "initiativesPage.contribute2.cta": "এখনই দান করুন",
    "initiativesPage.contribute3.title": "সদস্য হোন",
    "initiativesPage.contribute3.desc": "একজন অফিসিয়াল শ্যাম জগত সদস্য হোন এবং পরিবর্তন-নির্মাতাদের আমাদের ক্রমবর্ধমান পরিবারের অংশ হোন।",
    "initiativesPage.contribute3.cta": "সদস্য হোন",
    "initiativesPage.contribute4.title": "শিক্ষা স্পনসর করুন",
    "initiativesPage.contribute4.desc": "একটি শিশুর শিক্ষা স্পনসর করুন এবং তাদের জ্ঞান, সুযোগ এবং উজ্জ্বল ভবিষ্যতের উপহার দিন।",
    "initiativesPage.contribute4.cta": "একটি শিশুকে স্পনসর করুন",
    "initiativesPage.contribute5.title": "খাবার স্পনসর করুন",
    "initiativesPage.contribute5.desc": "১০০টি পরিবারের একদিনের খাবারের অর্থায়ন করুন এবং আজ রাতে কেউ যেন ক্ষুধার্ত না ঘুমায় তার কারণ হোন।",
    "initiativesPage.contribute5.cta": "খাবার স্পনসর করুন",
    "initiativesPage.contribute6.title": "আমাদের সাথে অংশীদার হন",
    "initiativesPage.contribute6.desc": "সংস্থা ও ব্যবসাগুলি আমাদের প্রভাব বাড়াতে এবং আরও সম্প্রদায়ে পৌঁছাতে আমাদের সাথে অংশীদার হতে পারে।",
    "initiativesPage.contribute6.cta": "আমাদের সাথে অংশীদার হন",

