    "artistReg.whySubtitle": "ভক্তি ও প্রদর্শনের মিলন। একটি প্ল্যাটফর্মে পা রাখুন যা আপনার পবিত্র শিল্পকে সম্মান জানাতে এবং আপনাকে বিশ্বব্যাপী ভক্তদের সাথে সংযুক্ত করতে তৈরি করা হয়েছে।",
