    "artistReg.whyFeature2Title": "পবিত্র মঞ্চ",
    "artistReg.whyFeature2Desc": "মর্যাদাপূর্ণ মন্দির উৎসব, নিরবচ্ছিন্ন সৎসঙ্গ এবং বড় সাংস্কৃতিক সমাবেশে পরিবেশন করুন।",
    "artistReg.whyFeature3Title": "আপনার শিল্প বৃদ্ধি করুন",
    "artistReg.whyFeature3Desc": "অভিজ্ঞ ভক্তি গুরুদের সাথে সংযুক্ত হোন, কৌশল বিনিময় করুন এবং আপনার আধ্যাত্মিক নেটওয়ার্ক প্রসারিত করুন।",
    "artistReg.whyFeature4Title": "ন্যায্য পারিশ্রমিক",
