    "templeReg.gallery.hint": "১০টি পর্যন্ত ছবি আপলোড করুন। গৃহীত ফরম্যাট: JPG, PNG। প্রতি ছবি সর্বোচ্চ 5MB। প্রধান দেবতা, মন্দিরের বাহিরের অংশ, অভ্যন্তর এবং প্রাঙ্গণের ছবি অন্তর্ভুক্ত করুন।",
    "templeReg.terms.certify": "আমি প্রত্যয়ন করছি যে প্রদত্ত তথ্য সঠিক এবং আমি মন্দির ট্রাস্টের পক্ষ থেকে এই মন্দির নিবন্ধন করার জন্য অনুমোদিত।",
    "templeReg.terms.agree": "আমি শ্যাম জগত আধ্যাত্মিক প্ল্যাটফর্মের সেবার শর্তাবলী এবং গোপনীয়তা নীতিতে সম্মত।",
    "templeReg.terms.consent": "আমি প্ল্যাটফর্ম আপডেট এবং ভক্তদের জিজ্ঞাসা সম্পর্কে যোগাযোগ পাওয়ার সম্মতি দিচ্ছি।",
    "templeReg.submit": "মন্দির নিবন্ধন জমা দিন",
    "templeReg.why.title": "কেন শ্যাম জগতে আপনার মন্দির তালিকাভুক্ত করবেন?",
    "templeReg.why.subtitle": "বিশ্বব্যাপী লক্ষ লক্ষ সাধকদের সাথে ভক্তির পবিত্র স্থানগুলি সংযুক্ত করা। যোগাযোগ সহজ করুন, অনুষ্ঠান আয়োজন করুন এবং সাম্প্রদায়িক সহায়তা অনায়াসে পরিচালনা করুন।",
    "templeReg.whyFeature1Title": "ভক্তদের কাছে পৌঁছান",
    "templeReg.whyFeature1Desc": "তাদের কাছাকাছি মন্দির খুঁজছেন এমন লক্ষ লক্ষ ভক্তের সাথে সংযুক্ত হন, তাদের আপনার পবিত্র স্থানে পথনির্দেশ করুন।",
    "templeReg.whyFeature2Title": "অনুষ্ঠান পরিচালনা করুন",
    "templeReg.whyFeature2Desc": "নিয়মিত উৎসব, বিশেষ পূজা এবং ভাণ্ডারার ঘোষণা একটি বৃহত্তর, অত্যন্ত সম্পৃক্ত দর্শকদের কাছে দিন।",
    "templeReg.whyFeature3Title": "দান গ্রহণ করুন",
    "templeReg.whyFeature3Desc": "নিরাপদে এবং স্বচ্ছভাবে অনলাইন দান গ্রহণ করুন, মন্দির রক্ষণাবেক্ষণের জন্য সরাসরি আর্থিক সহায়তা তৈরি করুন।",
    "templeReg.whyFeature4Title": "সম্প্রদায় গড়ে তুলুন",
    "templeReg.whyFeature4Desc": "আপনার মন্দিরের দর্শকদের ডিজিটাল-প্রথম উপায়ে বৃদ্ধি করুন, আশীর্বাদ পাঠান এবং আধ্যাত্মিক শিক্ষা সাবলীলভাবে শেয়ার করুন।",

