    "chairmanPage.breadcrumbCurrent": "চেয়ারম্যান",
    "chairmanPage.roleTitle": "চেয়ারম্যান — শ্রী শ্যাম জগত",
    "chairmanPage.bio": "একজন আজীবন আধ্যাত্মিক সাধক এবং সামাজিক পরিবর্তনের স্থপতি, শ্রী রমেশ কুমার জি তিন দশকেরও বেশি সময় ধরে বিশ্বব্যাপী আধ্যাত্মিক সম্প্রদায় সংগঠিত করা, ত্রাণ কর্মসূচি পরিচালনা এবং প্রতিষ্ঠান গড়ে তোলার জন্য উৎসর্গ করেছেন।",
    "chairmanPage.ctaSchedule": "সাক্ষাতের সময় নিন",
    "chairmanPage.quoteTitle": "“বিশ্বাস তখনই শক্তি দেয় যখন তা নিরলস মানব সেবায় রূপান্তরিত হয়।”",
    "chairmanPage.quoteBody": "“আমরা আধ্যাত্মিক সংযোগের এক নতুন যুগে প্রবেশ করেছি। আমাদের লক্ষ্য আধুনিক ডিজিটাল ব্যবস্থার শক্তি ব্যবহার করা যাতে কোনো ভক্ত বাবা শ্যামের দিব্য আভা অনুভব করা থেকে বঞ্চিত না হন, এবং আমাদের নাগালের মধ্যে কোনো বৃদ্ধ বা ক্ষুধার্ত শিশু সহায়তা ছাড়া না থাকে।”",
    "chairmanPage.quoteSignatureLabel": "চেয়ারম্যানের স্বাক্ষর ও সিলমোহর অনুমোদিত",
    "chairmanPage.milestonesTitle": "নেতৃত্বের যাত্রা ও মাইলফলক",
    "chairmanPage.milestone1Year": "১৯৯৮ – বর্তমান",
    "chairmanPage.milestone1Title": "প্রতিষ্ঠাতা পরিচালক, শ্যাম সেবা উদ্যোগ",
    "chairmanPage.milestone1Desc": "খাটু, রাজস্থানে আগত তীর্থযাত্রীদের জন্য প্রাথমিক চিকিৎসা শিবির এবং বিনামূল্যে রান্নাঘর পরিষেবার নেতৃত্ব দিয়েছেন।",
    "chairmanPage.milestone2Year": "২০১২",
    "chairmanPage.milestone2Title": "আধ্যাত্মিক সংস্কার পুরস্কার প্রাপক",
    "chairmanPage.milestone2Desc": "তীর্থযাত্রী ভিড় ব্যবস্থাপনা ডেটাবেস ও নিরাপত্তা আধুনিকীকরণের জন্য জাতীয়ভাবে স্বীকৃত।",
    "chairmanPage.milestone3Year": "২০২০",
    "chairmanPage.milestone3Title": "শ্রী শ্যাম জগতের বিশ্ব চেয়ারম্যান নিযুক্ত",
    "chairmanPage.milestone3Desc": "ডিজিটাইজেশন, বৈবাহিক প্ল্যাটফর্ম এবং রাজ্যব্যাপী শাখা একীকরণের নেতৃত্ব দিচ্ছেন।",
    "chairmanPage.credEducation": "শিক্ষা",
    "chairmanPage.credKeyResponsibility": "মূল দায়িত্ব",

    "mukhyaTrusteePage.breadcrumbCurrent": "মুখ্য ট্রাস্টি",
    "mukhyaTrusteePage.roleTitle": "মুখ্য ট্রাস্টি — শ্রী শ্যাম জগত",
    "mukhyaTrusteePage.bio": "প্রশাসনিক নৈতিকতা ও সম্প্রদায় কল্যাণের একটি স্তম্ভ, শ্রীমতি সুনীতা দেবী জি খাটু মন্দির পরিচালনা, নারী ক্ষমতায়ন এবং প্রবীণ পরিচর্যা কেন্দ্রে নিবেদিত ঐতিহ্যবাহী পারিবারিক ট্রাস্টগুলি পরিচালনা করেন।",
    "mukhyaTrusteePage.ctaConnect": "কার্যালয়ের সাথে যোগাযোগ করুন",
    "mukhyaTrusteePage.quoteTitle": "“প্রকৃত ক্ষমতায়ন মানে আমাদের কন্যাদের সক্ষম করা এবং আমাদের প্রবীণদের রক্ষা করা।”",
    "mukhyaTrusteePage.quoteBody": "“শ্যাম জগতের শক্তি নিহিত সবচেয়ে দুর্বলদের জন্য আমরা যে আত্মনির্ভরতা তৈরি করতে পারি তাতে। সক্রিয় দক্ষতা শিক্ষা এবং স্বচ্ছ দাতা সহায়তার মাধ্যমে, আমরা সকল জেলায় আমাদের নারী সমবায় ও প্রবীণ পরিচর্যা নেটওয়ার্ক সম্প্রসারণ করতে চাই।”",
    "mukhyaTrusteePage.visionTitle": "দৃষ্টিভঙ্গি ও কর্মক্ষেত্র",
    "mukhyaTrusteePage.focus1Title": "গ্রামীণ নারী ক্ষমতায়ন",
    "mukhyaTrusteePage.focus1Desc": "টেকসই আয় সক্ষমকারী বৃত্তিমূলক সেলাই, নকশা এবং কম্পিউটার সাক্ষরতা কেন্দ্র পরিচালনা।",
    "mukhyaTrusteePage.focus2Title": "প্রবীণ নাগরিক কল্যাণ",
    "mukhyaTrusteePage.focus2Desc": "জয়পুর ও সিকারের বৃদ্ধাশ্রমে মর্যাদাপূর্ণ আবাসন ও উচ্চ-যত্ন নার্সিং ইউনিট প্রতিষ্ঠা।",
    "mukhyaTrusteePage.focus3Title": "অনুপ সেবা বৈবাহিক পরিষেবা",
    "mukhyaTrusteePage.focus3Desc": "সম্প্রদায়-সমর্থিত অনলাইন ঘটকালি সহায়তার মাধ্যমে পারিবারিক মূল্যবোধ ও ঐতিহ্যবাহী কাঠামো সংরক্ষণ।",
    "mukhyaTrusteePage.credAreaOfWork": "কর্মক্ষেত্র",

