      "எங்கள் காலம் கடந்த பாரம்பரியங்களைப் பாதுகாத்து, எங்கள் உலகளாவிய பக்தர் சமூகத்தின் தற்கால தேவைகளை நிறைவேற்றி வருகிறோம்.",
