    "initiatives.card1.tag": "உணவு சேவா",
    "initiatives.card1.title": "அன்னதானம் (உணவு சேவா)",
    "initiatives.card1.desc": "ஒருவரும் பசியுடன் தூங்காமல் இருப்பதை உறுதி செய்தல் - ஒரு நேரத்தில் ஒரு வேளை உணவு, ஒரு வாழ்க்கை.",
    "initiatives.card2.tag": "கல்வி",
    "initiatives.card2.title": "கல்வி ஆதரவு",
    "initiatives.card2.desc": "உதவித்தொகைகள், வழிகாட்டுதல் மற்றும் வளங்கள் - ஏனெனில் ஒவ்வொரு குழந்தையும் கனவு காண தகுதியுடையது.",
    "initiatives.card3.tag": "ஸ்வச் வாஹினி",
    "initiatives.card3.title": "ஸ்வச் வாஹினி",
    "initiatives.card3.desc": "சமூகம் இயக்கும் முயற்சிகள் மூலம் தூய்மை, சுகாதாரம் மற்றும் சுற்றுச்சூழல் பராமரிப்பை மேம்படுத்துதல்.",
    "initiatives.card4.tag": "கோசாலை",
    "initiatives.card4.title": "கோசாலை",
    "initiatives.card4.desc": "கைவிடப்பட்ட மற்றும் காயமடைந்த பசுக்களுக்கு தங்குமிடம், ஊட்டச்சத்து மற்றும் மருத்துவ பராமரிப்பு வழங்குதல்.",
    "initiatives.card5.tag": "திருமண பணியகம்",
    "initiatives.card5.title": "திருமண பணியகம்",
    "initiatives.card5.desc": "சமூகத்திற்காக கட்டமைக்கப்பட்ட நம்பகமான, மதிப்புகள் சார்ந்த திருமண தளத்தின் மூலம் இதயங்களை இணைத்தல்.",
    "initiatives.card6.tag": "பராமரிப்பு & தங்குமிடம்",
    "initiatives.card6.title": "முதியோர் இல்லம்",
    "initiatives.card6.desc": "நமது முதியவர்களுக்கு பாதுகாப்பான, கண்ணியமான மற்றும் அன்பான வீடு - ஏனெனில் அவர்கள் இதற்கு குறைவாக எதையும் தகுதியானவர்கள் அல்ல.",
    "initiatives.explore": "மேலும் அறிக →",

