    "initiativesPage.contribute.title": "நீங்கள் எப்படி பங்களிக்க முடியும்",
    "initiativesPage.contribute.subtitle": "கொடுக்கும் ஒவ்வொரு செயலும் - பெரிதோ சிறிதோ - மாற்றத்தின் அலையை உருவாக்குகிறது.",
    "initiativesPage.contribute1.title": "தன்னார்வலராக சேருங்கள்",
    "initiativesPage.contribute1.desc": "உங்கள் நேரம் மற்றும் திறமைகளை எங்கள் சேவை திட்டங்களுக்கு அர்ப்பணித்து மக்களின் வாழ்க்கையில் நேரடி மாற்றத்தை ஏற்படுத்துங்கள்.",
    "initiativesPage.contribute1.cta": "தன்னார்வலராக சேருங்கள்",
    "initiativesPage.contribute2.title": "நன்கொடை அளியுங்கள்",
    "initiativesPage.contribute2.desc": "உங்கள் நன்கொடை மிகவும் தேவைப்படுபவர்களுக்கு உணவு, மருந்துகள், கல்வி மற்றும் தங்குமிடத்திற்கு நிதியளிக்கிறது.",
    "initiativesPage.contribute2.cta": "இப்போதே நன்கொடை அளியுங்கள்",
    "initiativesPage.contribute3.title": "உறுப்பினராகுங்கள்",
    "initiativesPage.contribute3.desc": "அதிகாரப்பூர்வ ஷ்யாம் ஜகத் உறுப்பினராகுங்கள் மற்றும் மாற்றத்தை உருவாக்குபவர்களின் எங்கள் வளர்ந்து வரும் குடும்பத்தின் ஒரு பகுதியாகுங்கள்.",
    "initiativesPage.contribute3.cta": "உறுப்பினராகுங்கள்",
    "initiativesPage.contribute4.title": "கல்வியை ஆதரிக்கவும்",
    "initiativesPage.contribute4.desc": "ஒரு குழந்தையின் கல்வியை ஆதரித்து, அவர்களுக்கு அறிவு, வாய்ப்பு மற்றும் பிரகாசமான எதிர்காலத்தின் பரிசை வழங்குங்கள்.",
    "initiativesPage.contribute4.cta": "ஒரு குழந்தையை ஆதரிக்கவும்",
    "initiativesPage.contribute5.title": "உணவை ஆதரிக்கவும்",
    "initiativesPage.contribute5.desc": "100 குடும்பங்களுக்கு ஒரு நாள் உணவுக்கு நிதியளித்து, இன்று இரவு யாரும் பசியுடன் தூங்காமல் இருப்பதற்கு காரணமாக இருங்கள்.",
    "initiativesPage.contribute5.cta": "உணவை ஆதரிக்கவும்",
    "initiativesPage.contribute6.title": "எங்களுடன் கூட்டு சேருங்கள்",
    "initiativesPage.contribute6.desc": "அமைப்புகள் மற்றும் வணிகங்கள் எங்கள் தாக்கத்தை அதிகரிக்கவும் மேலும் சமூகங்களை சென்றடையவும் எங்களுடன் கூட்டு சேரலாம்.",
    "initiativesPage.contribute6.cta": "எங்களுடன் கூட்டு சேருங்கள்",

    "eventsPage.hero.mantra": "|| ஜெய் ஸ்ரீ ஷ்யாம் ||",
    "eventsPage.hero.title": "புனித நிகழ்வுகள் & கொண்டாட்டங்கள்",
    "eventsPage.hero.subtitle": "பாபா ஷ்யாமிற்கு அர்ப்பணிக்கப்பட்ட வரவிருக்கும் ஆன்மீக கூட்டங்கள், பெரும் திருவிழாக்கள், கோவில் விழாக்கள் மற்றும் பாரம்பரிய கலாச்சார நிகழ்ச்சிகளை கண்டறிந்து பங்கேற்கவும்.",
    "eventsPage.hero.findEvents": "நிகழ்வுகளைக் கண்டறியவும்",
    "eventsPage.dateOption1": "தேதியைத் தேர்ந்தெடுக்கவும் (அனைத்து வரவிருக்கும்)",
    "eventsPage.dateOption2": "இந்த வாரம்",
