    "eventsPage.typeOption1": "நிகழ்வு வகை (அனைத்து பிரிவுகளும்)",
    "eventsPage.typeOption2": "கோவில் திருவிழா",
    "eventsPage.typeOption3": "இசை & பஜன்",
    "eventsPage.typeOption4": "சேவை & தொண்டு",
    "eventsPage.upcoming.eyebrow": "சிறப்பு கூட்டங்கள்",
    "eventsPage.upcoming.title": "முக்கிய வரவிருக்கும் நிகழ்வுகள்",
    "eventsPage.upcoming.desc": "தெய்வீக அருள் மற்றும் ஆன்மீக ஆனந்தத்தை அனுபவிக்கவும். இந்த வரவிருக்கும் முக்கிய சத்சங்குகளுக்கு உங்கள் இடங்களை முன்பதிவு செய்யவும், பயணத்தை ஒருங்கிணைக்கவும், நிஷான் பிரசாதத்தை பாதுகாக்கவும்.",
    "eventsPage.upcoming.freeEntry": "இலவச நுழைவு",
    "eventsPage.upcoming.registrationMandatory": "(பதிவு கட்டாயம்)",
