    "eventsPage.categories.desc": "உங்கள் பக்தி பாதையின் அடிப்படையில் நிகழ்வுகளை வடிகட்டவும். வழிபாடு, சமூக ஆதரவு மற்றும் ஆன்மீக கற்றலின் குறிப்பிட்ட பகுதிகளுக்கு ஏற்ப வடிவமைக்கப்பட்ட திட்டங்களுடன் இணையுங்கள்.",
