    "eventsPage.past.eyebrow": "பழைய நினைவுகள் தொகுப்பு",
    "eventsPage.past.title": "தெய்வீக மகிழ்ச்சி & சேவையின் தருணங்கள்",
    "eventsPage.past.desc": "எங்கள் வெற்றிகரமான சமூக முயற்சிகள், மாபெரும் கலாச்சார நிகழ்வுகள் மற்றும் கோவில் திருவிழாக்களை திரும்பிப் பார்க்கவும். எங்கள் கடந்த காலம் கூட்டு பக்தியின் உயிருள்ள சாட்சி.",
    "eventsPage.past1.title": "கோபாஷ்டமி கோசேவா கொண்டாட்டம்",
