    "eventsPage.past3.title": "ஷ்யாம் பஜன் சந்தியா - கொல்கத்தா",
    "eventsPage.past4.title": "குளிர்கால போர்வை விநியோக இயக்கம்",
    "eventsPage.hostCta.eyebrow": "நீங்கள் ஒரு கோவில் அல்லது சத்சங் சமிதியா?",
    "eventsPage.hostCta.title": "உங்கள் ஆன்மீக நிகழ்வுகளை நடத்தி விளம்பரப்படுத்துங்கள்",
    "eventsPage.hostCta.desc": "உங்கள் ஆன்மீக வளர்ச்சியை விரிவுபடுத்துங்கள். உலகளவில் மில்லியன் கணக்கான பக்தர்களுடன் இணைய உங்கள் வரவிருக்கும் கோவில் கொண்டாட்டங்கள், தொடர்ச்சியான நேரடி தரிசன நேரங்கள் அல்லது பஜன் கூட்டங்களை ஷ்ரீ ஷ்யாம் ஜகத்தில் பட்டியலிடுங்கள்.",
