    "teamPage.breadcrumb.ourTeam": "எங்கள் குழு",
    "teamPage.breadcrumb.overview": "கண்ணோட்டம்",
    "teamPage.hero.title": "எங்கள் குழு",
    "teamPage.hero.subtitle": "பாபா ஷ்யாமின் தெய்வீக அருளின் கீழ் எங்கள் உலகளாவிய சமூக-ஆன்மீக நோக்கத்தை வழிநடத்தவும், வளர்க்கவும், வலுப்படுத்தவும் ஒன்றாக பணியாற்றும் அர்ப்பணிப்புள்ள மக்களை சந்திக்கவும்.",
