    "teamPage.leader1.role": "தலைவர் — ஸ்ரீ ஷ்யாம் ஜகத்",
    "teamPage.leader1.desc": "எல்லைகள் மற்றும் முயற்சிகளில் எங்கள் முயற்சிகளை ஒன்றிணைக்க முக்கிய மூலோபாய பார்வை மற்றும் ஆன்மீக திசையை வழங்குதல்.",
    "teamPage.leader1.cta": "சுயவிவரத்தைப் பார்க்கவும் →",
    "teamPage.leader2.role": "முதன்மை அறங்காவலர்",
    "teamPage.leader2.desc": "மதிப்பு அடிப்படையிலான செயல்படுத்தலை உறுதிசெய்து, ஆன்மீக அறக்கட்டளைகளின் முக்கிய நிர்வாக மற்றும் நெறிமுறை கட்டமைப்புகளை மேற்பார்வையிடுதல்.",
    "teamPage.leader2.cta": "சுயவிவரத்தைப் பார்க்கவும் →",
    "teamPage.leader3.role": "நிர்வாகக் குழு",
    "teamPage.leader3.desc": "எங்கள் சட்டப்பூர்வ அறக்கட்டளைகளை வழிநடத்தும் ஆன்மீக பயிற்சியாளர்கள், வணிகத் தலைவர்கள் மற்றும் சமூக சீர்திருத்தவாதிகளின் மிகவும் அர்ப்பணிப்புள்ள குழு.",
    "teamPage.leader3.cta": "அனைத்து அறங்காவலர்களையும் காண்க →",
    "teamPage.management.title": "மேலாண்மைக் குழு",
    "teamPage.management.desc": "எங்கள் நிர்வாக செயல்பாடுகள், நிகழ்வு ஒருங்கிணைப்பாளர்கள் மற்றும் அன்றாட நிர்வாகப் பணியாளர்கள் உள்ளூர் தரிசனங்கள், திருமண இணைப்புகள், கோவில் பட்டியல் புதுப்பிப்புகள் மற்றும் மருத்துவ சேவைகள் தடையின்றி கையாளப்படுவதை உறுதிசெய்கின்றனர்.",
    "teamPage.management.cta": "மேலாண்மைக் குழுவைப் பார்க்கவும்",
    "teamPage.advisory.title": "ஆலோசனைக் குழு",
    "teamPage.advisory.desc": "எங்கள் கொள்கைகளை நெறிமுறை மற்றும் தர்மத்தில் நிலைநிறுத்தும் முனிவர்கள், ஓய்வுபெற்ற நீதிபதிகள் மற்றும் அதிக அனுபவம் வாய்ந்த சமூக மூத்தவர்கள்.",
    "teamPage.advisory.cta": "ஆலோசகர்களைச் சந்திக்கவும் →",
    "teamPage.stateCommittee.title": "மாநில குழு அணிகள்",
    "teamPage.stateCommittee.desc": "15+ இந்திய மாநிலங்களில் உள்ளூர் கிளைகள், கோவில் பதிவேடுகள், பஜன் சந்தியா முன்பதிவுகள் மற்றும் சமூக ஆதரவு வலையமைப்புகளை நிர்வகிக்கும் பிராந்திய அணிகள்.",
