    "registerPage.adSlot.desc": "நிதியுதவி பெற்ற உள்ளடக்கம், சிறப்பு பட்டியல்கள் அல்லது சமூக அறிவிப்புகளுக்காக இந்த உயர்-தெரிவுத்தன்மை இடத்தை ஒதுக்குங்கள்.",
