    "registerPage.hero.mantra": "|| ஜெய் ஸ்ரீ ஷ்யாம் ||",
    "registerPage.hero.title": "ஷ்யாம் ஜகத் சமூகத்தில் சேருங்கள்",
    "registerPage.hero.desc": "தனிநபராகவோ, அமைப்பாகவோ அல்லது சேவை வழங்குநராகவோ பதிவு செய்து, எங்கள் வளர்ந்து வரும் ஆன்மீக குடும்பத்தின் ஒரு பகுதியாகுங்கள். நம்பிக்கை, சேவை மற்றும் பக்தியில் ஒன்றிணையுங்கள்.",
