    "artistReg.heroTitle": "ஒரு கலைஞராக பதிவு செய்யவும்",
    "artistReg.heroDesc": "ஷ்யாம் ஜகத்தின் வளர்ந்து வரும் பக்தி கலைஞர் சமூகத்தில் சேருங்கள். இந்தியா முழுவதும் ஆன்மீக நிகழ்வுகள், கலாச்சார நிகழ்ச்சிகள் மற்றும் புனித கூட்டங்களில் உங்கள் திறமையை காட்சிப்படுத்துங்கள்.",
    "artistReg.expertiseTitle": "உங்கள் கலை & நிபுணத்துவம்",
    "artistReg.primaryLabel": "முதன்மை கலை வடிவம்",
    "artistReg.secondaryLabel": "இரண்டாம் கலை வடிவம் (விருப்பத்தேர்வு)",
    "artistReg.secondaryPlaceholder": "இரண்டாம் கலை வடிவத்தைத் தேர்ந்தெடுக்கவும்",
    "artistReg.guruLabel": "குரு / ஆசிரியர் பெயர் (விருப்பத்தேர்வு)",
    "artistReg.bioLabel": "சுருக்கமான சுயவிவரம் / உங்கள் கலை பற்றி",
    "artistReg.bioPlaceholder": "ஒரு கலைஞராக உங்கள் பயணம், உங்கள் பயிற்சி மற்றும் உங்கள் பக்தி கலைக்கு உத்வேகம் அளிப்பது பற்றி எங்களிடம் கூறுங்கள்...",
    "artistReg.dragDrop": "உங்கள் படங்கள், வீடியோக்கள் அல்லது ஆடியோ கோப்புகளை இங்கே இழுத்து விடவும்",
    "artistReg.artistType1": "பஜன் பாடகர்",
    "artistReg.artistType2": "இசைக் கலைஞர்",
    "artistReg.artistType3": "நடனக் கலைஞர்",
    "artistReg.artistType4": "பேச்சாளர்",
    "artistReg.artistType5": "ஓவியர்",
    "artistReg.artistType6": "இசையமைப்பாளர்",
    "artistReg.artistType7": "மற்றவை",
    "artistReg.whyTitle": "ஒரு கலைஞராக ஷ்யாம் ஜகத்தில் ஏன் சேர வேண்டும்?",
    "artistReg.whySubtitle": "பக்தியும் காட்சிப்படுத்தலும் சந்திக்கும் இடம். உங்கள் புனித கலையை கௌரவிக்கவும், உலகளாவிய பக்தர்களுடன் உங்களை இணைக்கவும் உருவாக்கப்பட்ட ஒரு தளத்தில் அடியெடுத்து வையுங்கள்.",
    "artistReg.whyFeature1Title": "ஆயிரக்கணக்கானோரை சென்றடையுங்கள்",
    "artistReg.whyFeature1Desc": "இந்தியா முழுவதும் உள்ள கோவில் வாரியங்கள் மற்றும் முன்னணி நிகழ்வு ஏற்பாட்டாளர்களால் கண்டறியப்படுங்கள்.",
    "artistReg.whyFeature2Title": "புனித மேடை",
    "artistReg.whyFeature2Desc": "மதிப்புமிக்க கோவில் திருவிழாக்கள், தொடர்ச்சியான சத்சங்குகள் மற்றும் முக்கிய கலாச்சார கூட்டங்களில் நிகழ்த்துங்கள்.",
    "artistReg.whyFeature3Title": "உங்கள் கலையை வளர்க்கவும்",
    "artistReg.whyFeature3Desc": "அனுபவம் வாய்ந்த பக்தி குருமார்களுடன் இணையுங்கள், நுட்பங்களை பரிமாறிக்கொள்ளுங்கள், உங்கள் ஆன்மீக வலையமைப்பை விரிவுபடுத்துங்கள்.",
    "artistReg.whyFeature4Title": "நியாயமான ஊதியம்",
    "artistReg.whyFeature4Desc": "வெளிப்படையான முன்பதிவு விதிமுறைகள் மற்றும் உங்கள் கணக்கிற்கு நேரடியாக விரைவான, சரிபார்க்கப்பட்ட டிஜிட்டல் பணம் செலுத்துதலை அனுபவிக்கவும்.",

    "dancerReg.heroTitle": "ஒரு நடனக் கலைஞராக பதிவு செய்யவும்",
    "dancerReg.heroDesc": "ஷ்யாம் ஜகத்தின் வளர்ந்து வரும் பக்தி நடனக் கலைஞர் சமூகத்தில் சேருங்கள். இந்தியா முழுவதும் ஆன்மீக நிகழ்வுகள், கலாச்சார நிகழ்ச்சிகள் மற்றும் புனித கூட்டங்களில் உங்கள் பாரம்பரிய மற்றும் பக்தி நடன நிகழ்ச்சிகளைப் பகிருங்கள்.",
    "dancerReg.expertiseTitle": "உங்கள் நடனம் & நிபுணத்துவம்",
