    "dancerReg.bioLabel": "சுருக்கமான சுயவிவரம் / உங்கள் நடனம் பற்றி",
    "dancerReg.bioPlaceholder": "ஒரு நடனக் கலைஞராக உங்கள் பயணம், உங்கள் பயிற்சி மற்றும் உங்கள் பக்தி நிகழ்ச்சிகளுக்கு உத்வேகம் அளிப்பது பற்றி எங்களிடம் கூறுங்கள்...",
