    "dancerReg.whyTitle": "ஒரு நடனக் கலைஞராக ஷ்யாம் ஜகத்தில் ஏன் சேர வேண்டும்?",
    "dancerReg.whySubtitle": "பக்தியும் காட்சிப்படுத்தலும் சந்திக்கும் இடம். உங்கள் புனித கலையை கௌரவிக்கவும், உலகளாவிய பக்தர்களுடன் உங்களை இணைக்கவும் உருவாக்கப்பட்ட ஒரு தளத்தில் அடியெடுத்து வையுங்கள்.",
    "dancerReg.whyFeature1Title": "ஆயிரக்கணக்கானோரை சென்றடையுங்கள்",
    "dancerReg.whyFeature1Desc": "இந்தியா முழுவதும் உள்ள கோவில் வாரியங்கள் மற்றும் முன்னணி நிகழ்வு ஏற்பாட்டாளர்களால் கண்டறியப்படுங்கள்.",
