    "dancerReg.whyFeature4Desc": "வெளிப்படையான முன்பதிவு விதிமுறைகள் மற்றும் உங்கள் கணக்கிற்கு நேரடியாக விரைவான, சரிபார்க்கப்பட்ட டிஜிட்டல் பணம் செலுத்துதலை அனுபவிக்கவும்.",

    "musicianReg.heroTitle": "ஒரு இசைக் கலைஞராக பதிவு செய்யவும்",
    "musicianReg.heroDesc": "ஷ்யாம் ஜகத்தின் வளர்ந்து வரும் பக்தி இசைக் கலைஞர் சமூகத்தில் சேருங்கள். இந்தியா முழுவதும் ஆன்மீக நிகழ்வுகள் மற்றும் புனித கூட்டங்களுக்கு தெய்வீக இசையை கொண்டு வாருங்கள் — கீர்த்தனை, பஜன் மற்றும் பாரம்பரிய இசை.",
