    "musicianReg.whyFeature4Desc": "வெளிப்படையான முன்பதிவு விதிமுறைகள் மற்றும் உங்கள் கணக்கிற்கு நேரடியாக விரைவான, சரிபார்க்கப்பட்ட டிஜிட்டல் பணம் செலுத்துதலை அனுபவிக்கவும்.",

    "templeReg.heroTitle": "உங்கள் கோவிலை பதிவு செய்யுங்கள்",
    "templeReg.heroDesc": "ஷ்யாம் ஜகத்தில் உங்கள் கோவிலை பட்டியலிட்டு மில்லியன் கணக்கான பக்தர்களுடன் இணையுங்கள். யாத்ரீகர்கள் உங்கள் புனித இடம், சேவைகள், தினசரி தரிசன நேரங்கள் மற்றும் வரவிருக்கும் திருவிழாக்களைக் கண்டறிய உதவுங்கள்.",
