    "templeReg.details.servicesLabel": "வழங்கப்படும் சேவைகள்",
    "templeReg.details.descLabel": "கோவிலின் சுருக்கமான விளக்கம்",
    "templeReg.details.descPlaceholder": "உங்கள் கோவிலின் வரலாறு, முக்கியத்துவம், புகழ்பெற்ற அற்புதங்கள் மற்றும் இந்த புனித இடத்தை சிறப்பாக்கும் விஷயங்களைப் பற்றி பக்தர்களுக்குக் கூறுங்கள்...",
    "templeReg.service1.title": "தினசரி தரிசனம்",
    "templeReg.service1.desc": "வழக்கமான பொது தரிசன நேரங்கள்",
