    "templeReg.service3.title": "திருமண விழாக்கள்",
    "templeReg.service3.desc": "புனித திருமணத்திற்கான இடம்/சேவைகள்",
    "templeReg.service4.title": "அன்னபூர்ணா சேவா (இலவச உணவு)",
    "templeReg.service4.desc": "இலவச சமூக சமையலறை / பண்டாரா",
