    "templeReg.service5.desc": "பிரவசனம், சத்சங் அல்லது கதா வசதிகள்",
    "templeReg.service6.title": "திருவிழா கொண்டாட்டங்கள்",
    "templeReg.service6.desc": "பால்குன் மேளா போன்ற பெரிய நிகழ்வுகளுக்கான சிறப்பு ஏற்பாடுகள்",
    "templeReg.service7.title": "தியான மண்டபம்",
    "templeReg.service7.desc": "அமைதியான பிரார்த்தனை/தியான இடம்",
    "templeReg.service8.title": "தர்மசாலா / விருந்தினர் தங்குமிடம்",
    "templeReg.service8.desc": "வரும் யாத்ரீகர்களுக்கான தங்குமிடம்",
    "templeReg.service9.title": "கோசாலா (பசு தங்குமிடம்)",
    "templeReg.service9.desc": "வளாகத்தில் புனித பசுக்களை பராமரித்தல்",
    "templeReg.service10.title": "வேத பாடசாலை",
    "templeReg.service10.desc": "வேதங்களுக்கான கல்வி திட்டங்கள்",
    "templeReg.gallery.title": "கோவில் புகைப்பட தொகுப்பு",
    "templeReg.gallery.dragDrop": "உங்கள் கோவிலின் படங்களை இங்கே இழுத்து விடவும் அல்லது",
    "templeReg.gallery.browse": "கோப்புகளை உலாவவும்",
    "templeReg.gallery.hint": "10 படங்கள் வரை பதிவேற்றவும். ஏற்கப்படும் வடிவங்கள்: JPG, PNG. ஒரு படத்திற்கு அதிகபட்சம் 5MB. முதன்மை தெய்வம், கோவிலின் வெளிப்புறம், உட்புறம் மற்றும் வளாகத்தின் படங்களைச் சேர்க்கவும்.",
    "templeReg.terms.certify": "வழங்கப்பட்ட தகவல் துல்லியமானது என்றும், கோவில் அறக்கட்டளையின் சார்பாக இந்த கோவிலை பதிவு செய்ய நான் அங்கீகரிக்கப்பட்டவன் என்றும் உறுதிப்படுத்துகிறேன்.",
    "templeReg.terms.agree": "ஷ்யாம் ஜகத் ஆன்மீக தளத்தின் சேவை விதிமுறைகள் மற்றும் தனியுரிமைக் கொள்கைக்கு நான் ஒப்புக்கொள்கிறேன்.",
    "templeReg.terms.consent": "தள புதுப்பிப்புகள் மற்றும் பக்தர் விசாரணைகள் குறித்த தகவல்தொடர்புகளைப் பெற நான் சம்மதிக்கிறேன்.",
    "templeReg.submit": "கோவில் பதிவை சமர்ப்பிக்கவும்",
    "templeReg.why.title": "ஷ்யாம் ஜகத்தில் உங்கள் கோவிலை ஏன் பட்டியலிட வேண்டும்?",
    "templeReg.why.subtitle": "உலகெங்கிலும் உள்ள மில்லியன் கணக்கான தேடுபவர்களுடன் பக்தியின் புனித இடங்களை இணைத்தல். தொடர்பை எளிதாக்குங்கள், நிகழ்வுகளை ஏற்பாடு செய்யுங்கள், சமூக ஆதரவை எளிதாக நிர்வகிக்கவும்.",
    "templeReg.whyFeature1Title": "பக்தர்களை சென்றடையுங்கள்",
    "templeReg.whyFeature1Desc": "அவர்களுக்கு அருகில் உள்ள கோவில்களைத் தேடும் மில்லியன் கணக்கான பக்தர்களுடன் இணையுங்கள், அவர்களை உங்கள் புனித தலத்திற்கு வழிநடத்துங்கள்.",
    "templeReg.whyFeature2Title": "நிகழ்வுகளை நிர்வகிக்கவும்",
    "templeReg.whyFeature2Desc": "வழக்கமான திருவிழாக்கள், சிறப்பு பூஜைகள் மற்றும் பண்டாராக்களை பரந்த, மிகவும் ஈடுபாடுள்ள பார்வையாளர்களுக்கு அறிவிக்கவும்.",
    "templeReg.whyFeature3Title": "நன்கொடைகளைப் பெறுங்கள்",
    "templeReg.whyFeature3Desc": "பாதுகாப்பாகவும் வெளிப்படையாகவும் ஆன்லைன் நன்கொடைகளை ஏற்றுக்கொள்ளுங்கள், கோவில் பராமரிப்புக்கான நேரடி நிதி ஆதரவை உருவாக்குங்கள்.",
    "templeReg.whyFeature4Title": "சமூகத்தை உருவாக்குங்கள்",
    "templeReg.whyFeature4Desc": "உங்கள் கோவில் பார்வையாளர்களை டிஜிட்டல்-முதல் வளர்த்து, ஆசீர்வாதங்களை அனுப்பி ஆன்மீக போதனைகளை சீராக பகிருங்கள்.",

    "teamShared.advertisement": "விளம்பரம்",
    "teamShared.adSpot300": "பக்தி விளம்பர இடம் — 300 × 250",
    "teamShared.viewProfile": "சுயவிவரத்தைக் காண்க",
