    "home.join.desc": "మా లక్ష్యంలో భాగం అవ్వండి మరియు మెరుగైన సమాజాన్ని సృష్టించడంలో మాకు సహాయం చేయండి.",
    "home.faq.title": "తరచుగా అడిగే ప్రశ్నలు",
    "home.faq.subtitle": "ప్రశ్నలు ఉన్నాయా? మా వద్ద సమాధానాలు ఉన్నాయి.",
    "home.faq.left.q1": "నేను శ్యామ్ జగత్‌కు ఎలా విరాళం ఇవ్వగలను?",
    "home.faq.left.a1": "మీరు మా వెబ్‌సైట్ ద్వారా ఆన్‌లైన్‌లో, UPI, బ్యాంక్ బదిలీ ద్వారా లేదా మా కార్యాలయాలలో వ్యక్తిగతంగా విరాళం ఇవ్వవచ్చు. అన్ని విరాళాలకు రసీదు ఇవ్వబడుతుంది మరియు అవి 80G పన్ను మినహాయింపు కలిగి ఉంటాయి.",
    "home.faq.left.q2": "నేను శ్యామ్ జగత్‌లో సభ్యుడిగా ఎలా మారగలను?",
    "home.faq.left.q3": "నేను శ్యామ్ జగత్‌తో ఎలా వాలంటీర్‌గా పనిచేయగలను?",
    "home.faq.left.q4": "వివాహ బ్యూరో సేవ ఉచితమేనా?",
    "home.faq.right.q1": "ఉద్యోగ పోర్టల్ ఎలా పనిచేస్తుంది?",
    "home.faq.right.a1": "మా పోర్టల్‌లో నమోదు చేసుకోండి, మీ ప్రొఫైల్ మరియు నైపుణ్యాలను అప్‌లోడ్ చేయండి, మా బృందం మిమ్మల్ని ధృవీకరించబడిన యజమానులు మరియు ఉద్యోగ అవకాశాలతో అనుసంధానిస్తుంది.",
    "home.faq.right.q2": "విద్యా స్కాలర్‌షిప్‌లకు ఎవరు అర్హులు?",
    "home.faq.right.q3": "ఒక సీనియర్ సిటిజన్ వృద్ధాశ్రమానికి ఎలా దరఖాస్తు చేసుకోవచ్చు?",
