    "home.contact.desc": "మీకు సహాయం చేయడానికి మేము ఎల్లప్పుడూ ఇక్కడ ఉన్నాము. మీకు ప్రశ్న ఉన్నా, వాలంటీర్‌గా పనిచేయాలనుకున్నా, విరాళం ఇవ్వాలనుకున్నా, లేదా సహాయం అవసరమైనా - మా హెల్ప్‌డెస్క్ మీ కోసం ఇక్కడ ఉంది.",
