    "initiativesPage.contribute.title": "మీరు ఎలా సహకరించవచ్చు",
    "initiativesPage.contribute.subtitle": "ఇచ్చే ప్రతి చర్య - పెద్దదైనా చిన్నదైనా - మార్పు తరంగాన్ని సృష్టిస్తుంది.",
    "initiativesPage.contribute1.title": "వాలంటీర్‌గా చేరండి",
    "initiativesPage.contribute1.desc": "మీ సమయం మరియు నైపుణ్యాలను మా సేవా కార్యక్రమాలకు అంకితం చేసి ప్రజల జీవితాల్లో ప్రత్యక్ష మార్పు తీసుకురండి.",
    "initiativesPage.contribute1.cta": "వాలంటీర్‌గా చేరండి",
    "initiativesPage.contribute2.title": "విరాళం ఇవ్వండి",
    "initiativesPage.contribute2.desc": "మీ విరాళం అత్యంత అవసరమైన వారికి ఆహారం, మందులు, విద్య మరియు ఆశ్రయానికి నిధులు సమకూరుస్తుంది.",
