    "artistReg.heroDesc": "శ్యామ్ జగత్ యొక్క పెరుగుతున్న భక్తి కళాకారుల సమాజంలో చేరండి. భారతదేశం అంతటా ఆధ్యాత్మిక కార్యక్రమాలు, సాంస్కృతిక కార్యక్రమాలు మరియు పవిత్ర సమావేశాలలో మీ ప్రతిభను ప్రదర్శించండి.",
