    "artistReg.whyTitle": "కళాకారుడిగా శ్యామ్ జగత్‌లో ఎందుకు చేరాలి?",
    "artistReg.whySubtitle": "భక్తి మరియు ప్రదర్శన కలిసే చోటు. మీ పవిత్ర కళను గౌరవించడానికి మరియు మిమ్మల్ని ప్రపంచవ్యాప్త భక్తులతో అనుసంధానించడానికి నిర్మించిన వేదికపైకి అడుగుపెట్టండి.",
    "artistReg.whyFeature1Title": "వేలాది మందిని చేరుకోండి",
    "artistReg.whyFeature1Desc": "భారతదేశం అంతటా ఆలయ బోర్డులు మరియు ప్రముఖ కార్యక్రమ నిర్వాహకులచే కనుగొనబడండి.",
    "artistReg.whyFeature2Title": "పవిత్ర వేదిక",
    "artistReg.whyFeature2Desc": "ప్రతిష్టాత్మక ఆలయ ఉత్సవాలు, నిరంతర సత్సంగాలు మరియు ప్రధాన సాంస్కృతిక సమావేశాలలో ప్రదర్శించండి.",
    "artistReg.whyFeature3Title": "మీ కళను పెంచుకోండి",
    "artistReg.whyFeature3Desc": "అనుభవజ్ఞులైన భక్తి గురువులతో కనెక్ట్ అవ్వండి, పద్ధతులను మార్పిడి చేసుకోండి మరియు మీ ఆధ్యాత్మిక నెట్‌వర్క్‌ను విస్తరించండి.",
    "artistReg.whyFeature4Title": "న్యాయమైన పరిహారం",
    "artistReg.whyFeature4Desc": "పారదర్శక బుకింగ్ నిబంధనలు మరియు మీ ఖాతాకు నేరుగా వేగవంతమైన, ధృవీకరించబడిన డిజిటల్ చెల్లింపులను అనుభవించండి.",

