    "musicianReg.heroDesc": "శ్యామ్ జగత్ యొక్క పెరుగుతున్న భక్తి సంగీతకారుల సమాజంలో చేరండి. భారతదేశం అంతటా ఆధ్యాత్మిక కార్యక్రమాలు మరియు పవిత్ర సమావేశాలకు దివ్య రాగాలను తీసుకురండి — కీర్తన, భజన మరియు శాస్త్రీయ సంగీతం.",
    "musicianReg.expertiseTitle": "మీ సంగీతం & నైపుణ్యం",
    "musicianReg.primaryLabel": "ప్రధాన వాయిద్యం / శైలి",
    "musicianReg.secondaryLabel": "ద్వితీయ వాయిద్యం / శైలి (ఐచ్ఛికం)",
    "musicianReg.secondaryPlaceholder": "ద్వితీయ వాయిద్యం / శైలిని ఎంచుకోండి",
    "musicianReg.guruLabel": "గురువు / సంగీత అకాడమీ పేరు (ఐచ్ఛికం)",
    "musicianReg.bioLabel": "సంక్షిప్త జీవిత చరిత్ర / మీ సంగీతం గురించి",
    "musicianReg.bioPlaceholder": "సంగీతకారుడిగా మీ ప్రయాణం, మీ శిక్షణ మరియు మీ భక్తి సంగీతాన్ని ప్రేరేపించేది గురించి మాకు చెప్పండి...",
    "musicianReg.dragDrop": "మీ ఫోటోలు, వీడియోలు లేదా ఆడియో ఫైళ్లను ఇక్కడ లాగి వదలండి",
    "musicianReg.instrumentGenre1": "గానం / భజన గానం",
    "musicianReg.instrumentGenre2": "తబలా",
    "musicianReg.instrumentGenre3": "హార్మోనియం",
    "musicianReg.instrumentGenre4": "సితార్",
