    "musicianReg.instrumentGenre7": "వయోలిన్",
    "musicianReg.instrumentGenre8": "ఇతర",
    "musicianReg.whyTitle": "సంగీతకారుడిగా శ్యామ్ జగత్‌లో ఎందుకు చేరాలి?",
    "musicianReg.whySubtitle": "భక్తి మరియు ప్రదర్శన కలిసే చోటు. మీ పవిత్ర కళను గౌరవించడానికి మరియు మిమ్మల్ని ప్రపంచవ్యాప్త భక్తులతో అనుసంధానించడానికి నిర్మించిన వేదికపైకి అడుగుపెట్టండి.",
    "musicianReg.whyFeature1Title": "వేలాది మందిని చేరుకోండి",
    "musicianReg.whyFeature1Desc": "భారతదేశం అంతటా ఆలయ బోర్డులు మరియు ప్రముఖ కార్యక్రమ నిర్వాహకులచే కనుగొనబడండి.",
    "musicianReg.whyFeature2Title": "పవిత్ర వేదిక",
    "musicianReg.whyFeature2Desc": "ప్రతిష్టాత్మక ఆలయ ఉత్సవాలు, నిరంతర సత్సంగాలు మరియు ప్రధాన సాంస్కృతిక సమావేశాలలో ప్రదర్శించండి.",
    "musicianReg.whyFeature3Title": "మీ నైపుణ్యాన్ని పెంచుకోండి",
    "musicianReg.whyFeature3Desc": "అనుభవజ్ఞులైన భక్తి గురువులతో కనెక్ట్ అవ్వండి, పద్ధతులను మార్పిడి చేసుకోండి మరియు మీ ఆధ్యాత్మిక నెట్‌వర్క్‌ను విస్తరించండి.",
    "musicianReg.whyFeature4Title": "న్యాయమైన పరిహారం",
    "musicianReg.whyFeature4Desc": "పారదర్శక బుకింగ్ నిబంధనలు మరియు మీ ఖాతాకు నేరుగా వేగవంతమైన, ధృవీకరించబడిన డిజిటల్ చెల్లింపులను అనుభవించండి.",

    "templeReg.heroTitle": "మీ ఆలయాన్ని నమోదు చేయండి",
    "templeReg.heroDesc": "శ్యామ్ జగత్‌లో మీ ఆలయాన్ని జాబితా చేసి లక్షలాది భక్తులతో కనెక్ట్ అవ్వండి. యాత్రికులు మీ పవిత్ర స్థలం, సేవలు, రోజువారీ దర్శన సమయాలు మరియు రాబోయే పండుగలను కనుగొనడంలో సహాయపడండి.",
