    "templeReg.gallery.title": "ఆలయ ఫోటో గ్యాలరీ",
    "templeReg.gallery.dragDrop": "మీ ఆలయం యొక్క ఫోటోలను ఇక్కడ లాగి వదలండి లేదా",
    "templeReg.gallery.browse": "ఫైళ్లను బ్రౌజ్ చేయండి",
    "templeReg.gallery.hint": "10 ఫోటోల వరకు అప్‌లోడ్ చేయండి. ఆమోదించబడిన ఫార్మాట్‌లు: JPG, PNG. ఫోటోకు గరిష్టంగా 5MB. ప్రధాన దేవత, ఆలయం బయటి భాగం, లోపలి భాగం మరియు ప్రాంగణ ఫోటోలను చేర్చండి.",
    "templeReg.terms.certify": "అందించిన సమాచారం ఖచ్చితమైనదని మరియు ఆలయ ధర్మకర్తృత్వం తరపున ఈ ఆలయాన్ని నమోదు చేయడానికి నేను అధికారం కలిగి ఉన్నానని ధృవీకరిస్తున్నాను.",
    "templeReg.terms.agree": "శ్యామ్ జగత్ ఆధ్యాత్మిక వేదిక యొక్క సేవా నిబంధనలు మరియు గోప్యతా విధానానికి నేను అంగీకరిస్తున్నాను.",
    "templeReg.terms.consent": "వేదిక నవీకరణలు మరియు భక్తుల విచారణల గురించి కమ్యూనికేషన్‌లను స్వీకరించడానికి నేను అంగీకరిస్తున్నాను.",
    "templeReg.submit": "ఆలయ నమోదును సమర్పించండి",
    "templeReg.why.title": "శ్యామ్ జగత్‌లో మీ ఆలయాన్ని ఎందుకు జాబితా చేయాలి?",
    "templeReg.why.subtitle": "ప్రపంచవ్యాప్తంగా లక్షలాది సాధకులతో భక్తి యొక్క పవిత్ర స్థలాలను కలుపుతోంది. కమ్యూనికేషన్‌ను సరళీకృతం చేయండి, కార్యక్రమాలను నిర్వహించండి మరియు సామాజిక మద్దతును సజావుగా నిర్వహించండి.",
    "templeReg.whyFeature1Title": "భక్తులను చేరుకోండి",
    "templeReg.whyFeature1Desc": "వారి సమీపంలో ఆలయాలను వెతుకుతున్న లక్షలాది భక్తులతో కనెక్ట్ అవ్వండి, వారిని మీ పవిత్ర స్థలానికి మార్గనిర్దేశం చేయండి.",
    "templeReg.whyFeature2Title": "కార్యక్రమాలను నిర్వహించండి",
    "templeReg.whyFeature2Desc": "సాధారణ పండుగలు, ప్రత్యేక పూజలు మరియు భండారాలను విస్తృత, అత్యంత నిమగ్నమైన ప్రేక్షకులకు ప్రకటించండి.",
    "templeReg.whyFeature3Title": "విరాళాలను స్వీకరించండి",
    "templeReg.whyFeature3Desc": "ఆన్‌లైన్ విరాళాలను సురక్షితంగా మరియు పారదర్శకంగా స్వీకరించండి, ఆలయ నిర్వహణ కోసం ప్రత్యక్ష ఆర్థిక మద్దతును సృష్టించండి.",
    "templeReg.whyFeature4Title": "సమాజాన్ని నిర్మించండి",
    "templeReg.whyFeature4Desc": "మీ ఆలయ ప్రేక్షకులను డిజిటల్-ఫస్ట్‌గా పెంచండి, ఆశీర్వాదాలు పంపడం మరియు ఆధ్యాత్మిక బోధనలను సజావుగా పంచుకోండి.",

