    "managementTeamPage.member4Desc": "భజన సంధ్యా ప్రసారాలు, ప్రత్యక్ష ప్రసారాలను సమన్వయం చేస్తారు మరియు నెలవారీ ఆధ్యాత్మిక వార్తాలేఖను నవీకరిస్తారు.",
    "managementTeamPage.member5Role": "కమ్యూనిటీ సేవా అధిపతి",
    "managementTeamPage.member5Dept": "అవుట్‌రీచ్",
    "managementTeamPage.member5Desc": "యాత్రికుల వైద్య సహాయ శిబిరాలు, ఆహార పంపిణీలు మరియు వాలంటీర్ మోహరింపు ప్రణాళికలను నడిపిస్తారు.",
    "managementTeamPage.member6Role": "జనరల్ లీగల్ కౌన్సెల్",
    "managementTeamPage.member6Dept": "న్యాయ & SLA లు",
    "managementTeamPage.member6Desc": "ధర్మకర్త ధృవీకరణలు, భూమి నిర్వహణ మరియు శాసనపరమైన నిర్మాణాల కోసం నిర్మాణాత్మక అనుగుణ్యతను నిర్ధారిస్తారు.",

    "trusteesPage.breadcrumbCurrent": "ధర్మకర్తలు",
    "trusteesPage.heroTitle": "మా ధర్మకర్తలు",
    "trusteesPage.heroDesc": "శ్రీ శ్యామ్ జగత్ ధర్మకర్తల మండలిలో మా పారదర్శక సామాజిక కార్యక్రమాలను నడిపించే ప్రముఖ నాయకులు, ఆధ్యాత్మిక సంస్కర్తలు మరియు దాతృత్వ ప్రేమికులు ఉన్నారు.",
    "trusteesPage.trustee1Desc": "ఐటి పరివర్తన, ఆలయ ధృవీకరణ నెట్‌వర్క్‌లు మరియు డేటా పారదర్శకత కార్యక్రమాలను పర్యవేక్షిస్తారు.",
    "trusteesPage.trustee2Desc": "ఆర్థిక ఆడిట్‌లు, న్యాయపరమైన అనుగుణ్యతలు మరియు పెద్ద నిధి కేటాయింపులను నిర్దేశిస్తారు.",
    "trusteesPage.trustee3Desc": "వాలంటీర్ సమీకరణ, కార్పొరేట్ సామాజిక బాధ్యత (CSR) భాగస్వామ్యాలు మరియు సాంస్కృతిక కార్యక్రమాలను పర్యవేక్షిస్తారు.",
    "trusteesPage.trustee4Desc": "మధ్య భారతదేశం అంతటా ఆహార పంపిణీ నెట్‌వర్క్‌లు మరియు మొబైల్ ఆరోగ్య క్లినిక్‌లను సమన్వయం చేస్తారు.",
    "trusteesPage.trustee5Desc": "ప్రామాణిక ఆధ్యాత్మిక సాహిత్య ప్రచురణ మరియు భజన కళాకారుల సమన్వయాన్ని ఆదరిస్తారు.",
    "trusteesPage.trustee6Desc": "పురాతన మాన్యుస్క్రిప్ట్‌లు మరియు ఆలయ సంగీత సంప్రదాయాల వారసత్వ పరిరక్షణను నిర్వహిస్తారు.",
