    "initiatives.card3.desc": "സമൂഹ നേതൃത്വത്തിലുള്ള സംരംഭങ്ങളിലൂടെ ശുചിത്വം, ആരോഗ്യ സംരക്ഷണം, പരിസ്ഥിതി പരിപാലനം എന്നിവ പ്രോത്സാഹിപ്പിക്കുന്നു.",
