    "teamPage.leader2.desc": "മൂല്യാധിഷ്ഠിത നിർവ്വഹണം ഉറപ്പാക്കി ആത്മീയ ട്രസ്റ്റുകളുടെ പ്രധാന ഭരണപരവും ധാർമ്മികവുമായ ചട്ടക്കൂടുകൾ മേൽനോട്ടം വഹിക്കുന്നു.",
