    "teamPage.leader3.desc": "ഞങ്ങളുടെ നിയമപരമായ ട്രസ്റ്റുകളെ നയിക്കുന്ന ആത്മീയ സാധകർ, ബിസിനസ് നേതാക്കൾ, സാമൂഹിക പരിഷ്കർത്താക്കൾ എന്നിവരുടെ അത്യധികം അർപ്പണബോധമുള്ള ഒരു സമിതി.",
