    "teamPage.management.desc": "ഞങ്ങളുടെ എക്സിക്യൂട്ടീവ് പ്രവർത്തനങ്ങൾ, ഇവന്റ് കോർഡിനേറ്റർമാർ, ദൈനംദിന ഭരണ ജീവനക്കാർ എന്നിവർ പ്രാദേശിക ദർശനങ്ങൾ, വൈവാഹിക ബന്ധങ്ങൾ, ക്ഷേത്ര പട്ടിക അപ്ഡേറ്റുകൾ, മെഡിക്കൽ സേവകൾ എന്നിവ സുഗമമായി കൈകാര്യം ചെയ്യുന്നുവെന്ന് ഉറപ്പാക്കുന്നു.",
    "teamPage.management.cta": "മാനേജ്മെന്റ് ടീം കാണുക",
    "teamPage.advisory.title": "ഉപദേശക സമിതി",
    "teamPage.advisory.desc": "ഞങ്ങളുടെ നയങ്ങളെ ധാർമ്മികതയിലും ധർമ്മത്തിലും ഉറപ്പിച്ചു നിർത്തുന്ന ഋഷിമാർ, വിരമിച്ച ന്യായാധിപന്മാർ, അതിയായ പരിചയസമ്പന്നരായ സമൂഹ മുതിർന്നവർ.",
    "teamPage.advisory.cta": "ഉപദേശകരെ കാണുക →",
    "teamPage.stateCommittee.title": "സംസ്ഥാന കമ്മിറ്റി ടീമുകൾ",
    "teamPage.stateCommittee.desc": "15+ ഇന്ത്യൻ സംസ്ഥാനങ്ങളിലുടനീളം പ്രാദേശിക ശാഖകൾ, ക്ഷേത്ര രജിസ്ട്രികൾ, ഭജൻ സന്ധ്യ ബുക്കിംഗുകൾ, സാമൂഹിക പിന്തുണാ ശൃംഖലകൾ എന്നിവ കൈകാര്യം ചെയ്യുന്ന പ്രാദേശിക ടീമുകൾ.",
