    "registerPage.step1.desc": "നിങ്ങളുടെ ആത്മീയ കല, സേവനങ്ങൾ, അല്ലെങ്കിൽ സ്ഥാപനവുമായി ഏറ്റവും യോജിക്കുന്ന പ്രൊഫൈൽ തിരഞ്ഞെടുക്കുക.",
