    "registerPage.step2.desc": "നിങ്ങളുടെ യഥാർത്ഥ യോഗ്യതകളും പോർട്ട്‌ഫോളിയോയും ഉപയോഗിച്ച് സുരക്ഷിത രജിസ്ട്രേഷൻ ഫോം പൂർത്തിയാക്കുക.",
