    "registerPage.testimonials.eyebrow": "അഭിപ്രായങ്ങൾ",
    "registerPage.testimonials.title": "ഞങ്ങളുടെ പുണ്യ കുടുംബത്തിൽ നിന്നുള്ള ശബ്ദങ്ങൾ",
    "registerPage.testimonial1.quote": "ശ്യാം ജഗതിന്റെ പ്ലാറ്റ്‌ഫോമിന് കീഴിൽ ഖാടു ശ്യാം ജി പരിപാടികളിൽ ഭജൻ പാടുന്നത് എന്റെ കരിയറിന്റെ പരമോന്നത ശിഖരമായിരുന്നു. ഊർജ്ജവും മാനേജ്മെന്റും തികച്ചും ആത്മീയമാണ്.",
    "registerPage.testimonial1.role": "ഭജൻ ഗായകൻ",
    "registerPage.testimonial2.quote": "ഞങ്ങളുടെ ചരിത്രപ്രധാനമായ ക്ഷേത്രം രജിസ്റ്റർ ചെയ്തത് ഞങ്ങളെ പൂർണ്ണമായും ഓൺലൈനിൽ കൊണ്ടുവന്നു. ഇപ്പോൾ ഞങ്ങൾ ദർശന ബുക്കിംഗുകൾ സുഗമമായി കൈകാര്യം ചെയ്യുകയും രാജ്യമെമ്പാടുമുള്ള മുതിർന്നവർക്ക് ആരതി സ്ട്രീം ചെയ്യുകയും ചെയ്യാം.",
    "registerPage.testimonial2.role": "ക്ഷേത്ര ഭരണാധികാരി",
    "registerPage.testimonial3.quote": "ഒരു ക്ലാസിക്കൽ കഥക് നർത്തകി എന്ന നിലയിൽ, ശരിയായ ആത്മീയ പ്ലാറ്റ്‌ഫോമുകൾ കണ്ടെത്തുന്നത് ബുദ്ധിമുട്ടായിരുന്നു. ശ്യാം ജഗത് ഞങ്ങളെ ഇന്ത്യയിലുടനീളമുള്ള പ്രധാന ദിവ്യ പരിപാടികളുമായി നേരിട്ട് ബന്ധിപ്പിച്ചു.",
    "registerPage.testimonial3.role": "ക്ലാസിക്കൽ നർത്തകി",
    "registerPage.faq.eyebrow": "ചോദ്യങ്ങൾ",
    "registerPage.faq.title": "പതിവായി ചോദിക്കുന്ന ചോദ്യങ്ങൾ",
    "registerPage.faq1.q": "എന്തെങ്കിലും രജിസ്ട്രേഷൻ ഫീസ് ഉണ്ടോ?",
    "registerPage.faq1.a": "ഇല്ല, ശ്യാം ജഗത് പ്ലാറ്റ്‌ഫോമിലെ രജിസ്ട്രേഷൻ എല്ലാ വ്യക്തിഗത കലാകാരന്മാർക്കും, ക്ഷേത്രങ്ങൾക്കും, സ്ഥാപനങ്ങൾക്കും തികച്ചും സൗജന്യമാണ്.",
    "registerPage.faq2.q": "സ്ഥിരീകരണ പ്രക്രിയ എന്താണ്?",
    "registerPage.faq2.a": "ഞങ്ങളുടെ സമർപ്പിത സേവാ സമിതി ഓരോ പ്രൊഫൈലും 24 മുതൽ 48 മണിക്കൂറിനുള്ളിൽ അവലോകനം ചെയ്യുന്നു. ഞങ്ങളുടെ ഡയറക്ടറിയുടെ പുണ്യ അന്തരീക്ഷം നിലനിർത്താൻ ഞങ്ങൾ തിരിച്ചറിയൽ രേഖകളും യോഗ്യതകളും സ്ഥിരീകരിക്കുന്നു.",
    "registerPage.faq3.q": "എനിക്ക് ഒന്നിലധികം പ്രൊഫൈലുകൾ കൈകാര്യം ചെയ്യാൻ കഴിയുമോ?",
    "registerPage.faq3.a": "അതെ, നിങ്ങൾക്ക് ഒരു വ്യക്തിയായി രജിസ്റ്റർ ചെയ്യാനും ഏകീകൃത അഡ്മിൻ ഡാഷ്‌ബോർഡ് ഉപയോഗിച്ച് ഒരു ക്ഷേത്രമോ മണ്ഡൽ ലിസ്റ്റിംഗോ കൈകാര്യം ചെയ്യാനും കഴിയും.",
    "registerPage.faq4.q": "യാത്രക്കാർ ധർമ്മശാലകളെ എങ്ങനെ ബന്ധപ്പെടും?",
    "registerPage.faq4.a": "ലിസ്റ്റ് ചെയ്തുകഴിഞ്ഞാൽ, നിങ്ങളുടെ ബന്ധപ്പെടാനുള്ള വിവരങ്ങൾ, സ്ഥാന ഭൂപടം, ബുക്കിംഗ് മാർഗ്ഗനിർദ്ദേശങ്ങൾ എന്നിവ ഉടനടി വിളിക്കാനോ ബുക്ക് ചെയ്യാനോ കഴിയുന്ന ദശലക്ഷക്കണക്കിന് തീർത്ഥാടകർക്ക് നേരിട്ട് ദൃശ്യമാകും.",
    "registerPage.cta.title": "ഞങ്ങളുടെ കുടുംബത്തിൽ ചേരാൻ തയ്യാറാണോ?",
    "registerPage.cta.desc": "വിശ്വാസത്തിന്റെ ഒരു കുതിച്ചുചാട്ടം നടത്തുക. രജിസ്റ്റർ ചെയ്യാൻ 5 മിനിറ്റിൽ താഴെ സമയമെടുക്കും, ഇത് 100% സൗജന്യമാണ്. ദശലക്ഷക്കണക്കിന് ബാബാ ശ്യാം ഭക്തരുമായി നേരിട്ട് ബന്ധപ്പെടുക.",
    "registerPage.cta.button": "രജിസ്ട്രേഷൻ ആരംഭിക്കുക",

