    "artistReg.heroTitle": "ഒരു കലാകാരനായി രജിസ്റ്റർ ചെയ്യുക",
    "artistReg.heroDesc": "ശ്യാം ജഗതിന്റെ വളരുന്ന ഭക്തി കലാകാരന്മാരുടെ സമൂഹത്തിൽ ചേരുക. ഇന്ത്യയിലുടനീളമുള്ള ആത്മീയ പരിപാടികൾ, സാംസ്കാരിക പരിപാടികൾ, പുണ്യ സംഗമങ്ങൾ എന്നിവയിൽ നിങ്ങളുടെ കഴിവ് പ്രദർശിപ്പിക്കുക.",
