    "artistReg.whyTitle": "ഒരു കലാകാരനായി ശ്യാം ജഗതിൽ എന്തുകൊണ്ട് ചേരണം?",
    "artistReg.whySubtitle": "ഭക്തിയും പ്രദർശനവും കൂടിച്ചേരുന്നിടം. നിങ്ങളുടെ പുണ്യ കലയെ ആദരിക്കാനും ആഗോള ഭക്തരുമായി നിങ്ങളെ ബന്ധിപ്പിക്കാനും നിർമ്മിച്ച ഒരു പ്ലാറ്റ്‌ഫോമിലേക്ക് കാലെടുത്തുവെക്കുക.",
    "artistReg.whyFeature1Title": "ആയിരക്കണക്കിനാളുകളിലേക്ക് എത്തുക",
    "artistReg.whyFeature1Desc": "ഇന്ത്യയിലുടനീളമുള്ള ക്ഷേത്ര ബോർഡുകളും പ്രമുഖ പരിപാടി സംഘാടകരും കണ്ടെത്തട്ടെ.",
    "artistReg.whyFeature2Title": "പുണ്യ വേദി",
    "artistReg.whyFeature2Desc": "അഭിമാനകരമായ ക്ഷേത്ര ഉത്സവങ്ങൾ, തുടർച്ചയായ സത്സംഗങ്ങൾ, പ്രധാന സാംസ്കാരിക സംഗമങ്ങൾ എന്നിവയിൽ അവതരിപ്പിക്കുക.",
    "artistReg.whyFeature3Title": "നിങ്ങളുടെ കല വളർത്തുക",
    "artistReg.whyFeature3Desc": "പരിചയസമ്പന്നരായ ഭക്തി ഗുരുക്കന്മാരുമായി ബന്ധപ്പെടുക, സാങ്കേതികവിദ്യകൾ കൈമാറുക, നിങ്ങളുടെ ആത്മീയ ശൃംഖല വിപുലീകരിക്കുക.",
    "artistReg.whyFeature4Title": "ന്യായമായ പ്രതിഫലം",
    "artistReg.whyFeature4Desc": "സുതാര്യമായ ബുക്കിംഗ് നിബന്ധനകളും നിങ്ങളുടെ അക്കൗണ്ടിലേക്ക് നേരിട്ട് വേഗത്തിലുള്ള, സ്ഥിരീകരിച്ച ഡിജിറ്റൽ പേയ്‌മെന്റുകളും അനുഭവിക്കുക.",

    "dancerReg.heroTitle": "ഒരു നർത്തകനായി രജിസ്റ്റർ ചെയ്യുക",
    "dancerReg.heroDesc": "ശ്യാം ജഗതിന്റെ വളരുന്ന ഭക്തി നർത്തകരുടെ സമൂഹത്തിൽ ചേരുക. ഇന്ത്യയിലുടനീളമുള്ള ആത്മീയ പരിപാടികൾ, സാംസ്കാരിക പരിപാടികൾ, പുണ്യ സംഗമങ്ങൾ എന്നിവയിൽ നിങ്ങളുടെ ക്ലാസിക്കൽ, ഭക്തി നൃത്ത അവതരണങ്ങൾ പങ്കിടുക.",
    "dancerReg.expertiseTitle": "നിങ്ങളുടെ നൃത്തവും വൈദഗ്ധ്യവും",
