    "dancerReg.guruLabel": "ഗുരു / നൃത്ത അക്കാദമിയുടെ പേര് (ഓപ്ഷണൽ)",
    "dancerReg.bioLabel": "ഹ്രസ്വ ജീവചരിത്രം / നിങ്ങളുടെ നൃത്തത്തെക്കുറിച്ച്",
    "dancerReg.bioPlaceholder": "ഒരു നർത്തകനെന്ന നിലയിൽ നിങ്ങളുടെ യാത്ര, പരിശീലനം, നിങ്ങളുടെ ഭക്തി അവതരണങ്ങളെ പ്രചോദിപ്പിക്കുന്നത് എന്നിവയെക്കുറിച്ച് ഞങ്ങളോട് പറയുക...",
