    "musicianReg.heroTitle": "ഒരു സംഗീതജ്ഞനായി രജിസ്റ്റർ ചെയ്യുക",
    "musicianReg.heroDesc": "ശ്യാം ജഗതിന്റെ വളരുന്ന ഭക്തി സംഗീതജ്ഞരുടെ സമൂഹത്തിൽ ചേരുക. ഇന്ത്യയിലുടനീളമുള്ള ആത്മീയ പരിപാടികളിലേക്കും പുണ്യ സംഗമങ്ങളിലേക്കും ദിവ്യ സംഗീതം കൊണ്ടുവരിക — കീർത്തനം, ഭജൻ, ക്ലാസിക്കൽ സംഗീതം.",
