    "templeReg.heroTitle": "നിങ്ങളുടെ ക്ഷേത്രം രജിസ്റ്റർ ചെയ്യുക",
    "templeReg.heroDesc": "ശ്യാം ജഗതിൽ നിങ്ങളുടെ ക്ഷേത്രം ലിസ്റ്റ് ചെയ്ത് ദശലക്ഷക്കണക്കിന് ഭക്തരുമായി ബന്ധപ്പെടുക. തീർത്ഥാടകർ നിങ്ങളുടെ പുണ്യ സ്ഥലം, സേവനങ്ങൾ, ദൈനംദിന ദർശന സമയങ്ങൾ, വരാനിരിക്കുന്ന ഉത്സവങ്ങൾ എന്നിവ കണ്ടെത്താൻ സഹായിക്കുക.",
