    "templeReg.gallery.title": "ക്ഷേത്ര ഫോട്ടോ ഗാലറി",
    "templeReg.gallery.dragDrop": "നിങ്ങളുടെ ക്ഷേത്രത്തിന്റെ ഫോട്ടോകൾ ഇവിടെ വലിച്ചിടുക അല്ലെങ്കിൽ",
    "templeReg.gallery.browse": "ഫയലുകൾ ബ്രൗസ് ചെയ്യുക",
    "templeReg.gallery.hint": "10 ഫോട്ടോകൾ വരെ അപ്‌ലോഡ് ചെയ്യുക. സ്വീകാര്യമായ ഫോർമാറ്റുകൾ: JPG, PNG. ഫോട്ടോയ്ക്ക് പരമാവധി 5MB. പ്രധാന ദേവത, ക്ഷേത്രത്തിന്റെ പുറംഭാഗം, അകത്തളം, പരിസരം എന്നിവയുടെ ഫോട്ടോകൾ ഉൾപ്പെടുത്തുക.",
    "templeReg.terms.certify": "നൽകിയ വിവരങ്ങൾ കൃത്യമാണെന്നും ക്ഷേത്ര ട്രസ്റ്റിന് വേണ്ടി ഈ ക്ഷേത്രം രജിസ്റ്റർ ചെയ്യാൻ ഞാൻ അധികാരപ്പെട്ടിട്ടുണ്ടെന്നും ഞാൻ സാക്ഷ്യപ്പെടുത്തുന്നു.",
    "templeReg.terms.agree": "ശ്യാം ജഗത് ആത്മീയ പ്ലാറ്റ്‌ഫോമിന്റെ സേവന നിബന്ധനകളും സ്വകാര്യതാ നയവും ഞാൻ അംഗീകരിക്കുന്നു.",
    "templeReg.terms.consent": "പ്ലാറ്റ്‌ഫോം അപ്‌ഡേറ്റുകളെയും ഭക്തരുടെ അന്വേഷണങ്ങളെയും കുറിച്ചുള്ള ആശയവിനിമയങ്ങൾ സ്വീകരിക്കാൻ ഞാൻ സമ്മതിക്കുന്നു.",
    "templeReg.submit": "ക്ഷേത്ര രജിസ്ട്രേഷൻ സമർപ്പിക്കുക",
    "templeReg.why.title": "എന്തുകൊണ്ട് ശ്യാം ജഗതിൽ നിങ്ങളുടെ ക്ഷേത്രം ലിസ്റ്റ് ചെയ്യണം?",
    "templeReg.why.subtitle": "ലോകമെമ്പാടുമുള്ള ദശലക്ഷക്കണക്കിന് അന്വേഷകരുമായി ഭക്തിയുടെ പുണ്യ സ്ഥലങ്ങളെ ബന്ധിപ്പിക്കുന്നു. ആശയവിനിമയം ലളിതമാക്കുക, പരിപാടികൾ സംഘടിപ്പിക്കുക, സാമൂഹിക പിന്തുണ അനായാസം കൈകാര്യം ചെയ്യുക.",
    "templeReg.whyFeature1Title": "ഭക്തരിലേക്ക് എത്തുക",
    "templeReg.whyFeature1Desc": "അവർക്ക് സമീപമുള്ള ക്ഷേത്രങ്ങൾ തിരയുന്ന ദശലക്ഷക്കണക്കിന് ഭക്തരുമായി ബന്ധപ്പെടുക, അവരെ നിങ്ങളുടെ പുണ്യ സ്ഥലത്തേക്ക് നയിക്കുക.",
    "templeReg.whyFeature2Title": "പരിപാടികൾ കൈകാര്യം ചെയ്യുക",
    "templeReg.whyFeature2Desc": "പതിവ് ഉത്സവങ്ങൾ, പ്രത്യേക പൂജകൾ, ഭണ്ഡാരകൾ എന്നിവ വിശാലവും ഉയർന്ന ഇടപഴകലുള്ളതുമായ പ്രേക്ഷകരോട് പ്രഖ്യാപിക്കുക.",
    "templeReg.whyFeature3Title": "സംഭാവനകൾ സ്വീകരിക്കുക",
    "templeReg.whyFeature3Desc": "സുരക്ഷിതമായും സുതാര്യമായും ഓൺലൈൻ സംഭാവനകൾ സ്വീകരിക്കുക, ക്ഷേത്ര പരിപാലനത്തിനായി നേരിട്ടുള്ള സാമ്പത്തിക പിന്തുണ സൃഷ്ടിക്കുക.",
    "templeReg.whyFeature4Title": "സമൂഹം കെട്ടിപ്പടുക്കുക",
    "templeReg.whyFeature4Desc": "നിങ്ങളുടെ ക്ഷേത്ര പ്രേക്ഷകരെ ഡിജിറ്റൽ-ആദ്യം വളർത്തുക, അനുഗ്രഹങ്ങൾ അയയ്ക്കുകയും ആത്മീയ പഠിപ്പിക്കലുകൾ സുഗമമായി പങ്കിടുകയും ചെയ്യുക.",

    "teamShared.advertisement": "പരസ്യം",
