    "stateTeamPage.mapDesc": "ദർശന പ്രവർത്തനങ്ങൾ, തീർത്ഥാടക ഭക്ഷണ അടുക്കളകൾ, സംസ്ഥാന ചാപ്റ്റർ പിന്തുണ എന്നിവ കൈകാര്യം ചെയ്യുന്ന സജീവ പ്രാദേശിക കമ്മിറ്റികളുമായി 15+ സംസ്ഥാനങ്ങളിലുടനീളം ഭക്തിയെ ബന്ധിപ്പിക്കുന്നു.",
