    "home.hero.missionTitle": "અમારું મિશન",
    "home.hero.missionText": "શ્રદ્ધા, સેવા અને કરુણાથી જોડાયેલા ભક્તોનો વૈશ્વિક સમુદાય બનાવવો.",
    "home.about.eyebrow": "વિશે",
    "home.about.body": "શ્યામ જગત બાબા શ્યામથી પ્રેરિત એક આધ્યાત્મિક અને સામાજિક સંસ્થા છે, જે શ્રદ્ધા અને કર્મ દ્વારા માનવતાની સેવા માટે સમર્પિત છે. અમે બાળકો માટે ગુણવત્તાયુક્ત શિક્ષણ, રોજગાર માટે કૌશલ્ય તાલીમ, ખાદ્ય સુરક્ષા માટે મફત ભોજન, બેઘર લોકો માટે સુરક્ષિત આશ્રય, મફત આરોગ્ય શિબિરો અને મહિલા સશક્તિકરણ કાર્યક્રમો દ્વારા સમુદાયોને ઉત્થાન આપીએ છીએ. સાથે મળીને, અમારું લક્ષ્ય એક દયાળુ અને આત્મનિર્ભર સમાજ બનાવવાનું છે જ્યાં દરેક વ્યક્તિ ગૌરવ સાથે વિકાસ કરી શકે.",
    "home.about.knowMore": "વધુ જાણો",
    "home.baba.body": "\"ભીમના પૌરાણિક પૌત્ર બર્બરીક તરીકે જન્મેલા, તેમની પાસે અજોડ યોદ્ધા શક્તિ હતી. છતાં, ધર્મ (સત્ય)ની જીત માટે પોતાના માથાનું સર્વોચ્ચ બલિદાન આપવું એ તેમનું સૌથી મોટું કાર્ય હતું. તેમની નિ:સ્વાર્થ ભક્તિથી પ્રસન્ન થઈને, ભગવાન કૃષ્ણએ તેમને પોતાનું નામ—શ્યામ—આપ્યું અને વરદાન આપ્યું કે કળિયુગમાં તેઓ પરાજિતોના પરમ રક્ષક તરીકે પૂજાશે.\"",
