    "home.initiatives.titleHighlight": "પહેલ",
    "home.initiatives.subtitle": "શ્રદ્ધાથી પ્રેરિત, કરુણાથી ટકાવેલ - સમાજના દરેક પાસામાં જીવનની સેવા.",
    "home.initiatives.learnMore": "વધુ જાણો",
    "home.success.title": "સફળતાની વાર્તાઓ",
    "home.success.subtitle": "વાસ્તવિક જીવન, વાસ્તવિક અસર — આશા અને પરિવર્તનની વાર્તાઓ.",
    "home.success.t1": "શ્યામ જગતની શિષ્યવૃત્તિએ મારું જીવન બદલી નાખ્યું. આજે હું સોફ્ટવેર એન્જિનિયર છું અને આનો સંપૂર્ણ શ્રેય તેમના સમર્થન અને મારા પરના વિશ્વાસને જાય છે.",
    "home.success.t2": "એમ્પ્લોયમેન્ટ પોર્ટલ દ્વારા, મને મારી કુશળતાને અનુરૂપ નોકરી મળી. શ્યામ જગતે મને ફક્ત કામ જ નથી આપ્યું — તેમણે મને હેતુ અને આત્મવિશ્વાસ આપ્યો.",
    "home.success.t3": "હું એકલો અને સંઘર્ષ કરી રહ્યો હતો. વૃદ્ધાશ્રમે મને ફરીથી એક પરિવાર આપ્યો. અહીં મને મળતી હૂંફ, કાળજી અને સન્માન શબ્દોથી પર છે.",
    "home.why.title": "શ્યામ જગત શા માટે પસંદ કરવું",
    "home.why.subtitle": "શ્રદ્ધા પર બનેલ, હેતુથી પ્રેરિત, અને કાયમી પરિવર્તન માટે પ્રતિબદ્ધ.",
    "home.why.f1.title": "શ્રદ્ધા આધારિત",
    "home.why.f1.desc": "દરેક પહેલ બાબા શ્યામના દિવ્ય ઉપદેશોમાં મૂળ ધરાવે છે - સેવા એ જ ભક્તિ છે.",
    "home.why.f2.title": "પારદર્શક",
    "home.why.f2.desc": "અમે અમારા તમામ કાર્યક્રમો અને દાનમાં સંપૂર્ણ નાણાકીય પારદર્શિતા અને જવાબદારી જાળવીએ છીએ.",
    "home.why.f3.title": "સમુદાય કેન્દ્રિત",
    "home.why.f3.desc": "અમારું કાર્ય સમુદાય દ્વારા, સમુદાય માટે માર્ગદર્શિત છે - વિશ્વાસ અને સામૂહિક ભાગીદારી પર બનેલ.",
    "home.why.f4.title": "ચકાસાયેલ સ્વયંસેવકો",
    "home.why.f4.desc": "અમારા તમામ સ્વયંસેવકો ચકાસાયેલ, પ્રશિક્ષિત અને સેવાના ઉચ્ચતમ ધોરણો માટે પ્રતિબદ્ધ છે.",
    "home.why.f5.title": "સમર્પિત સહાય",
    "home.why.f5.desc": "અમારા સભ્યો, લાભાર્થીઓ અને ભાગીદારો માટે 24/7 સહાય - જ્યારે તમને જરૂર હોય ત્યારે અમે હંમેશા અહીં છીએ.",
    "home.why.f6.title": "લાંબા ગાળાની અસર",
    "home.why.f6.desc": "અમે ટકાઉ પરિવર્તન પર ધ્યાન કેન્દ્રિત કરીએ છીએ - ફક્ત ટૂંકા ગાળાની રાહત નહીં પરંતુ કાયમી તકોનું નિર્માણ.",
    "home.temple.eyebrow": "મંદિરો માટે",
    "home.temple.title": "તમારું મંદિર નોંધણી કરો",
    "home.temple.desc": "તમારા મંદિરને શ્યામ જગત પર સૂચિબદ્ધ કરો અને લાખો ભક્તો સાથે જોડાઓ. યાત્રાળુઓને તમારું પવિત્ર સ્થળ, દર્શન સમય અને આગામી કાર્યક્રમો શોધવામાં મદદ કરો.",
