    "home.temple.b2": "કાર્યક્રમો અને દાનનું ડિજિટલ રીતે સંચાલન કરો",
    "home.temple.b3": "પ્રીમિયમ વિકલ્પો સાથે મફત લિસ્ટિંગ",
