    "baba.festival2.desc": "મંદિરમાં ભવ્ય ઉજવણી અને મધ્યરાત્રિની પ્રાર્થનાઓ સાથે ભગવાન કૃષ્ણના જન્મની ઉજવણી.",
    "baba.festival3.title": "એકાદશી",
