    "baba.festival3.desc": "બાબા શ્યામનો આશીર્વાદ મેળવવા માટે ભક્તો દ્વારા વિશેષ પ્રાર્થના અને ઉપવાસ.",
    "baba.festival4.title": "ભજન સંધ્યા",
