    "baba.festival4.desc": "હૃદયસ્પર્શી ભજનો અને પ્રાર્થનાઓથી મંદિરને ભરી દેતા ભક્તિ સંગીતના સત્રો.",
    "baba.festival5.title": "શ્યામ કથા",
    "baba.festival5.when": "સાપ્તાહિક",
    "baba.festival5.desc": "બાબા શ્યામની દિવ્ય કથાઓ અને ઉપદેશોનું વર્ણન કરતા કથા સત્રો.",
    "baba.rituals.title": "દૈનિક મંદિર વિધિઓ",
    "baba.rituals.subtitle": "ખાટુ શ્યામ જી મંદિરમાં ભક્તિની પવિત્ર લય",
    "baba.ritual1.title": "મંગળા આરતી",
    "baba.ritual1.desc": "પરોઢે ભક્તિ સાથે બાબા શ્યામનું સ્વાગત કરતી દિવસની પ્રથમ પ્રાર્થના.",
    "baba.ritual2.title": "શૃંગાર દર્શન",
    "baba.ritual2.desc": "ભક્તો બાબા શ્યામને સુંદર વસ્ત્રો અને આભૂષણોથી શણગારેલા જુએ છે.",
    "baba.ritual3.title": "રાજભોગ",
    "baba.ritual3.desc": "બપોરે બાબા શ્યામને ભોજનનો ભવ્ય ભોગ ધરાવવામાં આવે છે.",
    "baba.ritual4.title": "બપોરનું દર્શન",
    "baba.ritual4.desc": "ભક્તો બપોરના કલાકો દરમિયાન આશીર્વાદ મેળવવાનું ચાલુ રાખે છે.",
    "baba.ritual5.title": "સંધ્યા આરતી",
    "baba.ritual5.desc": "સાંજની પ્રાર્થના, ભક્તિ સાથે દિવસથી રાત્રિમાં સંક્રમણને ચિહ્નિત કરે છે.",
    "baba.ritual6.title": "શયન દર્શન",
    "baba.ritual6.desc": "દિવસની અંતિમ પ્રાર્થના, જ્યારે બાબા શ્યામને આરામ માટે તૈયાર કરવામાં આવે છે.",
    "baba.bhajans.title": "ભજનો અને આધ્યાત્મિક જ્ઞાન",
    "baba.bhajans.artistLabel": "લોકપ્રિય ભક્તિ કલાકાર",
    "baba.gallery.title": "દિવ્ય ક્ષણોની ગેલેરી",
    "baba.gallery.filterAll": "બધા",
