    "baba.visit.title": "તમારી મુલાકાતનું આયોજન કરો",
    "baba.visit.fact1.label": "સ્થાન",
    "baba.visit.fact1.value": "ખાટુ, સીકર જિલ્લો, રાજસ્થાન",
    "baba.visit.fact2.label": "સમય",
