    "initiativesPage.contribute.title": "તમે કેવી રીતે યોગદાન આપી શકો",
    "initiativesPage.contribute.subtitle": "આપવાનું દરેક કાર્ય - મોટું હોય કે નાનું - પરિવર્તનની લહેર બનાવે છે.",
    "initiativesPage.contribute1.title": "સ્વયંસેવક બનો",
    "initiativesPage.contribute1.desc": "તમારો સમય અને કૌશલ્ય અમારા સેવા કાર્યક્રમોને સમર્પિત કરો અને લોકોના જીવનમાં સીધો ફેરફાર લાવો.",
    "initiativesPage.contribute1.cta": "સ્વયંસેવક બનો",
    "initiativesPage.contribute2.title": "દાન કરો",
    "initiativesPage.contribute2.desc": "તમારું દાન એવા લોકો માટે ભોજન, દવાઓ, શિક્ષણ અને આશ્રયનું ભંડોળ પૂરું પાડે છે જેમને તેની સૌથી વધુ જરૂર છે.",
    "initiativesPage.contribute2.cta": "હવે દાન કરો",
    "initiativesPage.contribute3.title": "સભ્ય બનો",
    "initiativesPage.contribute3.desc": "સત્તાવાર શ્યામ જગત સભ્ય બનો અને પરિવર્તન લાવનારાઓના અમારા વધતા પરિવારનો ભાગ બનો.",
    "initiativesPage.contribute3.cta": "સભ્ય બનો",
    "initiativesPage.contribute4.title": "શિક્ષણને પ્રાયોજિત કરો",
    "initiativesPage.contribute4.desc": "બાળકના શિક્ષણને પ્રાયોજિત કરો અને તેમને જ્ઞાન, તક અને ઉજ્જવળ ભવિષ્યની ભેટ આપો.",
    "initiativesPage.contribute4.cta": "એક બાળકને પ્રાયોજિત કરો",
    "initiativesPage.contribute5.title": "ભોજનને પ્રાયોજિત કરો",
    "initiativesPage.contribute5.desc": "100 પરિવારો માટે એક દિવસના ભોજનનું ભંડોળ પૂરું પાડો અને આજે રાત્રે કોઈ ભૂખ્યું ન સૂવે તેનું કારણ બનો.",
    "initiativesPage.contribute5.cta": "ભોજનને પ્રાયોજિત કરો",
    "initiativesPage.contribute6.title": "અમારી સાથે ભાગીદારી કરો",
