    "artistReg.heroDesc": "શ્યામ જગતના વધતા ભક્તિ કલાકારોના સમુદાયમાં જોડાઓ. સમગ્ર ભારતમાં આધ્યાત્મિક કાર્યક્રમો, સાંસ્કૃતિક કાર્યક્રમો અને પવિત્ર મેળાવડાઓમાં તમારી પ્રતિભા દર્શાવો.",
