    "artistReg.whyTitle": "એક કલાકાર તરીકે શ્યામ જગતમાં શા માટે જોડાવું?",
    "artistReg.whySubtitle": "ભક્તિ અને પ્રદર્શનનો સંગમ. એક એવા પ્લેટફોર્મ પર પગ મૂકો જે તમારી પવિત્ર કલાનું સન્માન કરવા અને તમને વૈશ્વિક ભક્તો સાથે જોડવા માટે બનાવવામાં આવ્યું છે.",
    "artistReg.whyFeature1Title": "હજારો સુધી પહોંચો",
    "artistReg.whyFeature1Desc": "સમગ્ર ભારતમાં મંદિર બોર્ડ અને અગ્રણી કાર્યક્રમ આયોજકો દ્વારા શોધાઓ.",
    "artistReg.whyFeature2Title": "પવિત્ર મંચ",
    "artistReg.whyFeature2Desc": "પ્રતિષ્ઠિત મંદિર ઉત્સવો, સતત સત્સંગો અને મુખ્ય સાંસ્કૃતિક મેળાવડાઓમાં પ્રદર્શન કરો.",
    "artistReg.whyFeature3Title": "તમારી કલા વધારો",
    "artistReg.whyFeature3Desc": "અનુભવી ભક્તિ ગુરુઓ સાથે જોડાઓ, તકનીકોની આપ-લે કરો, અને તમારું આધ્યાત્મિક નેટવર્ક વિસ્તૃત કરો.",
