    "templeReg.gallery.browse": "ફાઇલો બ્રાઉઝ કરો",
    "templeReg.gallery.hint": "10 ફોટા સુધી અપલોડ કરો. સ્વીકૃત ફોર્મેટ: JPG, PNG. પ્રતિ ફોટો મહત્તમ 5MB. મુખ્ય દેવતા, મંદિરના બાહ્ય ભાગ, આંતરિક ભાગ અને પરિસરના ફોટા શામેલ કરો.",
