    "templeReg.submit": "મંદિર નોંધણી સબમિટ કરો",
    "templeReg.why.title": "શ્યામ જગત પર તમારું મંદિર શા માટે યાદીબદ્ધ કરવું?",
    "templeReg.why.subtitle": "વિશ્વભરના લાખો શોધકો સાથે ભક્તિના પવિત્ર સ્થાનોને જોડવું. સંચારને સરળ બનાવો, કાર્યક્રમોનું આયોજન કરો અને સામુદાયિક સહાયનું સહેલાઈથી સંચાલન કરો.",
    "templeReg.whyFeature1Title": "ભક્તો સુધી પહોંચો",
    "templeReg.whyFeature1Desc": "તેમની નજીકના મંદિરો શોધી રહેલા લાખો ભક્તો સાથે જોડાઓ, તેમને તમારા પવિત્ર સ્થળ તરફ માર્ગદર્શન આપો.",
    "templeReg.whyFeature2Title": "કાર્યક્રમોનું સંચાલન કરો",
    "templeReg.whyFeature2Desc": "નિયમિત તહેવારો, વિશેષ પૂજાઓ અને ભંડારાની જાહેરાત વ્યાપક, અત્યંત જોડાયેલા પ્રેક્ષકોને કરો.",
    "templeReg.whyFeature3Title": "દાન મેળવો",
    "templeReg.whyFeature3Desc": "સુરક્ષિત અને પારદર્શક રીતે ઓનલાઈન દાન સ્વીકારો, મંદિરની જાળવણી માટે સીધો નાણાકીય ટેકો ઉત્પન્ન કરો.",
    "templeReg.whyFeature4Title": "સમુદાય બનાવો",
    "templeReg.whyFeature4Desc": "તમારા મંદિરના પ્રેક્ષકોને ડિજિટલ-પ્રથમ વધારો, આશીર્વાદ મોકલો અને આધ્યાત્મિક ઉપદેશો સરળતાથી શેર કરો.",

