    "chairmanPage.breadcrumbCurrent": "અધ્યક્ષ",
    "chairmanPage.roleTitle": "અધ્યક્ષ — શ્રી શ્યામ જગત",
    "chairmanPage.bio": "આજીવન આધ્યાત્મિક શોધક અને સામાજિક પરિવર્તનના શિલ્પકાર, શ્રી રમેશ કુમાર જીએ ત્રણ દાયકાથી વધુ સમય વૈશ્વિક આધ્યાત્મિક સમુદાયોનું આયોજન, રાહત કાર્યક્રમોનું સંચાલન અને સંસ્થાઓના નિર્માણ માટે સમર્પિત કર્યો છે.",
    "chairmanPage.ctaSchedule": "મુલાકાતનો સમય નક્કી કરો",
    "chairmanPage.quoteTitle": "“શ્રદ્ધા ત્યારે જ શક્તિ આપે છે જ્યારે તે અથાક માનવ સેવામાં પરિવર્તિત થાય.”",
    "chairmanPage.quoteBody": "“અમે આધ્યાત્મિક જોડાણના નવા યુગમાં પ્રવેશ કર્યો છે. અમારું મિશન આધુનિક ડિજિટલ સિસ્ટમોની શક્તિનો ઉપયોગ કરવાનું છે જેથી કોઈ પણ ભક્ત બાબા શ્યામની દિવ્ય આભા અનુભવવાથી વંચિત ન રહે, અને અમારી પહોંચમાં કોઈ પણ વૃદ્ધ કે ભૂખ્યું બાળક સહાય વિના ન રહે.”",
    "chairmanPage.quoteSignatureLabel": "અધ્યક્ષની સહી અને મહોર માન્ય",
    "chairmanPage.milestonesTitle": "નેતૃત્વ યાત્રા અને સીમાચિહ્નો",
    "chairmanPage.milestone1Year": "1998 – વર્તમાન",
    "chairmanPage.milestone1Title": "સ્થાપક નિર્દેશક, શ્યામ સેવા પહેલ",
    "chairmanPage.milestone1Desc": "ખાટુ, રાજસ્થાન આવતા યાત્રાળુઓ માટે મૂળભૂત તબીબી શિબિરો અને મફત રસોડા સેવાઓનું નેતૃત્વ કર્યું.",
    "chairmanPage.milestone2Year": "2012",
    "chairmanPage.milestone2Title": "આધ્યાત્મિક સુધારણા પુરસ્કાર પ્રાપ્તકર્તા",
    "chairmanPage.milestone2Desc": "યાત્રાળુ ભીડ-વ્યવસ્થાપન ડેટાબેઝ અને સુરક્ષાના આધુનિકીકરણ માટે રાષ્ટ્રીય સ્તરે માન્યતા પ્રાપ્ત.",
    "chairmanPage.milestone3Year": "2020",
    "chairmanPage.milestone3Title": "શ્રી શ્યામ જગતના વૈશ્વિક અધ્યક્ષ તરીકે નિમણૂક",
    "chairmanPage.milestone3Desc": "ડિજિટાઇઝેશન, વૈવાહિક પ્લેટફોર્મ અને રાજ્યવ્યાપી શાખા એકીકરણનું નેતૃત્વ કરે છે.",
    "chairmanPage.credEducation": "શિક્ષણ",
    "chairmanPage.credKeyResponsibility": "મુખ્ય જવાબદારી",

    "mukhyaTrusteePage.breadcrumbCurrent": "મુખ્ય ટ્રસ્ટી",
    "mukhyaTrusteePage.roleTitle": "મુખ્ય ટ્રસ્ટી — શ્રી શ્યામ જગત",
    "mukhyaTrusteePage.bio": "વહીવટી નૈતિકતા અને સામુદાયિક કલ્યાણનો સ્તંભ, શ્રીમતી સુનિતા દેવી જી ખાટુ મંદિર સંચાલન, મહિલા સશક્તિકરણ અને વરિષ્ઠ સંભાળ ગૃહોને સમર્પિત પરંપરાગત પારિવારિક ટ્રસ્ટોનું સંચાલન કરે છે.",
    "mukhyaTrusteePage.ctaConnect": "કાર્યાલય સાથે જોડાઓ",
    "mukhyaTrusteePage.quoteTitle": "“સાચું સશક્તિકરણ એટલે આપણી દીકરીઓને સક્ષમ બનાવવી અને આપણા વડીલોનું રક્ષણ કરવું.”",
    "mukhyaTrusteePage.quoteBody": "“શ્યામ જગતની શક્તિ સૌથી નબળા વર્ગ માટે આપણે જે આત્મનિર્ભરતા પેદા કરી શકીએ છીએ તેમાં રહેલી છે. સક્રિય કૌશલ્ય શિક્ષણ અને પારદર્શક દાતા સહાય દ્વારા, અમે તમામ જિલ્લાઓમાં અમારા મહિલા સહકારી મંડળો અને વરિષ્ઠ સંભાળ નેટવર્કનો વિસ્તાર કરવાનો લક્ષ્યાંક રાખીએ છીએ.”",
    "mukhyaTrusteePage.visionTitle": "દ્રષ્ટિકોણ અને ધ્યાન કેન્દ્રિત ક્ષેત્રો",
    "mukhyaTrusteePage.focus1Title": "ગ્રામીણ મહિલા સશક્તિકરણ",
    "mukhyaTrusteePage.focus1Desc": "ટકાઉ આવક શક્ય બનાવતા વ્યાવસાયિક સીવણ, હસ્તકલા ડિઝાઇન અને કમ્પ્યુટર સાક્ષરતા કેન્દ્રોનું નેતૃત્વ.",
    "mukhyaTrusteePage.focus2Title": "વરિષ્ઠ નાગરિક કલ્યાણ",
    "mukhyaTrusteePage.focus2Desc": "જયપુર અને સીકરના વૃદ્ધાશ્રમોમાં ગૌરવપૂર્ણ આવાસ અને ઉચ્ચ-સંભાળ નર્સિંગ યુનિટોની સ્થાપના.",
    "mukhyaTrusteePage.focus3Title": "અનૂપ સેવા વૈવાહિક સેવાઓ",
    "mukhyaTrusteePage.focus3Desc": "સમુદાય-સમર્થિત ઓનલાઇન મેચમેકિંગ સહાય દ્વારા પારિવારિક મૂલ્યો અને પરંપરાગત માળખાનું જતન.",
    "mukhyaTrusteePage.credAreaOfWork": "કાર્યક્ષેત્ર",

