    "trusteesPage.heroDesc": "શ્રી શ્યામ જગત ટ્રસ્ટી બોર્ડમાં અગ્રણી નેતાઓ, આધ્યાત્મિક સુધારકો અને પરોપકારીઓનો સમાવેશ થાય છે જે અમારા પારદર્શક સામાજિક કાર્યક્રમોનું સંચાલન કરે છે.",
