    "trusteesPage.trustee3Desc": "સ્વયંસેવક એકત્રીકરણ, કોર્પોરેટ સામાજિક જવાબદારી (CSR) ભાગીદારી અને સાંસ્કૃતિક કાર્યક્રમોની દેખરેખ રાખે છે.",
