    "home.hero.missionTitle": "आमचे ध्येय",
    "home.hero.missionText": "श्रद्धा, सेवा आणि करुणेने एकत्रित भक्तांचा जागतिक समुदाय निर्माण करणे.",
    "home.about.eyebrow": "विषयी",
    "home.about.body": "श्याम जगत ही बाबा श्यामपासून प्रेरित एक आध्यात्मिक आणि सामाजिक संस्था आहे, जी श्रद्धा आणि कृतीद्वारे मानवतेच्या सेवेसाठी समर्पित आहे. आम्ही मुलांसाठी दर्जेदार शिक्षण, रोजगारासाठी कौशल्य प्रशिक्षण, अन्न सुरक्षिततेसाठी मोफत जेवण, बेघरांसाठी सुरक्षित निवारा, मोफत आरोग्य शिबिरे आणि महिला सक्षमीकरण कार्यक्रमांद्वारे समुदायांचा विकास करतो. एकत्रितपणे, आमचे ध्येय एक दयाळू आणि स्वावलंबी समाज निर्माण करणे आहे जिथे प्रत्येकजण सन्मानाने प्रगती करू शकेल.",
    "home.about.knowMore": "अधिक जाणून घ्या",
    "home.baba.body": "\"भीमाचा पौराणिक नातू बर्बरीक म्हणून जन्मलेल्या त्याच्याकडे अतुलनीय योद्धा शक्ती होती. तरीही, धर्माच्या (सत्याच्या) विजयासाठी स्वतःच्या मस्तकाचे सर्वोच्च बलिदान देणे हे त्याचे सर्वात मोठे कार्य होते. त्याच्या निःस्वार्थ भक्तीने प्रसन्न होऊन, भगवान कृष्णाने त्याला स्वतःचे नाव—श्याम—दिले आणि वरदान दिले की कलियुगात तो पराभूतांचा परम रक्षक म्हणून पूजला जाईल.\"",
