    "initiatives.card1.desc": "कोणीही उपाशी झोपू नये याची खात्री करणे - एका वेळी एक जेवण, एक जीवन.",
    "initiatives.card2.tag": "शिक्षण",
    "initiatives.card2.title": "शिक्षण सहाय्य",
    "initiatives.card2.desc": "शिष्यवृत्ती, मार्गदर्शन आणि संसाधने - कारण प्रत्येक मूल स्वप्न पाहण्यास पात्र आहे.",
    "initiatives.card3.tag": "स्वच्छ वाहिनी",
    "initiatives.card3.title": "स्वच्छ वाहिनी",
    "initiatives.card3.desc": "समुदाय-आधारित उपक्रमांद्वारे स्वच्छता, आरोग्य आणि पर्यावरण काळजीला प्रोत्साहन देणे.",
    "initiatives.card4.tag": "गौशाळा",
    "initiatives.card4.title": "गौशाळा",
    "initiatives.card4.desc": "बेवारस आणि जखमी गायींना निवारा, पोषण आणि वैद्यकीय काळजी प्रदान करणे.",
    "initiatives.card5.tag": "विवाह ब्यूरो",
    "initiatives.card5.title": "विवाह ब्यूरो",
    "initiatives.card5.desc": "समुदायासाठी तयार केलेल्या विश्वासार्ह, मूल्याधारित वैवाहिक व्यासपीठाद्वारे हृदये जोडणे.",
    "initiatives.card6.tag": "काळजी आणि निवारा",
    "initiatives.card6.title": "वृद्धाश्रम",
