    "initiativesPage.commitment.title": "आमची बांधिलकी",
    "initiativesPage.commitment.text": "श्याम जगतने हाती घेतलेला प्रत्येक उपक्रम श्रद्धा, करुणा आणि जबाबदारीने मानवतेची सेवा करण्याप्रती आमची अटळ बांधिलकी दर्शवतो. आमच्या स्वयंसेवकांसह, सदस्यांसह आणि समर्थकांसह, आम्ही अर्थपूर्ण संधी निर्माण करणे, आशा देणे आणि एक मजबूत समुदाय घडवणे सुरू ठेवतो जिथे प्रत्येकजण प्रतिष्ठेने जगू शकेल.",
