    "artistReg.whyTitle": "कलाकार म्हणून श्याम जगतमध्ये का सामील व्हावे?",
    "artistReg.whySubtitle": "भक्ती आणि सादरीकरणाचा संगम. तुमच्या पवित्र कलेचा सन्मान करण्यासाठी आणि तुम्हाला जागतिक भक्तांशी जोडण्यासाठी तयार केलेल्या व्यासपीठावर पाऊल टाका.",
    "artistReg.whyFeature1Title": "हजारो लोकांपर्यंत पोहोचा",
    "artistReg.whyFeature1Desc": "संपूर्ण भारतातील मंदिर मंडळे आणि प्रमुख कार्यक्रम आयोजकांद्वारे शोधले जा.",
    "artistReg.whyFeature2Title": "पवित्र मंच",
    "artistReg.whyFeature2Desc": "प्रतिष्ठित मंदिर सण, सतत सत्संग आणि प्रमुख सांस्कृतिक मेळाव्यांमध्ये सादरीकरण करा.",
    "artistReg.whyFeature3Title": "तुमची कला वाढवा",
    "artistReg.whyFeature3Desc": "अनुभवी भक्ती गुरूंशी जोडले जा, तंत्रांची देवाणघेवाण करा आणि तुमचे आध्यात्मिक नेटवर्क विस्तृत करा.",
    "artistReg.whyFeature4Title": "योग्य मोबदला",
    "artistReg.whyFeature4Desc": "पारदर्शक बुकिंग अटी आणि तुमच्या खात्यात थेट जलद, सत्यापित डिजिटल पेमेंटचा अनुभव घ्या.",

