    "templeReg.gallery.browse": "फाइल्स ब्राउझ करा",
    "templeReg.gallery.hint": "10 फोटोंपर्यंत अपलोड करा. स्वीकृत फॉरमॅट: JPG, PNG. प्रति फोटो कमाल 5MB. मुख्य देवता, मंदिराचा बाह्य भाग, आतील भाग आणि परिसराचे फोटो समाविष्ट करा.",
    "templeReg.terms.certify": "मी प्रमाणित करतो की दिलेली माहिती अचूक आहे आणि मी मंदिर ट्रस्टच्या वतीने हे मंदिर नोंदणी करण्यासाठी अधिकृत आहे.",
    "templeReg.terms.agree": "मी श्याम जगत आध्यात्मिक व्यासपीठाच्या सेवा अटी आणि गोपनीयता धोरणाशी सहमत आहे.",
    "templeReg.terms.consent": "मी व्यासपीठ अद्यतने आणि भक्तांच्या चौकशीबद्दल संवाद प्राप्त करण्यास संमती देतो.",
    "templeReg.submit": "मंदिर नोंदणी सबमिट करा",
    "templeReg.why.title": "श्याम जगतवर तुमचे मंदिर का सूचीबद्ध करावे?",
    "templeReg.why.subtitle": "जगभरातील लाखो साधकांशी भक्तीच्या पवित्र स्थानांना जोडणे. संवाद सुलभ करा, कार्यक्रम आयोजित करा आणि सामुदायिक सहाय्य सहजतेने व्यवस्थापित करा.",
    "templeReg.whyFeature1Title": "भक्तांपर्यंत पोहोचा",
    "templeReg.whyFeature1Desc": "त्यांच्या जवळपास मंदिरे शोधणाऱ्या लाखो भक्तांशी जोडले जा, त्यांना तुमच्या पवित्र स्थळाकडे मार्गदर्शन करा.",
    "templeReg.whyFeature2Title": "कार्यक्रम व्यवस्थापित करा",
    "templeReg.whyFeature2Desc": "नियमित सण, विशेष पूजा आणि भंडाऱ्यांची घोषणा व्यापक, अत्यंत सहभागी प्रेक्षकांना करा.",
    "templeReg.whyFeature3Title": "देणग्या स्वीकारा",
    "templeReg.whyFeature3Desc": "सुरक्षित आणि पारदर्शकपणे ऑनलाइन देणग्या स्वीकारा, मंदिराच्या देखभालीसाठी थेट आर्थिक सहाय्य निर्माण करा.",
    "templeReg.whyFeature4Title": "समुदाय तयार करा",
    "templeReg.whyFeature4Desc": "तुमच्या मंदिराच्या प्रेक्षकांना डिजिटल-प्रथम वाढवा, आशीर्वाद पाठवा आणि आध्यात्मिक शिकवणी सहजतेने शेअर करा.",

