    "chairmanPage.breadcrumbCurrent": "अध्यक्ष",
    "chairmanPage.roleTitle": "अध्यक्ष — श्री श्याम जगत",
    "chairmanPage.bio": "आजीवन आध्यात्मिक साधक आणि सामाजिक परिवर्तनाचे शिल्पकार, श्री रमेश कुमार जी यांनी तीन दशकांहून अधिक काळ जागतिक आध्यात्मिक समुदायांचे आयोजन, मदत कार्यक्रमांचे संचालन आणि संस्थांच्या उभारणीसाठी समर्पित केला आहे.",
    "chairmanPage.ctaSchedule": "भेटीची वेळ घ्या",
    "chairmanPage.quoteTitle": "“श्रद्धा तेव्हाच शक्ती देते जेव्हा ती अथक मानवी सेवेत परिवर्तित होते.”",
    "chairmanPage.quoteBody": "“आम्ही आध्यात्मिक जोडणीच्या नव्या युगात प्रवेश केला आहे. आमचे ध्येय आधुनिक डिजिटल प्रणालींच्या सामर्थ्याचा वापर करणे आहे जेणेकरून कोणताही भक्त बाबा श्यामच्या दिव्य आभेचा अनुभव घेण्यापासून वंचित राहू नये, आणि आमच्या पोहोचीत कोणताही वृद्ध किंवा भुकेला बालक मदतीशिवाय राहू नये.”",
    "chairmanPage.quoteSignatureLabel": "अध्यक्षांची स्वाक्षरी आणि शिक्का मंजूर",
    "chairmanPage.milestonesTitle": "नेतृत्व प्रवास आणि टप्पे",
    "chairmanPage.milestone1Year": "1998 – आजपर्यंत",
    "chairmanPage.milestone1Title": "संस्थापक संचालक, श्याम सेवा उपक्रम",
    "chairmanPage.milestone1Desc": "खाटू, राजस्थान येथे येणाऱ्या यात्रेकरूंसाठी मूलभूत वैद्यकीय शिबिरे आणि मोफत स्वयंपाकघर सेवांचे नेतृत्व केले.",
    "chairmanPage.milestone2Year": "2012",
    "chairmanPage.milestone2Title": "आध्यात्मिक सुधारणा पुरस्कार प्राप्तकर्ता",
    "chairmanPage.milestone2Desc": "यात्रेकरू गर्दी-व्यवस्थापन डेटाबेस आणि सुरक्षेच्या आधुनिकीकरणासाठी राष्ट्रीय स्तरावर सन्मानित.",
    "chairmanPage.milestone3Year": "2020",
    "chairmanPage.milestone3Title": "श्री श्याम जगतचे जागतिक अध्यक्ष म्हणून नियुक्त",
    "chairmanPage.milestone3Desc": "डिजिटायझेशन, वैवाहिक व्यासपीठ आणि राज्यव्यापी शाखा एकत्रीकरणाचे नेतृत्व करत आहेत.",
    "chairmanPage.credEducation": "शिक्षण",
    "chairmanPage.credKeyResponsibility": "मुख्य जबाबदारी",

    "mukhyaTrusteePage.breadcrumbCurrent": "मुख्य विश्वस्त",
    "mukhyaTrusteePage.roleTitle": "मुख्य विश्वस्त — श्री श्याम जगत",
    "mukhyaTrusteePage.bio": "प्रशासकीय नीतिमत्ता आणि सामुदायिक कल्याणाचा आधारस्तंभ, श्रीमती सुनीता देवी जी खाटू मंदिर संचालन, महिला सक्षमीकरण आणि ज्येष्ठ नागरिक काळजी गृहांना समर्पित पारंपरिक कौटुंबिक विश्वस्त संस्थांचे संचालन करतात.",
    "mukhyaTrusteePage.ctaConnect": "कार्यालयाशी संपर्क साधा",
    "mukhyaTrusteePage.quoteTitle": "“खरे सक्षमीकरण म्हणजे आपल्या मुलींना सक्षम करणे आणि आपल्या वडीलधाऱ्यांचे रक्षण करणे.”",
    "mukhyaTrusteePage.quoteBody": "“श्याम जगतची शक्ती सर्वात असुरक्षित घटकांसाठी आपण निर्माण करू शकणाऱ्या आत्मनिर्भरतेत आहे. सक्रिय कौशल्य शिक्षण आणि पारदर्शक देणगीदार सहाय्याद्वारे, आम्ही सर्व जिल्ह्यांमध्ये आमच्या महिला सहकारी संस्था आणि ज्येष्ठ काळजी नेटवर्कचा विस्तार करू इच्छितो.”",
    "mukhyaTrusteePage.visionTitle": "दृष्टिकोन आणि लक्ष केंद्रित क्षेत्रे",
    "mukhyaTrusteePage.focus1Title": "ग्रामीण महिला सक्षमीकरण",
    "mukhyaTrusteePage.focus1Desc": "शाश्वत उत्पन्न शक्य करणाऱ्या व्यावसायिक शिवणकाम, हस्तकला डिझाइन आणि संगणक साक्षरता केंद्रांचे नेतृत्व.",
    "mukhyaTrusteePage.focus2Title": "ज्येष्ठ नागरिक कल्याण",
    "mukhyaTrusteePage.focus2Desc": "जयपूर आणि सीकर वृद्धाश्रमांमध्ये सन्माननीय निवास आणि उच्च-काळजी नर्सिंग युनिट्सची स्थापना.",
    "mukhyaTrusteePage.focus3Title": "अनूप सेवा वैवाहिक सेवा",
    "mukhyaTrusteePage.focus3Desc": "समुदाय-समर्थित ऑनलाइन विवाहजुळणी सहाय्याद्वारे कौटुंबिक मूल्ये आणि पारंपरिक रचनांचे जतन.",
    "mukhyaTrusteePage.credAreaOfWork": "कार्यक्षेत्र",

    "advisoryBoardPage.breadcrumbCurrent": "सल्लागार मंडळ",
