    "advisoryBoardPage.heroDesc": "वैधानिक अनुपालन आणि सनातन मूल्यांप्रती कठोर बांधिलकीसह आमच्या कामकाजाचे मार्गदर्शन करणाऱ्या अनुभवी दिग्गज, ऋषी, कायदेतज्ज्ञ आणि उद्योग तज्ञांना भेटा.",
