    "advisoryBoardPage.member1Desc": "विश्वस्त संरचना कायदेशीरदृष्ट्या मजबूत आणि नैतिकदृष्ट्या शुद्ध ठेवण्यासाठी जागतिक आध्यात्मिक कामकाजाचे मार्गदर्शन करतात.",
