    "managementTeamPage.breadcrumbCurrent": "व्यवस्थापन संघ",
    "managementTeamPage.heroTitle": "व्यवस्थापन संघ",
    "managementTeamPage.heroDesc": "बाबा श्यामच्या दिव्य कृपेखाली संस्थेच्या दैनंदिन कामकाजाचे व्यवस्थापन आणि संचालन करण्यास जबाबदार व्यावसायिकांना भेटा.",
    "managementTeamPage.member1Role": "कार्यसंचालन संचालक",
    "managementTeamPage.member1Dept": "कार्यसंचालन",
    "managementTeamPage.member1Desc": "राज्यभरातील मंदिरांमध्ये दैनंदिन सेवा रसद, वैवाहिक पोर्टल तपासणी आणि तांत्रिक अंमलबजावणीचे निरीक्षण करतात.",
