    "managementTeamPage.member5Desc": "यात्रेकरू वैद्यकीय मदत शिबिरे, अन्न वितरण आणि स्वयंसेवक तैनाती योजना राबवतात.",
    "managementTeamPage.member6Role": "सामान्य कायदेशीर सल्लागार",
