    "managementTeamPage.member6Desc": "विश्वस्त प्रमाणपत्रे, जमीन व्यवस्थापन आणि वैधानिक चौकटींसाठी संरचनात्मक अनुपालन सुनिश्चित करतात.",

    "trusteesPage.breadcrumbCurrent": "विश्वस्त",
    "trusteesPage.heroTitle": "आमचे विश्वस्त",
    "trusteesPage.heroDesc": "श्री श्याम जगत विश्वस्त मंडळामध्ये प्रमुख नेते, आध्यात्मिक सुधारक आणि परोपकारी व्यक्तींचा समावेश आहे जे आमच्या पारदर्शक सामाजिक कार्यक्रमांचे संचालन करतात.",
    "trusteesPage.trustee1Desc": "आयटी परिवर्तन, मंदिर सत्यापन नेटवर्क आणि डेटा पारदर्शकता कार्यक्रमांचे निरीक्षण करतात.",
    "trusteesPage.trustee2Desc": "आर्थिक लेखापरीक्षण, कायदेशीर अनुपालन आणि मोठ्या निधी वाटपाचे निर्देशन करतात.",
    "trusteesPage.trustee3Desc": "स्वयंसेवक जमवाजमव, कॉर्पोरेट सामाजिक जबाबदारी (सीएसआर) भागीदारी आणि सांस्कृतिक कार्यक्रमांचे निरीक्षण करतात.",
    "trusteesPage.trustee4Desc": "मध्य भारतात अन्न वितरण नेटवर्क आणि मोबाइल आरोग्य दवाखान्यांचे समन्वय साधतात.",
    "trusteesPage.trustee5Desc": "दर्जेदार आध्यात्मिक साहित्य प्रकाशन आणि भजन कलाकार समन्वयाचे संरक्षण करतात.",
    "trusteesPage.trustee6Desc": "प्राचीन हस्तलिखिते आणि मंदिर संगीत परंपरांच्या वारसा जतनाचे व्यवस्थापन करतात.",
