    "home.hero.tagline": "ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ ਭਗਤੀ ਫੈਲਾਉਣ ਅਤੇ ਮਨੁੱਖਤਾ ਦੀ ਸੇਵਾ ਕਰਨ ਲਈ ਸਮਰਪਿਤ ਇੱਕ ਮੰਚ ਹੈ",
