    "home.hero.stat.devotees2": "ਜੁੜੇ ਹੋਏ",
    "home.hero.stat.seva1": "ਸੇਵਾ",
    "home.hero.stat.seva2": "ਪਹਿਲਕਦਮੀਆਂ",
    "home.hero.stat.temples1": "ਮੰਦਰ",
    "home.hero.stat.temples2": "ਸੰਬੰਧਿਤ",
    "home.hero.stat.states1": "ਰਾਜ",
    "home.hero.stat.states2": "ਕਵਰ ਕੀਤੇ ਗਏ",
    "home.hero.missionTitle": "ਸਾਡਾ ਮਿਸ਼ਨ",
    "home.hero.missionText": "ਆਸਥਾ, ਸੇਵਾ ਅਤੇ ਦਇਆ ਨਾਲ ਜੁੜੇ ਭਗਤਾਂ ਦਾ ਇੱਕ ਵਿਸ਼ਵਵਿਆਪੀ ਭਾਈਚਾਰਾ ਬਣਾਉਣਾ।",
    "home.about.eyebrow": "ਬਾਰੇ",
    "home.about.body": "ਸ਼੍ਯਾਮ ਜਗਤ ਬਾਬਾ ਸ਼੍ਯਾਮ ਤੋਂ ਪ੍ਰੇਰਿਤ ਇੱਕ ਅਧਿਆਤਮਿਕ ਅਤੇ ਸਮਾਜਿਕ ਸੰਸਥਾ ਹੈ, ਜੋ ਆਸਥਾ ਅਤੇ ਕਰਮ ਰਾਹੀਂ ਮਨੁੱਖਤਾ ਦੀ ਸੇਵਾ ਲਈ ਸਮਰਪਿਤ ਹੈ। ਅਸੀਂ ਬੱਚਿਆਂ ਲਈ ਮਿਆਰੀ ਸਿੱਖਿਆ, ਰੁਜ਼ਗਾਰ ਲਈ ਹੁਨਰ ਸਿਖਲਾਈ, ਭੋਜਨ ਸੁਰੱਖਿਆ ਲਈ ਮੁਫ਼ਤ ਭੋਜਨ, ਬੇਘਰਿਆਂ ਲਈ ਸੁਰੱਖਿਅਤ ਆਸਰਾ, ਮੁਫ਼ਤ ਸਿਹਤ ਕੈਂਪਾਂ ਅਤੇ ਔਰਤਾਂ ਦੇ ਸਸ਼ਕਤੀਕਰਨ ਪ੍ਰੋਗਰਾਮਾਂ ਰਾਹੀਂ ਭਾਈਚਾਰਿਆਂ ਨੂੰ ਉੱਪਰ ਚੁੱਕਦੇ ਹਾਂ। ਮਿਲ ਕੇ, ਸਾਡਾ ਟੀਚਾ ਇੱਕ ਦਿਆਲੂ ਅਤੇ ਆਤਮਨਿਰਭਰ ਸਮਾਜ ਬਣਾਉਣਾ ਹੈ ਜਿੱਥੇ ਹਰ ਕੋਈ ਮਾਣ ਨਾਲ ਅੱਗੇ ਵਧ ਸਕੇ।",
    "home.about.knowMore": "ਹੋਰ ਜਾਣੋ",
    "home.baba.body": "\"ਭੀਮ ਦੇ ਮਹਾਨ ਪੋਤੇ ਬਰਬਰੀਕ ਵਜੋਂ ਜਨਮੇ, ਉਨ੍ਹਾਂ ਕੋਲ ਬੇਮਿਸਾਲ ਯੋਧਾ ਸ਼ਕਤੀ ਸੀ। ਫਿਰ ਵੀ, ਧਰਮ (ਸੱਚ) ਦੀ ਜਿੱਤ ਲਈ ਆਪਣੇ ਸਿਰ ਦਾ ਸਰਵਉੱਚ ਬਲੀਦਾਨ ਦੇਣਾ ਉਨ੍ਹਾਂ ਦਾ ਸਭ ਤੋਂ ਵੱਡਾ ਕਾਰਜ ਸੀ। ਉਨ੍ਹਾਂ ਦੀ ਨਿਸ਼ਕਾਮ ਭਗਤੀ ਤੋਂ ਖੁਸ਼ ਹੋ ਕੇ, ਭਗਵਾਨ ਕ੍ਰਿਸ਼ਨ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਆਪਣਾ ਨਾਮ—ਸ਼੍ਯਾਮ—ਦਿੱਤਾ ਅਤੇ ਵਰਦਾਨ ਦਿੱਤਾ ਕਿ ਕਲਯੁਗ ਵਿੱਚ ਉਹ ਹਾਰੇ ਹੋਇਆਂ ਦੇ ਪਰਮ ਰੱਖਿਅਕ ਵਜੋਂ ਪੂਜੇ ਜਾਣਗੇ।\"",
    "home.aarti.eyebrow": "ਦਰਸ਼ਨ",
    "home.aarti.title": "ਲਾਈਵ ਆਰਤੀ ਅਤੇ ਦਰਸ਼ਨ",
    "home.aarti.streamingTitle": "ਹੁਣੇ ਪ੍ਰਸਾਰਣ ਜਾਰੀ ਹੈ",
    "home.aarti.streamingDesc": "ਮੰਦਰ ਦੇ ਗਰਭ ਗ੍ਰਹਿ ਦੇ ਸਾਡੇ ਲਗਾਤਾਰ ਲਾਈਵ ਪ੍ਰਸਾਰਣ ਵਿੱਚ ਹਜ਼ਾਰਾਂ ਭਗਤਾਂ ਨਾਲ ਜੁੜੋ।",
    "home.aarti.watchLive": "ਲਾਈਵ ਦੇਖੋ",
    "home.initiatives.eyebrow": "ਅਸੀਂ ਕੀ ਕਰਦੇ ਹਾਂ",
    "home.initiatives.titlePrefix": "ਸਾਡੀਆਂ",
    "home.initiatives.titleHighlight": "ਪਹਿਲਕਦਮੀਆਂ",
    "home.initiatives.subtitle": "ਆਸਥਾ ਤੋਂ ਪ੍ਰੇਰਿਤ, ਦਇਆ ਦੁਆਰਾ ਪੋਸ਼ਿਤ - ਸਮਾਜ ਦੇ ਹਰ ਪਹਿਲੂ ਵਿੱਚ ਜੀਵਨ ਦੀ ਸੇਵਾ।",
    "home.initiatives.learnMore": "ਹੋਰ ਜਾਣੋ",
    "home.success.title": "ਸਫਲਤਾ ਦੀਆਂ ਕਹਾਣੀਆਂ",
    "home.success.subtitle": "ਅਸਲ ਜ਼ਿੰਦਗੀਆਂ, ਅਸਲ ਪ੍ਰਭਾਵ — ਉਮੀਦ ਅਤੇ ਬਦਲਾਅ ਦੀਆਂ ਕਹਾਣੀਆਂ।",
    "home.success.t1": "ਸ਼੍ਯਾਮ ਜਗਤ ਦੀ ਸਕਾਲਰਸ਼ਿਪ ਨੇ ਮੇਰੀ ਜ਼ਿੰਦਗੀ ਬਦਲ ਦਿੱਤੀ। ਅੱਜ ਮੈਂ ਇੱਕ ਸਾਫਟਵੇਅਰ ਇੰਜੀਨੀਅਰ ਹਾਂ ਅਤੇ ਇਸ ਦਾ ਸਾਰਾ ਸਿਹਰਾ ਉਨ੍ਹਾਂ ਦੇ ਸਮਰਥਨ ਅਤੇ ਮੇਰੇ ਵਿੱਚ ਵਿਸ਼ਵਾਸ ਨੂੰ ਜਾਂਦਾ ਹੈ।",
    "home.success.t2": "ਰੁਜ਼ਗਾਰ ਪੋਰਟਲ ਰਾਹੀਂ, ਮੈਨੂੰ ਆਪਣੇ ਹੁਨਰ ਨਾਲ ਮੇਲ ਖਾਂਦੀ ਨੌਕਰੀ ਮਿਲੀ। ਸ਼੍ਯਾਮ ਜਗਤ ਨੇ ਮੈਨੂੰ ਸਿਰਫ਼ ਕੰਮ ਹੀ ਨਹੀਂ ਦਿੱਤਾ — ਉਨ੍ਹਾਂ ਨੇ ਮੈਨੂੰ ਮਕਸਦ ਅਤੇ ਆਤਮਵਿਸ਼ਵਾਸ ਦਿੱਤਾ।",
    "home.success.t3": "ਮੈਂ ਇਕੱਲਾ ਅਤੇ ਸੰਘਰਸ਼ਸ਼ੀਲ ਸੀ। ਬਿਰਧ ਆਸ਼ਰਮ ਨੇ ਮੈਨੂੰ ਦੁਬਾਰਾ ਇੱਕ ਪਰਿਵਾਰ ਦਿੱਤਾ। ਇੱਥੇ ਮੈਨੂੰ ਜੋ ਨਿੱਘ, ਦੇਖਭਾਲ ਅਤੇ ਸਤਿਕਾਰ ਮਿਲਦਾ ਹੈ, ਉਹ ਸ਼ਬਦਾਂ ਤੋਂ ਪਰੇ ਹੈ।",
    "home.why.title": "ਸ਼੍ਯਾਮ ਜਗਤ ਕਿਉਂ ਚੁਣੀਏ",
    "home.why.subtitle": "ਆਸਥਾ 'ਤੇ ਬਣਿਆ, ਮਕਸਦ ਤੋਂ ਪ੍ਰੇਰਿਤ, ਅਤੇ ਸਥਾਈ ਬਦਲਾਅ ਲਈ ਵਚਨਬੱਧ।",
    "home.why.f1.title": "ਆਸਥਾ ਤੋਂ ਪ੍ਰੇਰਿਤ",
    "home.why.f1.desc": "ਹਰ ਪਹਿਲਕਦਮੀ ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੀਆਂ ਦੈਵੀ ਸਿੱਖਿਆਵਾਂ ਵਿੱਚ ਜੜ੍ਹੀ ਹੈ - ਸੇਵਾ ਹੀ ਭਗਤੀ ਹੈ।",
    "home.why.f2.title": "ਪਾਰਦਰਸ਼ੀ",
    "home.why.f2.desc": "ਅਸੀਂ ਆਪਣੇ ਸਾਰੇ ਪ੍ਰੋਗਰਾਮਾਂ ਅਤੇ ਦਾਨਾਂ ਵਿੱਚ ਪੂਰੀ ਵਿੱਤੀ ਪਾਰਦਰਸ਼ਤਾ ਅਤੇ ਜਵਾਬਦੇਹੀ ਬਣਾਈ ਰੱਖਦੇ ਹਾਂ।",
    "home.why.f3.title": "ਭਾਈਚਾਰਾ ਕੇਂਦਰਿਤ",
    "home.why.f3.desc": "ਸਾਡਾ ਕੰਮ ਭਾਈਚਾਰੇ ਦੁਆਰਾ, ਭਾਈਚਾਰੇ ਲਈ ਸੇਧਿਤ ਹੈ - ਭਰੋਸੇ ਅਤੇ ਸਮੂਹਿਕ ਭਾਗੀਦਾਰੀ 'ਤੇ ਬਣਿਆ।",
    "home.why.f4.title": "ਪ੍ਰਮਾਣਿਤ ਵਲੰਟੀਅਰ",
