    "home.why.f6.desc": "ਅਸੀਂ ਟਿਕਾਊ ਬਦਲਾਅ 'ਤੇ ਧਿਆਨ ਕੇਂਦਰਿਤ ਕਰਦੇ ਹਾਂ - ਸਿਰਫ਼ ਥੋੜ੍ਹੇ ਸਮੇਂ ਦੀ ਰਾਹਤ ਨਹੀਂ ਸਗੋਂ ਸਥਾਈ ਮੌਕੇ ਬਣਾਉਣਾ।",
