    "home.temple.desc": "ਆਪਣੇ ਮੰਦਰ ਨੂੰ ਸ਼੍ਯਾਮ ਜਗਤ 'ਤੇ ਸੂਚੀਬੱਧ ਕਰੋ ਅਤੇ ਲੱਖਾਂ ਭਗਤਾਂ ਨਾਲ ਜੁੜੋ। ਸ਼ਰਧਾਲੂਆਂ ਨੂੰ ਆਪਣੀ ਪਵਿੱਤਰ ਥਾਂ, ਦਰਸ਼ਨ ਸਮੇਂ ਅਤੇ ਆਉਣ ਵਾਲੇ ਸਮਾਗਮਾਂ ਦਾ ਪਤਾ ਲਗਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰੋ।",
