    "home.artist.desc": "ਇੱਕ ਭਗਤੀ ਕਲਾਕਾਰ ਵਜੋਂ ਸ਼੍ਯਾਮ ਜਗਤ ਨਾਲ ਜੁੜੋ। ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਅਧਿਆਤਮਿਕ ਸਮਾਗਮਾਂ, ਸੱਭਿਆਚਾਰਕ ਪ੍ਰੋਗਰਾਮਾਂ ਅਤੇ ਪਵਿੱਤਰ ਇਕੱਠਾਂ ਵਿੱਚ ਆਪਣੀ ਪ੍ਰਤਿਭਾ ਦਿਖਾਓ।",
