    "home.join.desc": "ਸਾਡੇ ਮਿਸ਼ਨ ਦਾ ਹਿੱਸਾ ਬਣੋ ਅਤੇ ਇੱਕ ਬਿਹਤਰ ਸਮਾਜ ਬਣਾਉਣ ਵਿੱਚ ਸਾਡੀ ਮਦਦ ਕਰੋ।",
