    "home.faq.left.a1": "ਤੁਸੀਂ ਸਾਡੀ ਵੈੱਬਸਾਈਟ ਰਾਹੀਂ ਆਨਲਾਈਨ, UPI, ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਰਾਹੀਂ ਜਾਂ ਸਾਡੇ ਦਫ਼ਤਰਾਂ ਵਿੱਚ ਖੁਦ ਦਾਨ ਦੇ ਸਕਦੇ ਹੋ। ਸਾਰੇ ਦਾਨਾਂ ਦੀ ਰਸੀਦ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਉਹ 80G ਟੈਕਸ ਛੋਟ ਅਧੀਨ ਹਨ।",
