    "home.faq.right.a1": "ਸਾਡੇ ਪੋਰਟਲ 'ਤੇ ਰਜਿਸਟਰ ਕਰੋ, ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਅਤੇ ਹੁਨਰ ਅੱਪਲੋਡ ਕਰੋ, ਅਤੇ ਸਾਡੀ ਟੀਮ ਤੁਹਾਨੂੰ ਪ੍ਰਮਾਣਿਤ ਮਾਲਕਾਂ ਅਤੇ ਨੌਕਰੀ ਦੇ ਮੌਕਿਆਂ ਨਾਲ ਜੋੜੇਗੀ।",
