    "auth.signup.switchLabel": "ਸਾਈਨ ਇਨ ਕਰੋ",
    "auth.signup.fullNameError": "ਕਿਰਪਾ ਕਰਕੇ ਆਪਣਾ ਪੂਰਾ ਨਾਮ ਦਰਜ ਕਰੋ।",
    "auth.signup.mobileError": "ਇੱਕ ਵੈਧ 10-ਅੰਕਾਂ ਦਾ ਭਾਰਤੀ ਮੋਬਾਈਲ ਨੰਬਰ ਦਰਜ ਕਰੋ।",
