    "auth.signup.passwordComplexityError": "ਘੱਟੋ-ਘੱਟ ਇੱਕ ਅੱਖਰ ਅਤੇ ਇੱਕ ਨੰਬਰ ਸ਼ਾਮਲ ਕਰੋ।",
