    "baba.festival3.desc": "ਬਾਬਾ ਸ਼੍ਯਾਮ ਦਾ ਆਸ਼ੀਰਵਾਦ ਲੈਣ ਲਈ ਭਗਤਾਂ ਦੁਆਰਾ ਪਾਲਣ ਕੀਤੀ ਜਾਣ ਵਾਲੀ ਖਾਸ ਪ੍ਰਾਰਥਨਾ ਅਤੇ ਵਰਤ।",
    "baba.festival4.title": "ਭਜਨ ਸੰਧਿਆ",
    "baba.festival4.when": "ਹਰ ਸ਼ਾਮ",
    "baba.festival4.desc": "ਦਿਲ ਨੂੰ ਛੂਹਣ ਵਾਲੇ ਭਜਨਾਂ ਅਤੇ ਪ੍ਰਾਰਥਨਾਵਾਂ ਨਾਲ ਮੰਦਰ ਨੂੰ ਭਰਨ ਵਾਲੇ ਭਗਤੀ ਸੰਗੀਤ ਸੈਸ਼ਨ।",
