    "baba.ritual3.title": "ਰਾਜਭੋਗ",
    "baba.ritual3.desc": "ਦੁਪਹਿਰ ਵੇਲੇ ਬਾਬਾ ਸ਼੍ਯਾਮ ਨੂੰ ਭੋਜਨ ਦਾ ਸ਼ਾਨਦਾਰ ਭੋਗ ਅਰਪਣ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
    "baba.ritual4.title": "ਦੁਪਹਿਰ ਦਾ ਦਰਸ਼ਨ",
    "baba.ritual4.desc": "ਭਗਤ ਦੁਪਹਿਰ ਦੇ ਸਮੇਂ ਦੌਰਾਨ ਆਸ਼ੀਰਵਾਦ ਲੈਣਾ ਜਾਰੀ ਰੱਖਦੇ ਹਨ।",
    "baba.ritual5.title": "ਸੰਧਿਆ ਆਰਤੀ",
