    "about.hero.mantra": "|| ਜੈ ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ||",
    "about.hero.title": "ਸ਼੍ਯਾਮ ਜਗਤ ਬਾਰੇ",
    "about.hero.subtitle": "ਆਸਥਾ, ਦਇਆ ਅਤੇ ਮਕਸਦ ਨਾਲ ਮਨੁੱਖਤਾ ਦੀ ਸੇਵਾ",
    "about.whoWeAre.title": "ਅਸੀਂ ਕੌਣ ਹਾਂ",
    "about.whoWeAre.p1": "ਸ਼੍ਯਾਮ ਜਗਤ ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੀਆਂ ਦੈਵੀ ਸਿੱਖਿਆਵਾਂ ਅਤੇ ਆਸ਼ੀਰਵਾਦ ਤੋਂ ਪ੍ਰੇਰਿਤ ਇੱਕ ਅਧਿਆਤਮਿਕ ਅਤੇ ਸਮਾਜਿਕ ਸੰਸਥਾ ਹੈ। ਸਾਡਾ ਮਿਸ਼ਨ ਭਗਤੀ ਨੂੰ ਸਾਰਥਕ ਸਮਾਜਿਕ ਸੇਵਾ ਨਾਲ ਜੋੜ ਕੇ ਜ਼ਿੰਦਗੀਆਂ ਬਦਲਣਾ ਹੈ, ਇੱਕ ਅਜਿਹਾ ਭਾਈਚਾਰਾ ਬਣਾਉਣਾ ਜਿੱਥੇ ਦਇਆ, ਮਾਣ ਅਤੇ ਮੌਕਾ ਹਰ ਕਿਸੇ ਲਈ ਪਹੁੰਚਯੋਗ ਹੋਵੇ।",
    "about.whoWeAre.p2": "ਅਸੀਂ ਮੰਨਦੇ ਹਾਂ ਕਿ ਸੱਚੀ ਭਗਤੀ ਨਿਸ਼ਕਾਮ ਸੇਵਾ ਰਾਹੀਂ ਪ੍ਰਗਟ ਹੁੰਦੀ ਹੈ। ਸਾਡੀ ਹਰ ਪਹਿਲਕਦਮੀ ਦਇਆ, ਸਮਾਨਤਾ ਅਤੇ ਮਨੁੱਖਤਾ ਦੀਆਂ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੈ, ਜੋ ਵਿਅਕਤੀਆਂ ਅਤੇ ਪਰਿਵਾਰਾਂ ਨੂੰ ਇੱਕ ਉੱਜਵਲ ਭਵਿੱਖ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀ ਹੈ।",
    "about.vision.title": "ਸਾਡਾ ਦ੍ਰਿਸ਼ਟੀਕੋਣ",
    "about.vision.text": "ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੇ ਆਸ਼ੀਰਵਾਦ ਹੇਠ ਇੱਕ ਦਇਆਵਾਨ, ਸਸ਼ਕਤ ਅਤੇ ਆਤਮਨਿਰਭਰ ਸਮਾਜ ਬਣਾਉਣਾ ਜਿੱਥੇ ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਸਿੱਖਿਆ, ਸਿਹਤ ਸੰਭਾਲ, ਭੋਜਨ, ਆਸਰਾ, ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਅਤੇ ਮਾਣਯੋਗ ਜੀਵਨ ਤੱਕ ਪਹੁੰਚ ਹੋਵੇ।",
    "about.mission.title": "ਸਾਡਾ ਮਿਸ਼ਨ",
    "about.mission.text": "ਸਾਡਾ ਮਿਸ਼ਨ ਟਿਕਾਊ ਪਹਿਲਕਦਮੀਆਂ ਰਾਹੀਂ ਸਮਾਜ ਦੀ ਸੇਵਾ ਕਰਨਾ ਹੈ ਜੋ ਜ਼ਿੰਦਗੀਆਂ ਨੂੰ ਉੱਪਰ ਚੁੱਕਦੀਆਂ ਹਨ, ਭਾਈਚਾਰਿਆਂ ਨੂੰ ਮਜ਼ਬੂਤ ਕਰਦੀਆਂ ਹਨ ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਇੱਕ ਬਿਹਤਰ ਭਲਕ ਵਿੱਚ ਯੋਗਦਾਨ ਪਾਉਣ ਲਈ ਪ੍ਰੇਰਿਤ ਕਰਦੀਆਂ ਹਨ। ਅਸੀਂ ਵਿਅਕਤੀਆਂ ਨੂੰ ਲੋੜੀਂਦੇ ਸਰੋਤਾਂ, ਸਹਾਇਤਾ ਅਤੇ ਮੌਕਿਆਂ ਨਾਲ ਸਸ਼ਕਤ ਬਣਾ ਕੇ ਸਥਾਈ ਸਮਾਜਿਕ ਪ੍ਰਭਾਵ ਬਣਾਉਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ।",
    "about.belief.title": "ਸਾਡਾ ਵਿਸ਼ਵਾਸ",
    "about.belief.text": "ਸ਼੍ਯਾਮ ਜਗਤ ਵਿੱਚ, ਅਸੀਂ ਮੰਨਦੇ ਹਾਂ ਕਿ ਦਇਆ ਦਾ ਸਭ ਤੋਂ ਛੋਟਾ ਕਾਰਜ ਵੀ ਸਥਾਈ ਪ੍ਰਭਾਵ ਪੈਦਾ ਕਰ ਸਕਦਾ ਹੈ। ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੇ ਆਸ਼ੀਰਵਾਦ ਦੁਆਰਾ ਸੇਧਿਤ, ਅਸੀਂ ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਸੇਵਾ, ਦਇਆ ਅਤੇ ਸਕਾਰਾਤਮਕ ਤਬਦੀਲੀ ਦੀ ਇਸ ਯਾਤਰਾ ਦਾ ਹਿੱਸਾ ਬਣਨ ਲਈ ਉਤਸ਼ਾਹਿਤ ਕਰਦੇ ਹਾਂ। ਮਿਲ ਕੇ, ਅਸੀਂ ਸਿਰਫ਼ ਲੋਕਾਂ ਦੀ ਸੇਵਾ ਹੀ ਨਹੀਂ ਕਰ ਰਹੇ — ਅਸੀਂ ਆਉਣ ਵਾਲੀਆਂ ਪੀੜ੍ਹੀਆਂ ਲਈ ਉਮੀਦ ਬਣਾ ਰਹੇ ਹਾਂ, ਮੌਕੇ ਸਿਰਜ ਰਹੇ ਹਾਂ ਅਤੇ ਇੱਕ ਮਜ਼ਬੂਤ, ਦਇਆਵਾਨ ਸਮਾਜ ਦਾ ਨਿਰਮਾਣ ਕਰ ਰਹੇ ਹਾਂ।",
    "about.belief.cta": "ਸ਼੍ਯਾਮ ਪਰਿਵਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ",
