    "teamPage.breadcrumb.ourTeam": "ਸਾਡੀ ਟੀਮ",
    "teamPage.breadcrumb.overview": "ਸੰਖੇਪ ਜਾਣਕਾਰੀ",
    "teamPage.hero.title": "ਸਾਡੀ ਟੀਮ",
    "teamPage.hero.subtitle": "ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੀ ਦੈਵੀ ਕਿਰਪਾ ਹੇਠ ਸਾਡੇ ਵਿਸ਼ਵਵਿਆਪੀ ਸਮਾਜਿਕ-ਅਧਿਆਤਮਿਕ ਮਿਸ਼ਨ ਦੀ ਅਗਵਾਈ, ਵਾਧਾ ਅਤੇ ਮਜ਼ਬੂਤੀ ਲਈ ਇਕੱਠੇ ਕੰਮ ਕਰਨ ਵਾਲੇ ਸਮਰਪਿਤ ਲੋਕਾਂ ਨੂੰ ਮਿਲੋ।",
    "teamPage.leadership.title": "ਲੀਡਰਸ਼ਿਪ ਬੋਰਡ",
    "teamPage.leader1.role": "ਚੇਅਰਮੈਨ — ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ",
    "teamPage.leader1.desc": "ਸਰਹੱਦਾਂ ਅਤੇ ਪਹਿਲਕਦਮੀਆਂ ਵਿੱਚ ਸਾਡੇ ਯਤਨਾਂ ਨੂੰ ਇਕਜੁੱਟ ਕਰਨ ਲਈ ਮੁੱਖ ਰਣਨੀਤਿਕ ਦ੍ਰਿਸ਼ਟੀ ਅਤੇ ਅਧਿਆਤਮਿਕ ਦਿਸ਼ਾ ਪ੍ਰਦਾਨ ਕਰਨਾ।",
    "teamPage.leader1.cta": "ਪ੍ਰੋਫਾਈਲ ਦੇਖੋ →",
    "teamPage.leader2.role": "ਮੁੱਖ ਟਰੱਸਟੀ",
    "teamPage.leader2.desc": "ਮੁੱਲ-ਅਧਾਰਿਤ ਅਮਲ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹੋਏ ਅਧਿਆਤਮਿਕ ਟਰੱਸਟਾਂ ਦੇ ਮੁੱਖ ਪ੍ਰਸ਼ਾਸਕੀ ਅਤੇ ਨੈਤਿਕ ਢਾਂਚੇ ਦੀ ਨਿਗਰਾਨੀ ਕਰਨਾ।",
    "teamPage.leader2.cta": "ਪ੍ਰੋਫਾਈਲ ਦੇਖੋ →",
    "teamPage.leader3.role": "ਸੰਚਾਲਕ ਸੰਸਥਾ",
    "teamPage.leader3.desc": "ਸਾਡੇ ਕਾਨੂੰਨੀ ਟਰੱਸਟਾਂ ਦਾ ਨਿਰਦੇਸ਼ਨ ਕਰਨ ਵਾਲੇ ਅਧਿਆਤਮਿਕ ਸਾਧਕਾਂ, ਵਪਾਰਕ ਆਗੂਆਂ ਅਤੇ ਸਮਾਜਿਕ ਸੁਧਾਰਕਾਂ ਦਾ ਇੱਕ ਬਹੁਤ ਹੀ ਸਮਰਪਿਤ ਬੋਰਡ।",
    "teamPage.leader3.cta": "ਸਾਰੇ ਟਰੱਸਟੀ ਦੇਖੋ →",
    "teamPage.management.title": "ਪ੍ਰਬੰਧਨ ਟੀਮ",
    "teamPage.management.desc": "ਸਾਡੇ ਕਾਰਜਕਾਰੀ ਸੰਚਾਲਨ, ਸਮਾਗਮ ਤਾਲਮੇਲਕਾਰ ਅਤੇ ਰੋਜ਼ਾਨਾ ਪ੍ਰਸ਼ਾਸਕੀ ਸਟਾਫ ਇਹ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਨ ਕਿ ਸਥਾਨਕ ਦਰਸ਼ਨ, ਵਿਆਹ ਸੰਬੰਧੀ ਸੰਪਰਕ, ਮੰਦਰ ਸੂਚੀ ਅੱਪਡੇਟ ਅਤੇ ਮੈਡੀਕਲ ਸੇਵਾਵਾਂ ਸਹਿਜੇ ਹੀ ਸੰਭਾਲੀਆਂ ਜਾਣ।",
    "teamPage.management.cta": "ਪ੍ਰਬੰਧਨ ਟੀਮ ਦੇਖੋ",
    "teamPage.advisory.title": "ਸਲਾਹਕਾਰ ਬੋਰਡ",
    "teamPage.advisory.desc": "ਰਿਸ਼ੀ, ਸੇਵਾਮੁਕਤ ਨਿਆਂਕਾਰ ਅਤੇ ਬਹੁਤ ਤਜਰਬੇਕਾਰ ਭਾਈਚਾਰਕ ਬਜ਼ੁਰਗ ਜੋ ਸਾਡੀਆਂ ਨੀਤੀਆਂ ਨੂੰ ਨੈਤਿਕਤਾ ਅਤੇ ਧਰਮ ਵਿੱਚ ਸਥਿਰ ਰੱਖਦੇ ਹਨ।",
    "teamPage.advisory.cta": "ਸਲਾਹਕਾਰਾਂ ਨੂੰ ਮਿਲੋ →",
    "teamPage.stateCommittee.title": "ਰਾਜ ਕਮੇਟੀ ਟੀਮਾਂ",
    "teamPage.stateCommittee.desc": "15+ ਭਾਰਤੀ ਰਾਜਾਂ ਵਿੱਚ ਸਥਾਨਕ ਸ਼ਾਖਾਵਾਂ, ਮੰਦਰ ਰਜਿਸਟਰੀਆਂ, ਭਜਨ ਸੰਧਿਆ ਬੁਕਿੰਗਾਂ ਅਤੇ ਸਮਾਜਿਕ ਸਹਾਇਤਾ ਨੈੱਟਵਰਕਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ ਵਾਲੀਆਂ ਖੇਤਰੀ ਟੀਮਾਂ।",
    "teamPage.stateCommittee.cta": "ਅਧਿਆਏ ਦੇਖੋ →",

