    "registerPage.hero.desc": "ਵਿਅਕਤੀ, ਸੰਗਠਨ, ਜਾਂ ਸੇਵਾ ਪ੍ਰਦਾਤਾ ਵਜੋਂ ਰਜਿਸਟਰ ਕਰੋ ਅਤੇ ਸਾਡੇ ਵਧ ਰਹੇ ਅਧਿਆਤਮਿਕ ਪਰਿਵਾਰ ਦਾ ਹਿੱਸਾ ਬਣੋ। ਆਸਥਾ, ਸੇਵਾ ਅਤੇ ਭਗਤੀ ਵਿੱਚ ਇਕਜੁੱਟ ਹੋਵੋ।",
