    "registerPage.category2.title": "ਨਰਤਕ",
    "registerPage.category2.desc": "ਪ੍ਰਮੁੱਖ ਤਿਉਹਾਰਾਂ ਵਿੱਚ ਆਪਣੇ ਕਲਾਸੀਕਲ ਅਤੇ ਭਗਤੀ ਨਾਚ ਪ੍ਰਦਰਸ਼ਨ ਸਾਂਝੇ ਕਰੋ।",
