    "registerPage.category11.title": "ਸਵਯੰਸੇਵਕ",
    "registerPage.category11.desc": "ਪਵਿੱਤਰ ਭਾਈਚਾਰੇ ਦੀ ਸੇਵਾ ਲਈ ਆਪਣਾ ਸਮਾਂ, ਹੁਨਰ ਅਤੇ ਊਰਜਾ ਯੋਗਦਾਨ ਪਾਓ।",
    "registerPage.category12.title": "ਉਤਪਾਦ",
