    "registerPage.howItWorks.eyebrow": "ਸਧਾਰਨ ਪ੍ਰਕਿਰਿਆ",
    "registerPage.howItWorks.title": "ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
    "registerPage.step1.title": "ਆਪਣੀ ਸ਼੍ਰੇਣੀ ਚੁਣੋ",
    "registerPage.step1.desc": "ਉਹ ਪ੍ਰੋਫਾਈਲ ਚੁਣੋ ਜੋ ਤੁਹਾਡੀ ਅਧਿਆਤਮਿਕ ਕਲਾ, ਸੇਵਾਵਾਂ, ਜਾਂ ਸੰਗਠਨ ਨਾਲ ਸਭ ਤੋਂ ਵਧੀਆ ਮੇਲ ਖਾਂਦੀ ਹੋਵੇ।",
    "registerPage.step2.title": "ਆਪਣੇ ਵੇਰਵੇ ਭਰੋ",
    "registerPage.step2.desc": "ਆਪਣੇ ਪ੍ਰਮਾਣਿਕ ਸਬੂਤਾਂ ਅਤੇ ਪੋਰਟਫੋਲੀਓ ਨਾਲ ਸੁਰੱਖਿਅਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫਾਰਮ ਪੂਰਾ ਕਰੋ।",
    "registerPage.step3.title": "ਪ੍ਰਮਾਣਿਤ ਹੋਵੋ ਅਤੇ ਲਾਈਵ ਜਾਓ",
    "registerPage.step3.desc": "ਸਾਡੀ ਟੀਮ ਤੁਹਾਡੀ ਅਰਜ਼ੀ ਦੀ ਸਮੀਖਿਆ ਕਰੇਗੀ। ਪ੍ਰਮਾਣਿਤ ਹੋਣ ਤੋਂ ਬਾਅਦ, ਤੁਸੀਂ ਤੁਰੰਤ ਲਾਈਵ ਹੋ ਜਾਂਦੇ ਹੋ!",
    "registerPage.benefits.eyebrow": "ਫਾਇਦੇ",
    "registerPage.benefits.title": "ਸ਼੍ਯਾਮ ਜਗਤ ਨਾਲ ਰਜਿਸਟਰ ਕਿਉਂ ਕਰੀਏ?",
    "registerPage.benefit1.title": "ਦੇਸ਼ ਵਿਆਪੀ ਦਿੱਖ",
    "registerPage.benefit1.desc": "ਅਧਿਆਤਮਿਕ ਸੇਵਾਵਾਂ ਅਤੇ ਵਸਤੂਆਂ ਦੀ ਸਰਗਰਮੀ ਨਾਲ ਭਾਲ ਕਰ ਰਹੇ ਲੱਖਾਂ ਭਗਤਾਂ ਤੱਕ ਪਹੁੰਚੋ।",
    "registerPage.benefit2.title": "ਪ੍ਰਮਾਣਿਤ ਟਰੱਸਟ ਬੈਜ",
    "registerPage.benefit2.desc": "ਪ੍ਰਮਾਣਿਕਤਾ ਦਿਖਾਉਣ ਅਤੇ ਭਗਤਾਂ ਦਾ ਭਰੋਸਾ ਬਣਾਉਣ ਲਈ ਇੱਕ ਸੁਨਹਿਰੀ ਟਰੱਸਟ ਬੈਜ ਕਮਾਓ।",
    "registerPage.benefit3.title": "ਭਾਈਚਾਰਕ ਸਹਾਇਤਾ",
    "registerPage.benefit3.desc": "ਸਾਡੇ ਡਿਜੀਟਲ ਸੇਵਾ ਸਹਾਇਤਾ ਮਾਹਿਰਾਂ ਤੋਂ ਸਮਰਪਿਤ ਚੌਵੀ ਘੰਟੇ ਮਦਦ ਲਓ।",
    "registerPage.benefit4.title": "ਮੁਫ਼ਤ ਸੂਚੀਕਰਨ",
    "registerPage.benefit4.desc": "ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਬਣਾਉਣ ਅਤੇ ਸੂਚੀਬੱਧ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਬਿਲਕੁਲ ਕੋਈ ਛੁਪਿਆ ਚਾਰਜ ਜਾਂ ਫੀਸ ਨਹੀਂ।",
    "registerPage.testimonials.eyebrow": "ਫੀਡਬੈਕ",
    "registerPage.testimonials.title": "ਸਾਡੇ ਪਵਿੱਤਰ ਪਰਿਵਾਰ ਦੀਆਂ ਆਵਾਜ਼ਾਂ",
    "registerPage.testimonial1.quote": "ਸ਼੍ਯਾਮ ਜਗਤ ਦੇ ਪਲੇਟਫਾਰਮ ਹੇਠ ਖਾਟੂ ਸ਼੍ਯਾਮ ਜੀ ਦੇ ਸਮਾਗਮਾਂ ਵਿੱਚ ਭਜਨ ਗਾਉਣਾ ਮੇਰੇ ਕਰੀਅਰ ਦਾ ਸਭ ਤੋਂ ਉੱਚਾ ਸਿਖਰ ਰਿਹਾ ਹੈ। ਊਰਜਾ ਅਤੇ ਪ੍ਰਬੰਧਨ ਪੂਰੀ ਤਰ੍ਹਾਂ ਅਧਿਆਤਮਿਕ ਹੈ।",
    "registerPage.testimonial1.role": "ਭਜਨ ਗਾਇਕ",
    "registerPage.testimonial2.quote": "ਸਾਡੇ ਇਤਿਹਾਸਕ ਮੰਦਰ ਨੂੰ ਰਜਿਸਟਰ ਕਰਨ ਨਾਲ ਅਸੀਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਆਨਲਾਈਨ ਆ ਗਏ। ਹੁਣ ਅਸੀਂ ਦਰਸ਼ਨ ਬੁਕਿੰਗ ਸਹਿਜੇ ਹੀ ਸੰਭਾਲਦੇ ਹਾਂ ਅਤੇ ਦੇਸ਼ ਭਰ ਦੇ ਬਜ਼ੁਰਗਾਂ ਨੂੰ ਆਰਤੀ ਸਟ੍ਰੀਮ ਕਰ ਸਕਦੇ ਹਾਂ।",
    "registerPage.testimonial2.role": "ਮੰਦਰ ਪ੍ਰਸ਼ਾਸਕ",
    "registerPage.testimonial3.quote": "ਇੱਕ ਕਲਾਸੀਕਲ ਕਥਕ ਨਰਤਕੀ ਵਜੋਂ, ਸਹੀ ਅਧਿਆਤਮਿਕ ਪਲੇਟਫਾਰਮ ਲੱਭਣਾ ਔਖਾ ਸੀ। ਸ਼੍ਯਾਮ ਜਗਤ ਨੇ ਸਾਨੂੰ ਪੂਰੇ ਭਾਰਤ ਦੇ ਪ੍ਰਮੁੱਖ ਦੈਵੀ ਸਮਾਗਮਾਂ ਨਾਲ ਸਿੱਧਾ ਜੋੜਿਆ।",
    "registerPage.testimonial3.role": "ਕਲਾਸੀਕਲ ਨਰਤਕੀ",
    "registerPage.faq.eyebrow": "ਸਵਾਲ",
    "registerPage.faq.title": "ਅਕਸਰ ਪੁੱਛੇ ਜਾਂਦੇ ਸਵਾਲ",
    "registerPage.faq1.q": "ਕੀ ਕੋਈ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫੀਸ ਹੈ?",
    "registerPage.faq1.a": "ਨਹੀਂ, ਸ਼੍ਯਾਮ ਜਗਤ ਪਲੇਟਫਾਰਮ 'ਤੇ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਾਰੇ ਵਿਅਕਤੀਗਤ ਕਲਾਕਾਰਾਂ, ਮੰਦਰਾਂ ਅਤੇ ਸੰਗਠਨਾਂ ਲਈ ਬਿਲਕੁਲ ਮੁਫ਼ਤ ਹੈ।",
    "registerPage.faq2.q": "ਪ੍ਰਮਾਣੀਕਰਨ ਪ੍ਰਕਿਰਿਆ ਕੀ ਹੈ?",
    "registerPage.faq2.a": "ਸਾਡੀ ਸਮਰਪਿਤ ਸੇਵਾ ਕਮੇਟੀ ਹਰ ਪ੍ਰੋਫਾਈਲ ਦੀ 24 ਤੋਂ 48 ਘੰਟਿਆਂ ਦੇ ਅੰਦਰ ਸਮੀਖਿਆ ਕਰਦੀ ਹੈ। ਅਸੀਂ ਆਪਣੀ ਡਾਇਰੈਕਟਰੀ ਦੇ ਪਵਿੱਤਰ ਮਾਹੌਲ ਨੂੰ ਬਣਾਈ ਰੱਖਣ ਲਈ ਪਛਾਣ ਸਬੂਤ ਅਤੇ ਪ੍ਰਮਾਣ ਪੱਤਰਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦੇ ਹਾਂ।",
    "registerPage.faq3.q": "ਕੀ ਮੈਂ ਕਈ ਪ੍ਰੋਫਾਈਲਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "registerPage.faq3.a": "ਹਾਂ, ਤੁਸੀਂ ਇੱਕ ਵਿਅਕਤੀ ਵਜੋਂ ਰਜਿਸਟਰ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਇੱਕ ਏਕੀਕ੍ਰਿਤ ਐਡਮਿਨ ਡੈਸ਼ਬੋਰਡ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਮੰਦਰ ਜਾਂ ਮੰਡਲ ਸੂਚੀ ਵੀ ਪ੍ਰਬੰਧਿਤ ਕਰ ਸਕਦੇ ਹੋ।",
    "registerPage.faq4.q": "ਯਾਤਰੀ ਧਰਮਸ਼ਾਲਾਵਾਂ ਨਾਲ ਕਿਵੇਂ ਸੰਪਰਕ ਕਰਦੇ ਹਨ?",
    "registerPage.faq4.a": "ਇੱਕ ਵਾਰ ਸੂਚੀਬੱਧ ਹੋਣ ਤੋਂ ਬਾਅਦ, ਤੁਹਾਡੀ ਸੰਪਰਕ ਜਾਣਕਾਰੀ, ਸਥਾਨ ਨਕਸ਼ਾ, ਅਤੇ ਬੁਕਿੰਗ ਦਿਸ਼ਾ-ਨਿਰਦੇਸ਼ ਸਿੱਧੇ ਲੱਖਾਂ ਸ਼ਰਧਾਲੂਆਂ ਨੂੰ ਦਿਖਾਈ ਦੇਣਗੇ ਜੋ ਤੁਰੰਤ ਕਾਲ ਕਰ ਸਕਦੇ ਹਨ ਜਾਂ ਬੁੱਕ ਕਰ ਸਕਦੇ ਹਨ।",
    "registerPage.cta.title": "ਸਾਡੇ ਪਰਿਵਾਰ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਣ ਲਈ ਤਿਆਰ ਹੋ?",
    "registerPage.cta.desc": "ਆਸਥਾ ਦੀ ਛਾਲ ਮਾਰੋ। ਰਜਿਸਟਰ ਕਰਨ ਵਿੱਚ 5 ਮਿੰਟ ਤੋਂ ਵੀ ਘੱਟ ਸਮਾਂ ਲੱਗਦਾ ਹੈ ਅਤੇ ਇਹ 100% ਮੁਫ਼ਤ ਹੈ। ਲੱਖਾਂ ਬਾਬਾ ਸ਼੍ਯਾਮ ਭਗਤਾਂ ਨਾਲ ਸਿੱਧਾ ਜੁੜੋ।",
    "registerPage.cta.button": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸ਼ੁਰੂ ਕਰੋ",

