    "templeReg.heroTitle": "ਆਪਣੇ ਮੰਦਰ ਨੂੰ ਰਜਿਸਟਰ ਕਰੋ",
    "templeReg.heroDesc": "ਸ਼੍ਯਾਮ ਜਗਤ 'ਤੇ ਆਪਣੇ ਮੰਦਰ ਨੂੰ ਸੂਚੀਬੱਧ ਕਰੋ ਅਤੇ ਲੱਖਾਂ ਭਗਤਾਂ ਨਾਲ ਜੁੜੋ। ਸ਼ਰਧਾਲੂਆਂ ਨੂੰ ਤੁਹਾਡੀ ਪਵਿੱਤਰ ਥਾਂ, ਸੇਵਾਵਾਂ, ਰੋਜ਼ਾਨਾ ਦਰਸ਼ਨ ਸਮੇਂ ਅਤੇ ਆਉਣ ਵਾਲੇ ਤਿਉਹਾਰਾਂ ਦਾ ਪਤਾ ਲਗਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰੋ।",
