    "templeReg.service6.desc": "ਫਾਲਗੁਨ ਮੇਲੇ ਵਰਗੇ ਵੱਡੇ ਮੌਕਿਆਂ ਲਈ ਵਿਸ਼ੇਸ਼ ਪ੍ਰਬੰਧ",
    "templeReg.service7.title": "ਧਿਆਨ ਕਮਰਾ",
    "templeReg.service7.desc": "ਸ਼ਾਂਤ ਪ੍ਰਾਰਥਨਾ/ਧਿਆਨ ਸਥਾਨ",
    "templeReg.service8.title": "ਧਰਮਸ਼ਾਲਾ / ਮਹਿਮਾਨ ਠਹਿਰਾਅ",
    "templeReg.service8.desc": "ਆਉਣ ਵਾਲੇ ਸ਼ਰਧਾਲੂਆਂ ਲਈ ਰਿਹਾਇਸ਼",
    "templeReg.service9.title": "ਗਊਸ਼ਾਲਾ (ਗਊ ਆਸਰਾ)",
    "templeReg.service9.desc": "ਪਰਿਸਰ ਵਿੱਚ ਪਵਿੱਤਰ ਗਾਵਾਂ ਦੀ ਦੇਖਭਾਲ",
    "templeReg.service10.title": "ਵੈਦਿਕ ਪਾਠਸ਼ਾਲਾ",
    "templeReg.service10.desc": "ਸ਼ਾਸਤਰਾਂ ਲਈ ਸਿੱਖਿਆ ਪ੍ਰੋਗਰਾਮ",
    "templeReg.gallery.title": "ਮੰਦਰ ਫੋਟੋ ਗੈਲਰੀ",
    "templeReg.gallery.dragDrop": "ਆਪਣੇ ਮੰਦਰ ਦੀਆਂ ਫੋਟੋਆਂ ਇੱਥੇ ਖਿੱਚੋ ਅਤੇ ਛੱਡੋ ਜਾਂ",
    "templeReg.gallery.browse": "ਫਾਈਲਾਂ ਬ੍ਰਾਊਜ਼ ਕਰੋ",
    "templeReg.gallery.hint": "10 ਫੋਟੋਆਂ ਤੱਕ ਅੱਪਲੋਡ ਕਰੋ। ਸਵੀਕਾਰਯੋਗ ਫਾਰਮੈਟ: JPG, PNG। ਪ੍ਰਤੀ ਫੋਟੋ ਵੱਧ ਤੋਂ ਵੱਧ 5MB। ਮੁੱਖ ਦੇਵਤਾ, ਮੰਦਰ ਦੇ ਬਾਹਰੀ ਹਿੱਸੇ, ਅੰਦਰੂਨੀ ਹਿੱਸੇ ਅਤੇ ਪਰਿਸਰ ਦੀਆਂ ਫੋਟੋਆਂ ਸ਼ਾਮਲ ਕਰੋ।",
    "templeReg.terms.certify": "ਮੈਂ ਪ੍ਰਮਾਣਿਤ ਕਰਦਾ ਹਾਂ ਕਿ ਦਿੱਤੀ ਗਈ ਜਾਣਕਾਰੀ ਸਟੀਕ ਹੈ ਅਤੇ ਮੈਂ ਮੰਦਰ ਟਰੱਸਟ ਵੱਲੋਂ ਇਸ ਮੰਦਰ ਨੂੰ ਰਜਿਸਟਰ ਕਰਨ ਲਈ ਅਧਿਕਾਰਤ ਹਾਂ।",
    "templeReg.terms.agree": "ਮੈਂ ਸ਼੍ਯਾਮ ਜਗਤ ਅਧਿਆਤਮਿਕ ਪਲੇਟਫਾਰਮ ਦੀਆਂ ਸੇਵਾ ਦੀਆਂ ਸ਼ਰਤਾਂ ਅਤੇ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਨਾਲ ਸਹਿਮਤ ਹਾਂ।",
    "templeReg.terms.consent": "ਮੈਂ ਪਲੇਟਫਾਰਮ ਅੱਪਡੇਟਾਂ ਅਤੇ ਭਗਤਾਂ ਦੀਆਂ ਪੁੱਛਗਿੱਛਾਂ ਬਾਰੇ ਸੰਚਾਰ ਪ੍ਰਾਪਤ ਕਰਨ ਦੀ ਸਹਿਮਤੀ ਦਿੰਦਾ ਹਾਂ।",
    "templeReg.submit": "ਮੰਦਰ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਬਮਿਟ ਕਰੋ",
    "templeReg.why.title": "ਸ਼੍ਯਾਮ ਜਗਤ 'ਤੇ ਆਪਣਾ ਮੰਦਰ ਕਿਉਂ ਸੂਚੀਬੱਧ ਕਰੀਏ?",
    "templeReg.why.subtitle": "ਦੁਨੀਆ ਭਰ ਦੇ ਲੱਖਾਂ ਖੋਜਕਰਤਾਵਾਂ ਨਾਲ ਭਗਤੀ ਦੇ ਪਵਿੱਤਰ ਸਥਾਨਾਂ ਨੂੰ ਜੋੜਨਾ। ਸੰਚਾਰ ਨੂੰ ਸਰਲ ਬਣਾਓ, ਸਮਾਗਮਾਂ ਦਾ ਆਯੋਜਨ ਕਰੋ, ਅਤੇ ਭਾਈਚਾਰਕ ਸਹਾਇਤਾ ਨੂੰ ਸਹਿਜੇ ਹੀ ਪ੍ਰਬੰਧਿਤ ਕਰੋ।",
    "templeReg.whyFeature1Title": "ਭਗਤਾਂ ਤੱਕ ਪਹੁੰਚੋ",
    "templeReg.whyFeature1Desc": "ਆਪਣੇ ਨੇੜੇ ਮੰਦਰਾਂ ਦੀ ਭਾਲ ਕਰ ਰਹੇ ਲੱਖਾਂ ਭਗਤਾਂ ਨਾਲ ਜੁੜੋ, ਉਨ੍ਹਾਂ ਨੂੰ ਆਪਣੇ ਪਵਿੱਤਰ ਸਥਾਨ ਵੱਲ ਮਾਰਗਦਰਸ਼ਨ ਕਰੋ।",
    "templeReg.whyFeature2Title": "ਸਮਾਗਮਾਂ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰੋ",
    "templeReg.whyFeature2Desc": "ਨਿਯਮਿਤ ਤਿਉਹਾਰਾਂ, ਵਿਸ਼ੇਸ਼ ਪੂਜਾਵਾਂ ਅਤੇ ਭੰਡਾਰਿਆਂ ਦਾ ਐਲਾਨ ਇੱਕ ਵਿਸ਼ਾਲ, ਬਹੁਤ ਜ਼ਿਆਦਾ ਜੁੜੇ ਹੋਏ ਦਰਸ਼ਕਾਂ ਨੂੰ ਕਰੋ।",
    "templeReg.whyFeature3Title": "ਦਾਨ ਪ੍ਰਾਪਤ ਕਰੋ",
    "templeReg.whyFeature3Desc": "ਸੁਰੱਖਿਅਤ ਅਤੇ ਪਾਰਦਰਸ਼ੀ ਢੰਗ ਨਾਲ ਆਨਲਾਈਨ ਦਾਨ ਸਵੀਕਾਰ ਕਰੋ, ਮੰਦਰ ਦੇ ਰੱਖ-ਰਖਾਅ ਲਈ ਸਿੱਧਾ ਵਿੱਤੀ ਸਹਾਇਤਾ ਪੈਦਾ ਕਰੋ।",
    "templeReg.whyFeature4Title": "ਭਾਈਚਾਰਾ ਬਣਾਓ",
    "templeReg.whyFeature4Desc": "ਆਪਣੇ ਮੰਦਰ ਦੇ ਦਰਸ਼ਕਾਂ ਨੂੰ ਡਿਜੀਟਲ-ਪਹਿਲਾਂ ਵਧਾਓ, ਆਸ਼ੀਰਵਾਦ ਭੇਜੋ ਅਤੇ ਅਧਿਆਤਮਿਕ ਸਿੱਖਿਆਵਾਂ ਨੂੰ ਸਹਿਜੇ ਹੀ ਸਾਂਝਾ ਕਰੋ।",

    "teamShared.advertisement": "ਇਸ਼ਤਿਹਾਰ",
    "teamShared.adSpot300": "ਭਗਤੀ ਇਸ਼ਤਿਹਾਰ ਸਥਾਨ — 300 × 250",
    "teamShared.viewProfile": "ਪ੍ਰੋਫਾਈਲ ਵੇਖੋ",
    "teamShared.viewProfileArrow": "ਪ੍ਰੋਫਾਈਲ ਵੇਖੋ →",
