    "chairmanPage.breadcrumbCurrent": "ਪ੍ਰਧਾਨ",
    "chairmanPage.roleTitle": "ਪ੍ਰਧਾਨ — ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ",
    "chairmanPage.bio": "ਇੱਕ ਜੀਵਨ ਭਰ ਦੇ ਅਧਿਆਤਮਿਕ ਖੋਜੀ ਅਤੇ ਸਮਾਜਿਕ ਤਬਦੀਲੀ ਦੇ ਨਿਰਮਾਤਾ, ਸ਼੍ਰੀ ਰਮੇਸ਼ ਕੁਮਾਰ ਜੀ ਨੇ ਤਿੰਨ ਦਹਾਕਿਆਂ ਤੋਂ ਵੱਧ ਸਮਾਂ ਵਿਸ਼ਵਵਿਆਪੀ ਅਧਿਆਤਮਿਕ ਭਾਈਚਾਰਿਆਂ ਨੂੰ ਸੰਗਠਿਤ ਕਰਨ, ਰਾਹਤ ਪ੍ਰੋਗਰਾਮਾਂ ਦਾ ਸੰਚਾਲਨ ਕਰਨ ਅਤੇ ਸੰਸਥਾਵਾਂ ਬਣਾਉਣ ਲਈ ਸਮਰਪਿਤ ਕੀਤਾ ਹੈ।",
    "chairmanPage.ctaSchedule": "ਮੁਲਾਕਾਤ ਦਾ ਸਮਾਂ ਲਓ",
    "chairmanPage.quoteTitle": "“ਸ਼ਰਧਾ ਤਾਂ ਹੀ ਸ਼ਕਤੀ ਦਿੰਦੀ ਹੈ ਜਦੋਂ ਉਹ ਅਣਥੱਕ ਮਨੁੱਖੀ ਸੇਵਾ ਵਿੱਚ ਬਦਲ ਜਾਂਦੀ ਹੈ।”",
    "chairmanPage.quoteBody": "“ਅਸੀਂ ਅਧਿਆਤਮਿਕ ਸੰਪਰਕ ਦੇ ਇੱਕ ਨਵੇਂ ਯੁੱਗ ਵਿੱਚ ਦਾਖਲ ਹੋ ਚੁੱਕੇ ਹਾਂ। ਸਾਡਾ ਮਿਸ਼ਨ ਆਧੁਨਿਕ ਡਿਜੀਟਲ ਪ੍ਰਣਾਲੀਆਂ ਦੀ ਸ਼ਕਤੀ ਦੀ ਵਰਤੋਂ ਕਰਨਾ ਹੈ ਤਾਂ ਜੋ ਕੋਈ ਵੀ ਭਗਤ ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੀ ਦਿਵਯ ਆਭਾ ਦਾ ਅਨੁਭਵ ਕਰਨ ਤੋਂ ਵਾਂਝਾ ਨਾ ਰਹੇ, ਅਤੇ ਸਾਡੀ ਪਹੁੰਚ ਵਿੱਚ ਕੋਈ ਵੀ ਬਜ਼ੁਰਗ ਜਾਂ ਭੁੱਖਾ ਬੱਚਾ ਸਹਾਇਤਾ ਤੋਂ ਬਿਨਾਂ ਨਾ ਰਹੇ।”",
    "chairmanPage.quoteSignatureLabel": "ਪ੍ਰਧਾਨ ਦੇ ਦਸਤਖਤ ਅਤੇ ਮੋਹਰ ਪ੍ਰਵਾਨਿਤ",
    "chairmanPage.milestonesTitle": "ਲੀਡਰਸ਼ਿਪ ਯਾਤਰਾ ਅਤੇ ਮੀਲ ਪੱਥਰ",
    "chairmanPage.milestone1Year": "1998 – ਹੁਣ ਤੱਕ",
    "chairmanPage.milestone1Title": "ਸੰਸਥਾਪਕ ਨਿਰਦੇਸ਼ਕ, ਸ਼੍ਯਾਮ ਸੇਵਾ ਪਹਿਲਕਦਮੀਆਂ",
    "chairmanPage.milestone1Desc": "ਖਾਟੂ, ਰਾਜਸਥਾਨ ਆਉਣ ਵਾਲੇ ਸ਼ਰਧਾਲੂਆਂ ਲਈ ਮੁੱਢਲੇ ਮੈਡੀਕਲ ਕੈਂਪਾਂ ਅਤੇ ਮੁਫ਼ਤ ਰਸੋਈ ਸੇਵਾਵਾਂ ਦੀ ਅਗਵਾਈ ਕੀਤੀ।",
    "chairmanPage.milestone2Year": "2012",
    "chairmanPage.milestone2Title": "ਅਧਿਆਤਮਿਕ ਸੁਧਾਰ ਪੁਰਸਕਾਰ ਪ੍ਰਾਪਤਕਰਤਾ",
    "chairmanPage.milestone2Desc": "ਸ਼ਰਧਾਲੂ ਭੀੜ-ਪ੍ਰਬੰਧਨ ਡੇਟਾਬੇਸ ਅਤੇ ਸੁਰੱਖਿਆ ਦੇ ਆਧੁਨਿਕੀਕਰਨ ਲਈ ਰਾਸ਼ਟਰੀ ਪੱਧਰ 'ਤੇ ਮਾਨਤਾ ਪ੍ਰਾਪਤ।",
    "chairmanPage.milestone3Year": "2020",
    "chairmanPage.milestone3Title": "ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ ਦੇ ਗਲੋਬਲ ਪ੍ਰਧਾਨ ਨਿਯੁਕਤ",
    "chairmanPage.milestone3Desc": "ਡਿਜੀਟਲੀਕਰਨ, ਵਿਆਹ ਪਲੇਟਫਾਰਮ ਅਤੇ ਰਾਜ-ਵਿਆਪੀ ਸ਼ਾਖਾ ਏਕੀਕਰਨ ਦੀ ਅਗਵਾਈ ਕਰ ਰਹੇ ਹਨ।",
    "chairmanPage.credEducation": "ਸਿੱਖਿਆ",
    "chairmanPage.credKeyResponsibility": "ਮੁੱਖ ਜ਼ਿੰਮੇਵਾਰੀ",

    "mukhyaTrusteePage.breadcrumbCurrent": "ਮੁੱਖ ਟਰੱਸਟੀ",
    "mukhyaTrusteePage.roleTitle": "ਮੁੱਖ ਟਰੱਸਟੀ — ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ",
    "mukhyaTrusteePage.bio": "ਪ੍ਰਸ਼ਾਸਨਿਕ ਨੈਤਿਕਤਾ ਅਤੇ ਭਾਈਚਾਰਕ ਭਲਾਈ ਦਾ ਇੱਕ ਥੰਮ੍ਹ, ਸ਼੍ਰੀਮਤੀ ਸੁਨੀਤਾ ਦੇਵੀ ਜੀ ਖਾਟੂ ਮੰਦਰ ਸੰਚਾਲਨ, ਔਰਤਾਂ ਦੇ ਸਸ਼ਕਤੀਕਰਨ ਅਤੇ ਬਜ਼ੁਰਗ ਦੇਖਭਾਲ ਘਰਾਂ ਨੂੰ ਸਮਰਪਿਤ ਰਵਾਇਤੀ ਪਰਿਵਾਰਕ ਟਰੱਸਟਾਂ ਦਾ ਸੰਚਾਲਨ ਕਰਦੀ ਹੈ।",
    "mukhyaTrusteePage.ctaConnect": "ਦਫ਼ਤਰ ਨਾਲ ਸੰਪਰਕ ਕਰੋ",
    "mukhyaTrusteePage.quoteTitle": "“ਅਸਲ ਸਸ਼ਕਤੀਕਰਨ ਦਾ ਮਤਲਬ ਹੈ ਸਾਡੀਆਂ ਧੀਆਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਣਾ ਅਤੇ ਸਾਡੇ ਬਜ਼ੁਰਗਾਂ ਦੀ ਸੁਰੱਖਿਆ ਕਰਨਾ।”",
    "mukhyaTrusteePage.quoteBody": "“ਸ਼੍ਯਾਮ ਜਗਤ ਦੀ ਤਾਕਤ ਸਭ ਤੋਂ ਕਮਜ਼ੋਰ ਵਰਗ ਲਈ ਅਸੀਂ ਜੋ ਆਤਮ-ਨਿਰਭਰਤਾ ਪੈਦਾ ਕਰ ਸਕਦੇ ਹਾਂ, ਉਸ ਵਿੱਚ ਹੈ। ਸਰਗਰਮ ਹੁਨਰ ਸਿੱਖਿਆ ਅਤੇ ਪਾਰਦਰਸ਼ੀ ਦਾਨੀ ਸਹਾਇਤਾ ਰਾਹੀਂ, ਅਸੀਂ ਸਾਰੇ ਜ਼ਿਲ੍ਹਿਆਂ ਵਿੱਚ ਆਪਣੇ ਮਹਿਲਾ ਸਹਿਕਾਰੀ ਸਮੂਹਾਂ ਅਤੇ ਬਜ਼ੁਰਗ ਦੇਖਭਾਲ ਨੈੱਟਵਰਕਾਂ ਦਾ ਵਿਸਥਾਰ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਾਂ।”",
    "mukhyaTrusteePage.visionTitle": "ਦ੍ਰਿਸ਼ਟੀਕੋਣ ਅਤੇ ਧਿਆਨ ਕੇਂਦਰਿਤ ਖੇਤਰ",
    "mukhyaTrusteePage.focus1Title": "ਪੇਂਡੂ ਔਰਤਾਂ ਦਾ ਸਸ਼ਕਤੀਕਰਨ",
    "mukhyaTrusteePage.focus1Desc": "ਟਿਕਾਊ ਆਮਦਨ ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਣ ਵਾਲੇ ਵੋਕੇਸ਼ਨਲ ਸਿਲਾਈ, ਸ਼ਿਲਪ ਡਿਜ਼ਾਈਨ ਅਤੇ ਕੰਪਿਊਟਰ ਸਾਖਰਤਾ ਕੇਂਦਰਾਂ ਦੀ ਅਗਵਾਈ।",
    "mukhyaTrusteePage.focus2Title": "ਬਜ਼ੁਰਗ ਨਾਗਰਿਕ ਭਲਾਈ",
    "mukhyaTrusteePage.focus2Desc": "ਜੈਪੁਰ ਅਤੇ ਸੀਕਰ ਦੇ ਬਿਰਧ ਆਸ਼ਰਮਾਂ ਵਿੱਚ ਸਨਮਾਨਜਨਕ ਰਿਹਾਇਸ਼ ਅਤੇ ਉੱਚ-ਦੇਖਭਾਲ ਨਰਸਿੰਗ ਯੂਨਿਟਾਂ ਦੀ ਸਥਾਪਨਾ।",
    "mukhyaTrusteePage.focus3Title": "ਅਨੂਪ ਸੇਵਾ ਵਿਆਹ ਸੇਵਾਵਾਂ",
    "mukhyaTrusteePage.focus3Desc": "ਭਾਈਚਾਰਕ-ਸਮਰਥਿਤ ਆਨਲਾਈਨ ਵਿਆਹ ਸਹਾਇਤਾ ਰਾਹੀਂ ਪਰਿਵਾਰਕ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਅਤੇ ਰਵਾਇਤੀ ਢਾਂਚਿਆਂ ਦੀ ਸੰਭਾਲ।",
    "mukhyaTrusteePage.credAreaOfWork": "ਕਾਰਜ ਖੇਤਰ",

    "advisoryBoardPage.breadcrumbCurrent": "ਸਲਾਹਕਾਰ ਬੋਰਡ",
    "advisoryBoardPage.heroTitle": "ਸਲਾਹਕਾਰ ਬੋਰਡ",
    "advisoryBoardPage.heroDesc": "ਕਾਨੂੰਨੀ ਪਾਲਣਾ ਅਤੇ ਸਨਾਤਨ ਕਦਰਾਂ-ਕੀਮਤਾਂ ਪ੍ਰਤੀ ਸਖ਼ਤ ਵਚਨਬੱਧਤਾ ਨਾਲ ਸਾਡੇ ਕੰਮਕਾਜ ਦੀ ਅਗਵਾਈ ਕਰਨ ਵਾਲੇ ਤਜਰਬੇਕਾਰ ਦਿੱਗਜਾਂ, ਰਿਸ਼ੀਆਂ, ਕਾਨੂੰਨੀ ਮਾਹਿਰਾਂ ਅਤੇ ਉਦਯੋਗ ਮਾਹਿਰਾਂ ਨੂੰ ਮਿਲੋ।",
    "advisoryBoardPage.member1Role": "ਮੁੱਖ ਕਾਨੂੰਨੀ ਸਲਾਹਕਾਰ",
    "advisoryBoardPage.member1Dept": "ਟਰੱਸਟ ਕਾਨੂੰਨ ਅਤੇ ਧਰਮ ਕੋਡ",
