    "managementTeamPage.breadcrumbCurrent": "ਪ੍ਰਬੰਧਨ ਟੀਮ",
    "managementTeamPage.heroTitle": "ਪ੍ਰਬੰਧਨ ਟੀਮ",
    "managementTeamPage.heroDesc": "ਬਾਬਾ ਸ਼੍ਯਾਮ ਦੀ ਦਿਵਯ ਕਿਰਪਾ ਹੇਠ ਸੰਸਥਾ ਦੀਆਂ ਰੋਜ਼ਾਨਾ ਗਤੀਵਿਧੀਆਂ ਦੇ ਪ੍ਰਬੰਧਨ ਅਤੇ ਸੰਚਾਲਨ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਪੇਸ਼ੇਵਰਾਂ ਨੂੰ ਮਿਲੋ।",
    "managementTeamPage.member1Role": "ਸੰਚਾਲਨ ਨਿਰਦੇਸ਼ਕ",
    "managementTeamPage.member1Dept": "ਸੰਚਾਲਨ",
