    "managementTeamPage.member2Role": "ਮੁੱਖ ਵਿੱਤੀ ਅਧਿਕਾਰੀ",
    "managementTeamPage.member2Dept": "ਵਿੱਤ ਅਤੇ ਖਾਤੇ",
    "managementTeamPage.member2Desc": "ਸਮਰਪਿਤ ਟਰੈਕਿੰਗ ਪ੍ਰੋਟੋਕੋਲ ਨਾਲ ਦਾਨ ਵੰਡ, ਆਡਿਟ ਅਤੇ ਫੰਡ ਪਾਰਦਰਸ਼ਤਾ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਦੀ ਹੈ।",
    "managementTeamPage.member3Role": "ਤਕਨਾਲੋਜੀ ਮੁਖੀ",
    "managementTeamPage.member3Dept": "ਆਈਟੀ ਅਤੇ ਸਿਸਟਮ",
    "managementTeamPage.member3Desc": "ਆਨਲਾਈਨ ਡਾਇਰੈਕਟਰੀਆਂ, ਸ਼ਰਧਾਲੂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਡੇਟਾਬੇਸਾਂ ਅਤੇ ਸੁਰੱਖਿਅਤ ਆਨਲਾਈਨ ਭੁਗਤਾਨ ਗੇਟਵੇਅ ਨੂੰ ਬਣਾਈ ਰੱਖਦੇ ਹਨ।",
    "managementTeamPage.member4Role": "ਮੀਡੀਆ ਅਤੇ ਪੀਆਰ ਮੈਨੇਜਰ",
    "managementTeamPage.member4Dept": "ਸੰਚਾਰ",
    "managementTeamPage.member4Desc": "ਭਜਨ ਸੰਧਿਆ ਪ੍ਰਸਾਰਣ, ਲਾਈਵ ਪ੍ਰਸਾਰਣ ਦਾ ਤਾਲਮੇਲ ਕਰਦੇ ਹਨ ਅਤੇ ਮਹੀਨਾਵਾਰ ਅਧਿਆਤਮਿਕ ਨਿਊਜ਼ਲੈਟਰ ਅੱਪਡੇਟ ਕਰਦੇ ਹਨ।",
    "managementTeamPage.member5Role": "ਭਾਈਚਾਰਕ ਸੇਵਾ ਮੁਖੀ",
    "managementTeamPage.member5Dept": "ਆਊਟਰੀਚ",
    "managementTeamPage.member5Desc": "ਸ਼ਰਧਾਲੂ ਮੈਡੀਕਲ ਰਾਹਤ ਕੈਂਪਾਂ, ਭੋਜਨ ਵੰਡ ਅਤੇ ਵਲੰਟੀਅਰ ਤੈਨਾਤੀ ਯੋਜਨਾਵਾਂ ਚਲਾਉਂਦੀ ਹੈ।",
    "managementTeamPage.member6Role": "ਜਨਰਲ ਕਾਨੂੰਨੀ ਸਲਾਹਕਾਰ",
    "managementTeamPage.member6Dept": "ਕਾਨੂੰਨੀ ਅਤੇ SLA",
    "managementTeamPage.member6Desc": "ਟਰੱਸਟ ਪ੍ਰਮਾਣੀਕਰਨ, ਜ਼ਮੀਨ ਪ੍ਰਬੰਧਨ ਅਤੇ ਵਿਧਾਨਕ ਢਾਂਚਿਆਂ ਲਈ ਢਾਂਚਾਗਤ ਪਾਲਣਾ ਯਕੀਨੀ ਬਣਾਉਂਦੇ ਹਨ।",

    "trusteesPage.breadcrumbCurrent": "ਟਰੱਸਟੀ",
    "trusteesPage.heroTitle": "ਸਾਡੇ ਟਰੱਸਟੀ",
    "trusteesPage.heroDesc": "ਸ਼੍ਰੀ ਸ਼੍ਯਾਮ ਜਗਤ ਟਰੱਸਟੀ ਬੋਰਡ ਵਿੱਚ ਪ੍ਰਮੁੱਖ ਆਗੂ, ਅਧਿਆਤਮਿਕ ਸੁਧਾਰਕ ਅਤੇ ਪਰਉਪਕਾਰੀ ਸ਼ਾਮਲ ਹਨ ਜੋ ਸਾਡੇ ਪਾਰਦਰਸ਼ੀ ਸਮਾਜਿਕ ਪ੍ਰੋਗਰਾਮਾਂ ਦਾ ਸੰਚਾਲਨ ਕਰਦੇ ਹਨ।",
    "trusteesPage.trustee1Desc": "ਆਈਟੀ ਤਬਦੀਲੀ, ਮੰਦਰ ਤਸਦੀਕ ਨੈੱਟਵਰਕ ਅਤੇ ਡਾਟਾ ਪਾਰਦਰਸ਼ਤਾ ਪ੍ਰੋਗਰਾਮਾਂ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦੇ ਹਨ।",
    "trusteesPage.trustee2Desc": "ਵਿੱਤੀ ਆਡਿਟ, ਕਾਨੂੰਨੀ ਪਾਲਣਾ ਅਤੇ ਵੱਡੇ ਫੰਡ ਵੰਡ ਦਾ ਨਿਰਦੇਸ਼ਨ ਕਰਦੇ ਹਨ।",
    "trusteesPage.trustee3Desc": "ਵਲੰਟੀਅਰ ਲਾਮਬੰਦੀ, ਕਾਰਪੋਰੇਟ ਸਮਾਜਿਕ ਜ਼ਿੰਮੇਵਾਰੀ (CSR) ਭਾਈਵਾਲੀ ਅਤੇ ਸੱਭਿਆਚਾਰਕ ਸਮਾਗਮਾਂ ਦੀ ਨਿਗਰਾਨੀ ਕਰਦੀ ਹੈ।",
    "trusteesPage.trustee4Desc": "ਮੱਧ ਭਾਰਤ ਵਿੱਚ ਭੋਜਨ ਵੰਡ ਨੈੱਟਵਰਕ ਅਤੇ ਮੋਬਾਈਲ ਸਿਹਤ ਕਲੀਨਿਕਾਂ ਦਾ ਤਾਲਮੇਲ ਕਰਦੇ ਹਨ।",
    "trusteesPage.trustee5Desc": "ਮਿਆਰੀ ਅਧਿਆਤਮਿਕ ਸਾਹਿਤ ਪ੍ਰਕਾਸ਼ਨ ਅਤੇ ਭਜਨ ਕਲਾਕਾਰ ਤਾਲਮੇਲ ਨੂੰ ਸਰਪ੍ਰਸਤੀ ਦਿੰਦੀ ਹੈ।",
    "trusteesPage.trustee6Desc": "ਪ੍ਰਾਚੀਨ ਹੱਥ-ਲਿਖਤਾਂ ਅਤੇ ਮੰਦਰ ਸੰਗੀਤ ਪਰੰਪਰਾਵਾਂ ਦੀ ਵਿਰਾਸਤ ਸੰਭਾਲ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਦੇ ਹਨ।",
